special_days["Juldagen"] = special_days["Christmas Day"]
special_days["Annandag jul"] = special_days["Boxing Day"]
special_days["Nyårsafton"] = special_days["New Year's Eve"]

function get_special_day(visitdate, special_day_list)
	for _, d in pairs(special_day_list) do
		if special_days[d] == nil then
			error("Special day: " .. d .. " not recognized.\n\nspecial_days = " .. dump(special_days).."\n")
		end

		if special_days[d][visitdate] ~= nil then
			return d
		end
		if special_days[d].pattern ~= nil and string.find(visitdate, special_days[d].pattern) then
			return d
		end
	end
	return nil
end

