-- Generate this from the above master list. You can optionally remap continents on this list, using its code by using "continent_remap" at the root level of the conf.
-- Eg: {"continent_remap": [ {"cc":"TR", continents:["ASI"]} ]} remaps Türkiye to be only in Asia, whereas by default it's in both Asia and Europe.
local continent_countries = nil -- only generate if requested
local country_continents = {} -- reverse map
function GetContinentCountries()
	if continent_countries ~= nil then
		return continent_countries
	end

	-- Do the remap, before we create the master map
	if conf.continent_remap ~= nil then
		for _, entry in ipairs(conf.continent_remap) do
			for _, country_def in ipairs(country_continent_definitions) do
				if entry.cc == country_def.cc then
					country_def.continents = entry.continents
				end
			end
		end
	end

	-- Now create the master map.
	continent_countries = {}
	for _, continent_def in ipairs(continent_definitions) do
		continent_countries[continent_def.name] = continent_countries[continent_def.name] or {}
		for _, country_def in ipairs(country_continent_definitions) do
			for _, continent_code in ipairs(country_def.continents) do				
				if continent_def.code == continent_code then
					for _, country_name_variant in ipairs(country_def.names) do
						country_continents[country_name_variant] = country_continents[country_name_variant] or {}
						table.insert(country_continents[country_name_variant], continent_def.name)
						table.insert(continent_countries[continent_def.name], country_name_variant )
					end
				end
			end
      end
  end

	return continent_countries
end

local mostFoundCountry={}
local mostFoundRegion={}
local mostFoundCounty={}
local findsInCountry = {}
local findsInRegion = {}
local findsInCounty = {}
local matchingCountries = {}
local matchingRegions = {}
local matchingCounties = {}

function dump(o)
  if type(o) == 'table' then
     local s = '{ '
     for k,v in pairs(o) do
        if type(k) ~= 'number' then k = '"'..k..'"' end
        s = s .. '['..k..'] = ' .. dump(v) .. ','
     end
     return s .. '} '
  else
     return tostring(o)
  end
end

function DebugPrint(a)
	if conf.debug==true then
		-- only put timings on things with newlines
		if string.sub(a,-1)=='\n' then
			a = "["..(os.time()-start_time).."s]"..a
		end
		PGC.print(a)
		PGC.Log(a)
	end
end

function error_if(e, msg)
	if e then 
		error(msg) 
	end
end

function error_if_table_fields(table_name, tbl, expected_fields, required_fields)
	local missing_required = {}
	local extra_fields = {}
	for _, rf in ipairs(required_fields or {}) do
		if tbl[rf] == nil then
			table.insert(missing_required, rf)
		end
	end
	for _, k in ipairs(keys(tbl)) do
		if find_in_list(k, expected_fields or {}) < 1 then
			table.insert(extra_fields, k)
		end
	end

	local error_string = 
		(#extra_fields == 0 and "" or "contains extra field(s):" .. table.concat(extra_fields, ", ")) ..
		(#missing_required == 0 and "" or "missing required field(s):" .. table.concat(missing_required, ", "))
		
	error_if(#extra_fields > 0 or #missing_required > 0, table_name .. " " .. error_string)
end

function PrintFindsText(finds,limit,fields,row_style_fn, no_header)

	local count=0
	local res={}

	if not no_header then
		table.insert(res,table.concat(fields," "))
	end

	for _,c in ipairs(finds) do
		if row_style_fn == nil or row_style_fn(c) ~= nil then		
			local tmp={}
			for n,k in ipairs(fields) do
				-- if the field contains 'gccode' assume that it's a code and make it a link
				if k == "n" and c[k] == nil then
					table.insert(tmp, count+1)
				else
					table.insert(tmp,c[k])
				end
			end
			table.insert(res,table.concat(tmp," "))

			count=count+1
			if count>=limit then
				break
			end
		end		
	end
    res=table.concat(res,"\n")
return res
end -- end function PrintFindsText
