function PrintFindsHtml(finds,limit,fields,no_header, row_style_fn,print_field_tags)

	local res={}
	local count=0
	table.insert(res,"<table class=\""..g_table_class.."\" style='padding:0px'>")
	if not no_header then
		table.insert(res,"<tr class='bg-light text-dark' style='border:1px'>")
		for _, f in ipairs(fields) do
			local field_style = nil
			if f == 'icon' or f=='type_icon' or f == 'n' then
				field_style = "width:32px"
			elseif f == 'country' then 
				field_style = "width:122px"
			elseif f ~= 'cache_name' then 
				field_style = "width:100px;"
			end
			local field_style_tag = (field_style ~=nil and "style='".. field_style.."'" or "")
			table.insert(res,"<th " .. field_style_tag .. ">" .. f .."</th>")
		end
		table.insert(res,"</tr>")
	end

	for _,c in ipairs(finds) do
		local tmp={}
		function print_find()
			for n,k in ipairs(fields) do
				-- if the field contains 'gccode' assume that it's a code and make it a link
				if string.find(k,'gccode') ~= nil then
					table.insert(tmp,"<a href='http://coord.info/"..tostring(c[k]).."'>"..tostring(c[k]).."</a>")
				elseif k=='visitdate' then
					if (tonumber(c['log_id']) ~= nil) then
						table.insert(tmp,"<a href='http://coord.info/GL"..id_to_gccode(tonumber(c['log_id'])).."'>"..c[k].."</a>")
					elseif c[k] ~= nil then
						table.insert(tmp,c[k])
					else
						table.insert(tmp,"N/A")
					end
				elseif k == "n" and c[k] == nil then
					table.insert(tmp, count+1)
				elseif k == "type_icon" or k=="icon" then
					table.insert(tmp, c.type and PGC.Icon.GeocacheType(c.type) or PGC.Icon.Stop(false))
				elseif k == "country" then
					table.insert(tmp, c.country and (PGC.Icon.CountryFlag(c.country) .. " " .. c.country) or PGC.Icon.Stop(false))
				elseif k == "attributes" then 
					local attributes = PGC.GetAttributeList()
					local attr_tag = "<div style='margin-bottom:2px' height='30'>"
					for _, attribute_index in ipairs(get_attribute_list(c)) do
						local negative = attribute_index > 96
						if (negative) then
							attribute_index = attribute_index-96
						end
						attr_tag = attr_tag .. attributes[attribute_index][negative and 'imageUnset' or 'imageSet']
					end
					attr_tag = attr_tag .. "</div>"
					table.insert(tmp, attr_tag)
				else
					table.insert(tmp,c[k] or "")
				end

				if print_field_tags and print_field_tags[n] and print_field_tags[n] ~= "" then
					tmp[#tmp] = "<"..print_field_tags[n] ..">"..tmp[#tmp].."</"..print_field_tags[n]..">"
				end
			end
		end

		-- you can return nil as the style to have the cache not printed at all.
		local style = ""
		if row_style_fn ~= nil then
			style = row_style_fn(c)
		end

		local function print_error_handler(err)
			DebugPrint("When printing cache exception occurred. Cache will be ignored.\n")
			DebugPrint("Exception: " .. err .. "\n")
		end
		if not xpcall(function() return print_find() end, print_error_handler) then
			DebugPrint("Error printing cache. " .. dump(c) .. "\n")
			style = nil
		end

		if (style ~= nil) then
			table.insert(res,"<tr style='" .. style .. "'><td>"..table.concat(tmp,"</td><td>").."</td></tr>")
			count=count+1
			if count>=limit then
				break
			end
		end
	end
	table.insert(res,"</table>")
    res=table.concat(res,"\n")

	if count == 0 then
		return ""
	end

	return res
end --end function PrintFindsHtml
