-- Given a bit index, get the value if that bit was set to 1
-- e.g.  given 4, set the fourth bit from the right to 1.  Result:  8
function bit(p)
    return 2 ^ (p - 1)  -- 1-based indexing
end

-- Given a bitfield and bitmask, AND the two to determine if the bitmask is set in this field.
function hasbit(x, p)
    return x % (p + p) >= p
end

function rshift(x, by)
    return math.floor(x / 2 ^by )
end

function attribute_short_name_to_index(attr)
	if (type(attr) == 'string') and tonumber(attr)==nil then
		local negative = string.sub(attr, 1, 3) == "no-"
		local attribute_short = negative and string.sub(attr,4) or attr
		for _, def in ipairs(attribute_definitions) do
			if def.short == attribute_short then
				attr = def.n + (negative and 96 or 0)
				return attr
			end
		end
	end
	return tonumber(attr)
end

-- Returns all attributes that a cache has a list of numbers.
function get_attribute_list(cache)
	local attributes = {}
	for attribute = 1, 32*6 do
		local setindex = rshift((attribute-1) % 96, 5)+1
		local bitindex = ((attribute-1) % 32)+1
		local attributeset = (attribute <= 96 and "attributes_set_" or "attributes_unset_") .. setindex
		if hasbit(cache[attributeset], bit(bitindex)) then
			table.insert(attributes, attribute)
		end
	end
	return attributes
end

function get_positive_attribute_numbers()
	local attrs = PGC.GetAttributeList()
	local fieldVals = {}
	for attributeNumber, attrDesc in pairs(attrs) do
		table.insert(fieldVals, attributeNumber)
	end
	return fieldVals
end

function get_negative_attribute_numbers()
	-- doesn't seem to be a reliable way to get negative attributes... so, here's a hardcoded list.
	return {97,102,103,104,105,106,109,110,111,113,120,121,123,124,125,126,127,128,129,130,131,132,133,134,136,137,142,143,148,149,150,151,152,153,154,155,159,160,161,162}
end

function get_attribute_numbers()
	local fieldVals = get_positive_attribute_numbers()

	-- doesn't seem to be a reliable way to get negative attributes... so, here's a hardcoded list.
	for _, negative_attribute in ipairs(get_negative_attribute_numbers()) do
		table.insert(fieldVals, negative_attribute)
	end
	return fieldVals
end

function cache_passes_attribute_filter(find, filter)
    if (filter.func == 'and') then
		local result = true
		for _,opt in ipairs(filter.opt) do
        	result = result and cache_passes_attribute_filter(find, opt)
		end
		return result
    elseif (filter.func == 'or') then
		local result = false
		for _,opt in ipairs(filter.opt) do
        	result = result or cache_passes_attribute_filter(find, opt)
		end
		return result
    elseif (filter.func == 'set') then
		-- If it's a string, but isn't a number, assume it's a short name for attributes
		filter.opt.attribute = attribute_short_name_to_index(filter.opt.attribute)
        local setindex = rshift((filter.opt.attribute-1) % 96, 5)+1
        local bitindex = ((filter.opt.attribute-1) % 32)+1
        local attributeset = (filter.opt.attribute <= 96 and "attributes_set_" or "attributes_unset_") .. setindex
        local cmp = true
		if filter.opt.value == false then
			cmp = false
		end

		if find[attributeset] == nil then
			DebugPrint(dump(find) .. " " .. attributeset .. " " .. bitindex .. "\n")
		end

        return cmp == hasbit(find[attributeset], bit(bitindex))	
	elseif (filter.func =='n') then
		local op = filter.opt.op or "eq"
		local count = 0
		for pos = 1,2 do
			local setunset = pos==1 and "attributes_set_" or "attributes_unset_"
			for setindex = 1,3 do
				local attributeset = setunset .. setindex
				for bitindex = 1,32 do
					if hasbit(find[attributeset], bit(bitindex)) then
						count = count +1
					end
				end
			end
		end

		if op == 'eq' then
			return count == filter.opt.n
		elseif op =='lte' then
			return count <= filter.opt.n
		elseif op =='gte' then
			return count >= filter.opt.n
		else
			error ('op = ' .. (filter.opt.n or "nil") .. " unsupported.")
		end
  	end
    return true
end

