-- Adapted from SameX DifferentY script by GreyHams

-- This is the "Nth" week of geocaching.
function week_number (date, startsonmonday)
  local geocaching_date_format = Date.Format "yyyy-mm-dd"
  local mydate = geocaching_date_format:parse (date)
  local daten = math.floor (mydate.time/86400)
  local offset = 10951
  if startsonmonday then offset = offset + 1 end
  return math.floor((daten-offset)/7)
end

function day_of_week(day, startsonmonday)
	if day=='Mon' then
		return startsonmonday and 0 or 1
	elseif day=='Tue' then
		return startsonmonday and 1 or 2
	elseif day=='Wed' then
		return startsonmonday and 2 or 3
	elseif day=='Thu' then
		return startsonmonday and 3 or 4
	elseif day=='Fri' then
		return startsonmonday and 4 or 5
	elseif day=='Sat' then
		return startsonmonday and 5 or 6
	elseif day=='Sun' then
		return startsonmonday and 6 or 0
	else
		error("'day' must be Mon-Sun.")
	end
end

-- This returns the Nth week the date is contained in, in the year that it is in. Returns 1..N
function week_of_year(date, method)

	if method == nil then
		method = "normalized"
	end
    if type(method) ~= 'string' then
        DebugPrint('week_of_year method was not string, assuming iso8601')
        method= 'iso8601'
    end
	if method ~= "normalized" and method ~= "iso8601" then
		error("week_of_year must be either 'normalized' (week #1 is always Jan1-7) or 'iso8601'. But it was ".. (method or 'nil'))
	end
	
	local mydate = iso:parse(date)

	if method == "normalized" then
		-- 'normalized' means that Jan 1st-Jan7th is always the first week, 8-14 is always the second week, etc.
		local day_of_year = mydate:yday()
		return math.floor((day_of_year-1)/7)+1, 0

	elseif method == "iso8601" then

		-- ISO 8601 - https://en.wikipedia.org/wiki/ISO_week_date#Calculating_the_week_number_from_an_ordinal_date
		local ord = mydate:yday()
		local year = mydate:year()
		local dow = day_of_week(mydate:weekday_name(), true)+1
		local woy = math.floor((ord - dow + 10)/7)

		-- NOTE: return the week of year, AND the year delta (eg. if it's in the next year or the previous year)
		if woy < 1 then
			return weeks_in_year_iso8601(year-1), -1
		elseif woy > weeks_in_year_iso8601(year) then
			return 1, 1
		else
			return woy, 0
		end
	else
		error ("Unsupported week_of_year method:" .. method)
	end
end

function week_of_year_iso8601(date)
	local year = string.sub(date,1,4)
	local mydate = iso:parse (date)
	local woy, year_delta = week_of_year(date,"iso8601")
	year = year + year_delta
	return year .. "-W".. woy .. "-" .. (day_of_week(mydate:weekday_name(),true)+1)
end

function time_difference_minutes(start_str, end_str)

	if type(start_str) == 'boolean' or type(end_str) == 'boolean' then
		-- "Old" events didn't have a start/end time... so, no time duration.
		return 0
	end

	local timefmt = Date.Format "HH:MM:SS"
	local start_time = timefmt:parse(start_str)
	local end_time = timefmt:parse(end_str)
	local diff = (end_time.time - start_time.time)/60
	return diff
end

function date_range_includes_leapyear(min_date, max_date)
	local includes_leap_year = false
	local min_year = min_date and tonumber(string.sub(min_date,1,4)) or 2000				-- no min date, assume it's May 1st, 2000.
	local max_year = max_date and tonumber(string.sub(max_date,1,4)) or Date().tab.year		-- no max date, assume it's this year.

	-- If we cross a divided by 4 boundary, or we're on one, then this is a leap year.
	return math.floor(max_year/4) ~= math.floor(min_year/4) or (min_year==max_year and min_year%4==0)
end

function weeks_in_year_iso8601(year)
	local p_y = (year + math.floor(year/4) - math.floor(year/100) + math.floor(year/400)) % 7
	local weeks = 52 + ((p_y == 4) and 1 or 0)
	return weeks
end

function round(num, idp)
	local mult = 10^(idp or 0)
	return math.floor(num * mult + 0.5) / mult
end

function DateDiff(a, b)
	if(a ~= nil and b ~= nil) then
	  local d1 = iso:parse(a)
	  local d2 = iso:parse(b)

	  local diffDays = round((d2.time-d1.time)/86400)
	  diffDays=math.abs(diffDays)
	  return diffDays
	end
	return nil
  end

