	} 
	local iso_hm = Date.Format("yyyy-mm-dd HH:MM")
	full_moon_hash = {}
	-- Convert the chart above to actual parsable dates
	local nth_moon= 1
	for year, day_list in pairs(moon_phase_chart) do
		for _, day in ipairs(day_list) do
			local moon_date_time = year .. "-" .. day        
			local moon_date = iso:tostring(iso_hm:parse(moon_date_time))
			full_moon_hash[moon_date] = true
		end
	end


	for k,v in spairs(full_moon_hash) do
		full_moon_hash[k] = nth_moon
		nth_moon = nth_moon+1
	end

	full_moon_init = true
end

function nth_moon(date)
	init_full_moons()
	if full_moon_hash[date] ~= nil then
		return full_moon_hash[date]
	else
		return -1
	end
end

function get_age_in_days(date_string)
	local today=Date()
	local age_in_days = DateDiff(date_string, iso:tostring(today))
	return age_in_days
end

function need_binary(opt)
	local l={} 
	if opt.field then table.insert(l,opt.field) end 
	if opt.field_op then table.insert(l,opt.field_op) end
	return l
end

function need_ternary(opt)
	local l={} 
	if opt.condition_field then table.insert(l,opt.condition_field) end 
	if opt.field then table.insert(l,opt.field) end 
	if opt.field_op then table.insert(l,opt.field_op) end
	return l
end

function process_cmp(c, opt)
	local v0 = opt.field and c[opt.field] or opt.value
	local v1 = opt.field_op and c[opt.field_op] or opt.value_op
	return binary_comparison(opt.op, v0, v1)
end

function process_operation(c, opt)
	local v0 = opt.field and c[opt.field] or opt.value
	local v1 = opt.field_op and c[opt.field_op] or opt.value_op
	return binary_operation(opt.op, v0, v1)
end

function process_ternary(c, opt)
	local condition = opt.condition_field and c[opt.condition_field] or opt.condition
	local v0 = opt.field and c[opt.field] or opt.value
	local v1 = opt.field_op and c[opt.field_op] or opt.value_op
	return ternary_operation(condition, v0, v1)
end

function are_intersecting(v1x1, v1y1, v1x2, v1y2, v2x1, v2y1, v2x2, v2y2) 
    
    -- Convert vector 1 to a line (line 1) of infinite length.
    -- We want the line in linear equation standard form: A*x + B*y + C = 0
    -- See: http://en.wikipedia.org/wiki/Linear_equation
    local a1 = v1y2 - v1y1;
    local b1 = v1x1 - v1x2;
    local c1 = (v1x2 * v1y1) - (v1x1 * v1y2);

    -- Every point (x,y), that solves the equation above, is on the line,
    -- every point that does not solve it, is either above or below the line.
    -- We insert (x1,y1) and (x2,y2) of vector 2 into the equation above.
    local d1 = (a1 * v2x1) + (b1 * v2y1) + c1;
    local d2 = (a1 * v2x2) + (b1 * v2y2) + c1;

    -- If d1 and d2 both have the same sign, they are both on the same side of
    -- our line 1 and in that case no intersection is possible. Careful, 0 is
    -- a special case, that's why we don't test ">=" and "<=", but "<" and ">".
    if (d1 > 0 and d2 > 0) then return false end
    if (d1 < 0 and d2 < 0) then return false end

    -- We repeat everything above for vector 2.
    -- We start by calculating line 2 in linear equation standard form.
    local a2 = v2y2 - v2y1;
    local b2 = v2x1 - v2x2;
    local c2 = (v2x2 * v2y1) - (v2x1 * v2y2);

    -- Calulate d1 and d2 again, this time using points of vector 1
    local d1 = (a2 * v1x1) + (b2 * v1y1) + c2;
    local d2 = (a2 * v1x2) + (b2 * v1y2) + c2;

    -- Again, if both have the same sign (and neither one is 0),
    -- no intersection is possible.
    if (d1 > 0 and d2 > 0) then return false end
    if (d1 < 0 and d2 < 0) then return false end

    -- If we get here, only three possibilities are left. Either the two
    -- vectors intersect in exactly one point or they are collinear
    -- (they both lie both on the same infinite line), in which case they
    -- may intersect in an infinite number of points or not at all.
    if ((a1 * b2) - (a2 * b1) == 0) then return false end

    -- If they are not collinear, they must intersect in exactly one point.
    return true;
end

function is_inside_poly(find, poly, filename, setname)
	local lat = find.latitude
	local lon = find.longitude

	-- quick out, to see if the point is anywhere near to the poly.
	local find_distance_from_bbox = PGC.DistanceHaversine(lat, lon, poly.bbox.circle.center[1], poly.bbox.circle.center[2] )
	if find_distance_from_bbox > poly.bbox.circle.radius then
		return false
	end

	DebugPrint("Actually checking " .. string.format("%s against polyset %s-%s, because it is only %.2f away, and the bbox radius is %.2f\n", find.gccode, filename, setname, find_distance_from_bbox, poly.bbox.circle.radius))

	-- Actually do all the intersection checks.
	local e = poly.bbox.max[1] - poly.bbox.min[1];
	local raystart = {poly.bbox.min[1]-e, lon}
	local rayend = {lat, lon}
	local intersections = 0;
	for i, list in ipairs(poly.polypoints) do
	  local prevpoint = nil
	  for _, point in ipairs(list) do
		if prevpoint ~= nil then                                                
		  if are_intersecting(
				 raystart[1], raystart[2], rayend[1], rayend[2],
				 prevpoint[1], prevpoint[2], point[1], point[2]) then
					   intersections = intersections + 1
		  end
		end
		prevpoint = point
	  end
	end
	return intersections % 2 == 1
	
  end
  
function find_fails_polyset(find, polyset)
	if type(polyset) == 'table' then
		if #polyset == 0 then error("Used 'polyset', but it was not an array or string. Should be in the format <file>:<setname>.") end
		local pass = true
		for _, ps in ipairs(polyset) do
			pass = pass and not find_fails_polyset(ps)
		end
		return not pass
	else
		local filename,setname
		filename,setname = polyset:match("([^:]+):([^:]+)")
		if polyset == nil or setname == nil then error("polyset was in the wrong format ("..polyset.."). Should be <file>:<setname>.") end

		if (g_polyset_cache[filename] == nil) then
			g_polyset_cache[filename] = PGC.GetJsonData(filename)
			if (g_polyset_cache[filename] == nil or type(g_polyset_cache[filename])=='boolean') then error("No such polyset filename: " .. filename .. "\n") end			

			-- If the indexes are integers in json, they come out to be numbers in lua, but we want everything to be a string for consistency.
			local nonstring_sns = {}
			for sn, _ in pairs(g_polyset_cache[filename]) do 
				g_polyset_cache[filename][sn].accessed = false
				if type(sn) ~= 'string' then
					table.insert(nonstring_sns,sn)
				end
			end
			for _, nssn in ipairs(nonstring_sns) do
				g_polyset_cache[filename][tostring(nssn)] = g_polyset_cache[filename][nssn]
				g_polyset_cache[filename][nssn] = nil
			end
		end

		-- special case - you can put in a *, to mean all polysets within the file.
		if setname=='*' then
			local pass = true
			for name, _ in pairs(g_polyset_cache[filename]) do
				pass = pass and find_fails_polyset(filename..":"..name)
			end
			return not pass
		end

		if g_polyset_cache[filename][setname] == nil then 
			local sns = {}
			for sn, _ in pairs(g_polyset_cache[filename]) do table.insert(sns,sn) end
			error("Polyset filename " .. filename .. " did not contain a setname: " .. setname .. "\nSet names in that file are: "  .. table.concat(sns,"\n"))
		end

		-- pre-process the polyset, if we haven't done it before
		if g_polyset_cache[filename][setname].bbox == nil then
			g_polyset_cache[filename][setname].accessed = true
			local poly = g_polyset_cache[filename][setname]
			poly.bbox = {max={},min={}}					
			for _, point_list in ipairs(g_polyset_cache[filename][setname].polypoints) do
				for _, coord in ipairs(point_list) do
					for i, value in ipairs(coord) do
						poly.bbox.max[i] = math.max(value, poly.bbox.max[i] or -math.huge)
						poly.bbox.min[i] = math.min(value, poly.bbox.min[i] or math.huge)		
					end
				end
			end
			
			local bbw = (poly.bbox.max[1]-poly.bbox.min[1])
			local bbh = (poly.bbox.max[2]-poly.bbox.min[2])
			local bbcx = poly.bbox.min[1] + bbw/2
			local bbcy = poly.bbox.min[2] + bbh/2
			poly.bbox.circle = {center={bbcx, bbcy}, radius= PGC.DistanceHaversine(bbcx, bbcy,bbcx+bbw/2,bbcy+bbh/2)}
			DebugPrint("Processed " .. string.format("%s-%s: %s", filename, setname, dump(poly.bbox)).."\n")
		end

		return not is_inside_poly(find, g_polyset_cache[filename][setname], filename, setname)
	end
end

function cache_is_in_bookmark_list(cache, bookmark_list)
	error_if(bookmark_list == nil, "bookmark_list is nil")
	local download_result = PGC.GetBookmarklist(bookmark_list, {useCache=true})
	if type(download_result) ~= 'table'then
		DebugPrint("Bookmarklist download failed. Result( " .. dump(bookmark_list) .. ")\n")		 
		return false
	else
		for _, bookmark_gccode in ipairs(download_result) do
			if cache.gccode == bookmark_gccode then 
				return true 
			end
		end
	end
	return false
end

