	, ["first_day_of_month"]        = {["name"]="True, if first day of the month",["need"]=function(opt) return opt.field end,["read"]=function(c,opt) local d = iso:parse(c[opt.field]); return tonumber(d.tab.day) == 1 end }
	, ["last_day_of_mmdd"]          = {["name"]="True, if last day of the month (any year)",["need"]=function(opt) return opt.field end,["read"]=function(c,opt) local d = iso:parse((opt.leapday and "2000" or "2001") ..'-'.. c[opt.field]); local ld = Date(d); return tonumber(ld:last_day().tab.day) == tonumber(d.tab.day) end }
	, ["first_day_of_mmdd"]         = {["name"]="True, if first day of the month (any year)",["need"]=function(opt) return opt.field end,["read"]=function(c,opt) local d = iso:parse((opt.leapday and "2000" or "2001") ..'-'.. c[opt.field]); return tonumber(d.tab.day) == 1 end }
	, ["delta_days"]       			= {["name"]="Returns the day N days the input (-1 = yesterday, +1 = tomorrow)",["need"]=function(opt) return opt.field end,["read"]=function(c,opt) local d = iso:parse(c[opt.field]); d:add({day=opt.delta}); return iso:tostring(d) end }

