	, ["regex"]						= {["name"]="Regex matches (extended)",["need"]=function(opt) return opt.field end,["read"]=function(c,opt) return regex_match(c[opt.field], opt.pattern, opt.case_insensitive, opt.whole_word) ~= nil end, ["desc"]=function(opt) return opt.pattern end }
	, ["gsub"]						= {["name"]="string.gsub",["need"]=function(opt) return opt.field end,["read"]=function(c,opt) return string.gsub(c[opt.field], opt.pattern, opt.replace) end }
	, ["upper"]						= {["name"]="string.upper",["need"]=function(opt) return opt.field end,["read"]=function(c,opt) return c[opt.field]:upper() end }
	, ["lower"]						= {["name"]="string.lower",["need"]=function(opt) return opt.field end,["read"]=function(c,opt) return c[opt.field]:lower() end }
	, ["choice"]				    = {["name"]="Or",["need"]=function(opt) return opt.field end,["read"]=function(c,opt) return c[opt.field]==opt.value and opt.true_value or opt.false_value end }
	, ["add"]				        = {["name"]="Add",["need"]=function(opt) return {opt.field1,opt.field2} end,["read"]=function(c,opt) return tonumber(c[opt.field1]) + tonumber(c[opt.field2]) end }
	, ["gmatch"]					= {["name"]="string.gmatch",["need"]=function(opt) return opt.field end, ["read"]=function(c,opt) local w={}; for n in string.gmatch(c[opt.field], opt.pattern) do table.insert(w,n) end return w end}
	, ["create_list"]				= {["name"]="Create a list from multiple fields",["need"]=function(opt) return opt.fields end, ["read"]=function(c,opt) local r = {}; for _,f in ipairs(opt.fields) do table.insert(r, c[f]); end return r end}
	, ["iso8601_week"]				= {["name"]="ISO8601 week number date",["need"]=function(opt) return opt.field end, ["read"]=function(c,opt) return week_of_year_iso8601(c[opt.field]) end }
	, ["owner_name"]				= {["name"]="Owner name",["need"]='owner_id', ["read"]=function(c,opt) return PGC.ProfileId2Name(c.owner_id) end }		
