	, ["attribute_not_set"]			= {["name"]="Find has the attribute",["need"]={'attributes_set','attributes_unset'}, ["read"]=function(c,opt) return not cache_passes_attribute_filter(c, {func='set',opt={attribute=opt.attribute}}) end }

	, ["most_found_country"]		= {["name"]="Most found country (bool)",["need"]={'country'}, ["read"]=function(c) calculateMostFound() return cache_is_in_most_found_area(c, 'country') end }
