	, ["cmp"]						= {["name"]="Perform binary comparison on input.",["need"]=function(opt) return need_binary(opt) end,["read"]=function(c,opt) return process_cmp(c,opt) end}
	, ["op"]						= {["name"]="Perform binary operation on input.",["need"]=function(opt) return need_binary(opt) end,["read"]=function(c,opt) return process_operation(c,opt) end}
	, ["uniary_op"]					= {["name"]="Perform uniary operation on input.",["need"]=function(opt) return opt.field end,["read"]=function(c,opt) return uniary_operation(opt.op, c[opt.field]) end}
	, ["ternary"]					= {["name"]="Perform ternary (select) on inputs.",["need"]=function(opt) return need_ternary(opt) end,["read"]=function(c,opt) return process_ternary(c, opt) end}
	, ["literal"]					= {["name"]="Assign a literal value to a field",["need"]={}, ["read"]=function(c,opt) return opt.value end}
	, ["format"]					= {["name"]="Format a field using string.format",["need"]=function(opt) return unpack(opt.field) end,["read"]=function(c,opt) local fields = {} for _, f in ipairs(opt.field) do table.insert(fields, c[f]) end string.format(opt.format, unpack(fields)) end}

	, ["prev_find"]					= {["name"]="Copy a field from the last find into this one",["need"]=function(opt) return opt.field end,["read"]=function(c,opt,prev_find) return prev_find and prev_find[opt.field] or nil end }
	}

local cell_function_def
cell_function_def =
{
	-- size of the list
	["n"]			= 	function(l) return #l end

	-- perform a binary operation on all fields for the entires in the list.
	,["list_op"]	= 	function(l, opt)
							-- if it's a multiply or divide, start with 1 instead of zero.
							local result = (opt.op == '*' or opt.op == '/') and 1 or 0
							for _, e in ipairs(l) do
								result = binary_operation(opt.op, result, e[opt.field])
							end
							return result
						end

	-- perform a binary operation the values of two tests
	,["op"]			=	function(l, opt)
							local f1_result = cell_function_def[opt.func[1].func](l, opt.func[1].opt)
							local f2_result = cell_function_def[opt.func[2].func](l, opt.func[2].opt)
							f1_result = math_clamp(f1_result, opt.func[1].opt.min or -math.huge, opt.func[1].opt.max or math.huge)
							f2_result = math_clamp(f2_result, opt.func[2].opt.min or -math.huge, opt.func[2].opt.max or math.huge)
							DebugPrint("processing "..f1_result.." "..opt.op .." " .. f2_result .. "\n")
							return binary_operation(opt.op, f1_result, f2_result)
						end

	-- number of unique values for fields in the list
	,["unique_n"]	= 	function(l,opt) 
							local unique_vals = {}
							local unique_n = 0
							for _,c in ipairs(l) do
								if opt.field and c[opt.field] and unique_vals[c[opt.field]] == nil then
									unique_n = unique_n + 1
									unique_vals[c[opt.field]] = true
								end
							end
							return unique_n
						end

	-- maximum value of a field in the list
	,["max"]		= function(l,opt)
						local max = -math.huge
						for _,c in ipairs(l) do
							max = math.max(c[opt.field],max)
						end
						return max
					end

	-- minimum value of a field in the list
	,["min"]		= function(l,opt)
						local min = math.huge
						for _,c in ipairs(l) do
							min = math.min(c[opt.field],min)
						end
						return min
					end
}

function collect_opt_fields(cell_fn, field_list)
	if cell_fn and cell_fn.opt then
		if cell_fn.opt.field then
			insert_into_list_if_unique(cell_fn.opt.field, field_list)
		elseif cell_fn.func == "op" then
			collect_opt_fields(cell_fn.opt.func[1], field_list)
			collect_opt_fields(cell_fn.opt.func[2], field_list)
		end
	end
end


function insert_function_needs_into_list(func, opt, list, need_value)
	local need = need_value or function_def[func].need
	if type(need) == 'table' then
		for _, nf in ipairs(need) do
			insert_into_list_if_unique(nf, list)
		end
	elseif type(need) =='string' then
		DebugPrint("how can we stack overflow from here? "..dump(need).." " ..dump(list).."\n")
		insert_into_list_if_unique(need, list)
	elseif type(need)=='function' then
		if opt == nil then
			error("You must specify the opt member for function (usually to indicate the field the transform is working on.)")
		end
		insert_function_needs_into_list(func, opt, list, need(opt))
	else
		error("'need' is invalid." .. func .. " " .. (dump(opt)) .. "\n")
	end
end

function preprocess_transforms(transforms, fields_required)

	DebugPrint("preprocess_transforms begin\n")
	if transforms ~= nil and type(transforms) ~= 'table' then
		error("You specified transforms, but they weren't a table, which is an error.")
	end

	-- Go through all the transforms, and gather the 'need' fields
	for _, transform in ipairs(transforms or conf.default_transforms or {}) do
		if function_def[transform.func] == nil then
			error ("specified transform: "..transform.func..", but it isn't found.")
		end
		insert_function_needs_into_list(transform.func, transform.opt, fields_required)
		DebugPrint("finished preprocess_transforms: " .. transform.func .. "\n")
	end

	DebugPrint("finished preprocess_transforms: " .. dump(transforms) .. "\n")
end

-- For future expansion, you can transform fields on finds into other fields
function field_transform(func, opt, finds)
	local prev_find = nil
	local invalid_cache_indices = {}
	for find_index,f in ipairs(finds) do
		if function_def[func] == nil then
			error("You specified an invalid function " .. func .. "\n")
		end
		if function_def[func].read == nil then
			error("You specified transform " .. func .. " but it doesn't seem to have an associated function\n.")
		else
			local function wrapped_transform(func, opt, f, prev_find)
				local outfield = opt and opt.outfield or func
				f[outfield] = function_def[func].read(f, opt, prev_find)
			end
			local function transform_error_handler(err)
				DebugPrint("When applying transform " .. func .. " to cache " .. f.gccode .. " an exception occurred. Cache will be ignored.\n")
				DebugPrint("Exception: " .. err .. "\n")
			end
			if not xpcall(function() return wrapped_transform(func, opt, f, prev_find) end, transform_error_handler) then
				table.insert(invalid_cache_indices, find_index)
			else
				prev_find = f
			end
		end
	end

	-- If any caches failed transform, remove them from the list now. Note: indices should be back to front, so removing them won't invalidate the next one.
	for _, invalid_index in ipairs(invalid_cache_indices) do
		table.remove(finds, invalid_index)
	end
end

function apply_transforms(transforms, finds)
	local f = nil
	for _, transform in ipairs(transforms or conf.default_transforms or {}) do
		f = transform.func or f
		if f == nil then 
			error("No function specified, and no previous function to use.")
		end
		DebugPrint("Applying transform " .. f .. " " .. dump(transform.opt) .."\n")
		field_transform(f, transform.opt, finds)
	end
end

-----------------------------------------------------
function calculate_points(conf, ok, n)

	-- Use the new method, if everything aligns
	if type(n) == 'table' then
		if conf.points ~= nil then
			return calculate_points_list(conf, ok, n)
		else
			-- Old method, just use the number in the list.
			DebugPrint("Using old method for calculating points, using the number of items in the list.\n")
			n = #n
		end
	end

	local points = conf.pointsPer ~= nil and 0 or nil
	local maxPoints = conf.maxPoints or math.huge
	local skipPoints = conf.skipPoints or 0
	local require_pass = get_default(conf.pointsRequirePass, true)
	if (not require_pass or ok) and conf.pointsPer ~= nil then
		points = conf.pointsPer * n
		points = math.min(maxPoints, math.max(points - skipPoints, 0))
	end
	return points
end
-----------------------------------------------------
function calculate_points_list(conf, ok, list)

	error_if(conf.points == nil, "Expected that conf.points is provided. (func, opt:{}, max_points, skip_points, points_require_pass)")
	error_if_table_fields("points", conf.points, {"func","opt","max_points","skip_points","points_require_pass","fail_points"} )
	local maxPoints = conf.points.max_points or math.huge
	local skipPoints = conf.points.skip_points or 0
	local require_pass = get_default(conf.points.points_require_pass, true)
	local points_op = conf.points.func or "n"
	local fail_points = conf.points.fail_points or 0

	error_if(cell_function_def[points_op]==nil, points_op .. " was not a valid function (valid = "..table.concat(keys(cell_function_def),", ")..")")
	local points = 0
	local list_points = cell_function_def[points_op](list, conf.points.opt) * (conf.points.opt and conf.points.opt.scale or 1)
	if (not require_pass or ok) then
		points = math.min(maxPoints, math.max(list_points - skipPoints, 0))
	end

	DebugPrint("calculting new points: " .. points .. " (list_points = "..list_points..")" .. dump(conf.points).."\n")
	return points
end
-----------------------------------------------------
function insert_into_list_if_unique(value, list)
	if (list == nil) then
		return
	end
	for i,v in ipairs(list) do
		if (v == value) then
			return
		end
	end
	table.insert(list, value)
end

-----------------------------------------------------
function math_clamp(v, min, max)
	if v < min then
		return min
	elseif v > max then
		return max
	end
	return v
end
-----------------------------------------------------
function insert_in_list_if_unique_field(value, field, list)
	local index = find_in_list_by_field(value, field, list)
	if index <= 0 then
		table.insert(list, value)
	end
end
-----------------------------------------------------
function insert_in_list_if_unique_fields(value, fields, list)
	if find_in_list_by_fields(value, fields, list) <= 0 then
		table.insert(list, value)
	end
end

---------------------------------------------------------------------------------------
function binary_comparison(op, v0, v1)

	local is_equality_op = (op == 'eq' or op == '=' or op == 'ne' or op == '~=' or op == '!=')

	if (not is_equality_op) and (v0 == nil or v1 == nil) then
		DebugPrint("One or both values was nil for comparison (".. dump(v0) .. " " .. op .. " " .. dump(v1) .. "). Assuming failure.\n")
		return false
	end

	if op == 'eq' or op == '=' then
		return v0 == v1
	elseif op == 'ne' or op == '~=' or op == '!=' then
		return v0 ~= v1
	elseif op == 'lt' or op == '<' then
		return v0 < v1
	elseif op == 'lte' or op == '<=' then
		return v0 <= v1
	elseif op == 'gt' or op == '>' then
		return v0 > v1
	elseif op == 'gte' or op == '>=' then
		return v0 >= v1
	else
		error("Need to supply op (was " .. dump(op) .. ", should be one of eq/ne/lt/lte/gt/gte)")
	end
end
---------------------------------------------------------------------------------------
function binary_search(list, gen_fn, op, target)
	local left = 1
	local right = #list
	local result = 0
	DebugPrint("binary_search: #list="..#list.." op=".. op .. " target=" .. target .. "\n")

	while left <= right do
		local mid = math.floor(left + (right-left)/2)
		local value = gen_fn(list[mid])
		DebugPrint("\t"..mid.." " .. value .."\n")

		if binary_comparison(op, value, target) then
			result = mid
		end
		if value <= target then
			left = mid +1
		else
			right = mid- 1
		end
	end

	return result
end
-----------------------------------------------------
function ternary_operation(selector, v0, v1)
	if selector then
		return v0
	else
		return v1
	end
end

-----------------------------------------------------
function binary_operation(op, v0, v1)
	if op == '+' then
		return v0 + v1
	elseif op == '-' then
		return v0 - v1
	elseif op == '*' then
		return v0 * v1
	elseif op == '/' then
		return v0 / v1
	elseif op == '%' then
		return v0 % v1
	elseif op == 'or' then
		return v0 or v1
	elseif op == 'and' then
		return v0 and v1
	elseif op == 'min' then
		return math.min(v0,v1)
	elseif op == 'max' then
		return math.max(v0,v1)
	elseif op == 'concat' then
		return tostring(v0) .. tostring(v1)
	else
		error("Unknown op used: ".. op .. ". Known are: +-/*% and min/max/concat")
	end
	return v0
end
-----------------------------------------------------
function uniary_operation(op, v0)
	if op=='floor' then
		return math.floor(v0)
	elseif op=='ceil' then
		return math.ceil(v0)
	elseif op=='abs' then
		return math.abs(v0)
	elseif op=='eq' then
		return v0 -- used to assign one field to another
	elseif op=='not' then
		return not v0
	else
		error("Unknown op used: ".. op .. ". Known are: floor/ceil/abs.")
	end
	return v0
end
-----------------------------------------------------
function regex_match(str, pattern, case_insensitive, whole_word)
	case_insensitive = case_insensitive or g_global_opts.regex_case_insensitive
	whole_word = case_insensitive or g_global_opts.regex_whole_word

	-- https://stackoverflow.com/questions/11401890/case-insensitive-lua-pattern-matching
	function case_insensitive_pattern(pattern)
		-- find an optional '%' (group 1) followed by any character (group 2)
		local p = pattern:gsub("(%%?)(.)", function(percent, letter)
			if percent ~= "" or not letter:match("%a") then
				-- if the '%' matched, or `letter` is not a letter, return "as is"
				return percent .. letter
			else
				-- else, return a case-insensitive character class of the matched letter
				return string.format("[%s%s]", letter:lower(), letter:upper())
			end
		end)

		return p
	end

	pattern = case_insensitive and case_insensitive_pattern(pattern) or pattern
	if whole_word then
		pattern = "%f[%a%d]" .. pattern .. "%f[^%a%d]"
	end
	
	return string.find(str, pattern)
end
-----------------------------------------------------
function determine_args_version()
	if args == nil or args[1] == nil or args[1].gccode == nil or args[1].gccode == 'GC0' then
		return 5
	elseif args[1].gccode >= 'GCBYF2M' then
		return 5
	elseif args[1].gccode >= 'GCBDYKM' then
		return 4
	elseif args[1].gccode >= 'GCB2ZNQ' then
		return 3
	elseif args[1].gccode >= 'GCAYY59' then
		return 2
	else
		return 1
	end
end

function get_default(value, default)
	if (value == nil) then
		if type(default)=='table' then 
			local version = determine_args_version()
			--DebugPrint(dump(default) .. " v="..version.."\n")
			while (version >= 1 and default[version] == nil) do
				version = version-1
			end
			return default[version]
		end
		return default
	else
		return value
	end
end
-----------------------------------------------------
function makekey(month, day)
	return string.format("%02d-%02d",month, day)
end

-----------------------------------------------------
function next_value(field, current)
	if field == 'cache_id' then
		return current+1
	elseif field == 'hidden' or field == 'visitdate' then
		return iso:tostring(iso:parse(current):add({day=1}))
	elseif type(current) == 'number'  then
		return current+1
	elseif string.sub(field,-4)=='mmdd' then
		local consider_year = leapday and "2000" or "2001" -- because 2000 was a leapyear, and 2001 wasn't.
		local current_date = string.format(consider_year .. "-%02d-%02d", tonumber(string.sub(current,1,2)), tonumber(string.sub(current,4,5)))
		local next_date = iso:parse(current_date):add({day=1})
		local next_date_str = iso:tostring(next_date)
		return string.sub(next_date_str,6,7)..'-'..string.sub(next_date_str,9,10)
	else
		error(field .. " sequence not implemented.")
	end
end

-----------------------------------------------------
function reduce_array_choices(yfield, arrays, found_group_count)
	-- To reduce the search space, iteratively remove items from other arrays, that only have one option.
	-- For example, if you're doing visit_day vs county, and visit_day=1 only has one county, it will always be chosen, and never chosen
	-- in subsequent checks. Doing this may result in a array then only having one option, and the process can happen again.
	local continue_reduction = true
	while continue_reduction do
		continue_reduction = false -- only continue if we "do" something.

		-- Put the arrays with the least number of options first, because, you'll converge faster if there is a solution that way.
		table.sort(arrays, function(a1, a2) return #a1 < #a2 end )
		for array_index,array in ipairs(arrays) do
			-- Once there multiple options, stop.
			if #array > 1 or #array == 0 then
				break
			end

			local only_option_find = array[1]
			local debug_line ="yfield : "
			for _,f in ipairs(yfield) do debug_line = debug_line .. (f.."="..only_option_find[f]..",") end 
			DebugPrint(debug_line .. " is the only option, removing any values of this further on in arrays.\n")

			for next_array = (array_index+1), #arrays do
				local eclipsed_find_index = find_in_list_by_fields(only_option_find, yfield, arrays[next_array])
				if eclipsed_find_index > 0 then
					-- We're actually doing something, so run this process again.
					continue_reduction = true
					table.remove(arrays[next_array], eclipsed_find_index)
					-- it's possible we removed all the options from an array, so remove that array completely
					if #arrays[next_array] == 0 then
						table.remove(arrays, next_array)
						found_group_count = found_group_count - 1
					end
				end
			end

			-- If we did something, just start again
			if continue_reduction then break end
		end
	end
end

-----------------------------------------------------
function choose_unique_fields_per_array(array_of_arrays, array_index, fields, solution, maximum_required, best_solution, timeout)

	if type(fields) ~= 'table' or type(maximum_required) ~= 'table' or #fields ~= #maximum_required then
		error("Trying to choose_unique_fields_per_array, but fields and maximum_required weren't lists, or, they aren't the same dimension.")
	end

	timeout = timeout or 55 -- timeout at 55s of runtime, by default.
	if os.difftime(os.time(), start_time) > timeout then
		DebugPrint("choose_unique_fields_per_array timeout reached, returning best solution so far.\n")
		return {ok=false, solution=solution, best_solution = best_solution}
	end

	local total_maximum_required =0
	for _,mr in ipairs(maximum_required) do
		total_maximum_required = total_maximum_required + mr
	end
	best_solution = best_solution or {total_maximum_required=total_maximum_required}

    -- no arrays left to choose from, and didn't fail up to this point, so success.
    if (#array_of_arrays < array_index or total_maximum_required == 0) then
        return {ok=(total_maximum_required == 0), solution=solution, best_solution = best_solution}
    end

	-- Determine whether this array requires a value.
	local can_skip_this_array = true
	for _, mr in ipairs(maximum_required) do
		if #array_of_arrays-array_index < mr then
			can_skip_this_array = false
		end
	end

    -- From the array, choose an item whose field values has not been used before.
    local current_array = array_of_arrays[array_index]
	local tried_field_values = {}
    for en, entry in ipairs(current_array) do
		local key = ""

		-- Check to see whether ALL field value has already been used in the solution, AND whether it's non-nil. nil values are just ignored.
		local valid = false
		local already_used = {}
		for _,field in ipairs(fields) do
			if entry[field] ~= nil then
				key = entry[field] .. "/"
				if find_in_list_by_field(entry, field, solution) <= 0 then
					valid = true
					table.insert(already_used, false)
				else
					table.insert(already_used, true)
				end
			else
				valid = false
				break
			end
		end

        if valid and tried_field_values[key] == nil then
			tried_field_values[key] = 1
            local new_solution = TableCopy(solution)
            table.insert(new_solution, entry)

			local new_maximum_required = TableCopy(maximum_required)
			local new_total_maximum_required = 0
			for i = 1,#already_used do
				if not already_used[i] and new_maximum_required[i] > 0 then
					new_maximum_required[i] = new_maximum_required[i]-1
				end
				new_total_maximum_required = new_total_maximum_required + new_maximum_required[i]
			end
            if new_total_maximum_required < best_solution.total_maximum_required then
                best_solution = TableCopy(new_solution)
				best_solution.total_maximum_required = new_total_maximum_required
				DebugPrint("New best solution (n="..#best_solution.." req="..new_total_maximum_required..")\n")
            end

            local result = choose_unique_fields_per_array(array_of_arrays, array_index+1, fields, new_solution, new_maximum_required, best_solution, timeout)
			if result.best_solution.total_maximum_required < best_solution.total_maximum_required then
				best_solution = result.best_solution
			end
            if result.ok then
                return result
            end
        end
    end

	-- There was no unique value for this group that hasn't already been chosen. BUT, maybe you don't need a unique one. If all the maximum required are less than the remaining number of arrays
	if can_skip_this_array then
		DebugPrint("choose_unique_fields_per_array no unique value for this array, skipping (maximum not reached).\n")
		return choose_unique_fields_per_array(array_of_arrays, array_index+1, fields, solution, maximum_required, best_solution)
	end

    -- No choice results in an uncolliding solution.	
	-- DebugPrint("Reached deadend.\n")
    return {ok=false, solution=solution, best_solution =best_solution}
end
