function criteria_as_string(criteria)
	local result = ""
	if criteria.func == 'and' then
		result = result .. "("
		for i, subcrit in ipairs(criteria.opt) do
			result = result .. criteria_as_string(subcrit)
			if i ~= #criteria.opt then result = result .. " AND " end
		end
		result = result .. ")"
	elseif criteria.func == 'or' then
		result = result .. "("
		for i, subcrit in ipairs(criteria.opt) do
			result = result .. criteria_as_string(subcrit)
			if i ~= #criteria.opt then result = result .. " OR " end
		end
		result = result .. ")"
	elseif criteria.func == 'not' then
		result = result .. "(NOT " .. criteria_as_string(criteria.opt) .. ")"
	elseif function_def[criteria.func] then
		local desc = function_def[criteria.func].desc or function_def[criteria.func].name
		local text = type(desc) == 'function' and desc(criteria.opt) or desc;
		result = result .. "(".. text ..")"
	else
		result = criteria.field .. " == " .. tostring(criteria.value)
	end
	return result
end

function fields_in_criteria(criteria)
	if criteria.func == 'and' or criteria.func == 'or' then
		local t = {}
		for i, subcrit in ipairs(criteria.opt) do
			for _, f in ipairs(fields_in_criteria(subcrit)) do
				insert_into_list_if_unique(f,t )
			end
		end
		return t
	elseif criteria.func =='not'  then
		return fields_in_criteria(criteria.opt)
	elseif function_def[criteria.func] then
		local fields_required = {}
		insert_function_needs_into_list(criteria.func, criteria.opt, fields_required)	
		return fields_required
	else
		return {criteria.field}
	end
end

function find_satisfies_criteria(find, criteria)
	-- NOTE: nil gccode is ignored.
	if criteria.func == 'and' then
		local result = true
		for _, subcrit in ipairs(criteria.opt) do
			result = result and  find_satisfies_criteria(find, subcrit)
		end
		return result
	elseif criteria.func == 'or' then
		for _, subcrit in ipairs(criteria.opt) do
			if find_satisfies_criteria(find, subcrit) then
				return true
			end
		end
		return false
	elseif criteria.func == 'not' then
		return not find_satisfies_criteria(find, criteria.opt)
	elseif function_def[criteria.func] ~= nil then
		local result = function_def[criteria.func].read(find, criteria.opt)
		if type(result) ~= 'boolean' then
			error("In find_satisfies_criteria, result of " .. criteria.func .. " is not a boolean.")
		end
		return result
	else
		-- simple comparison of field and value.
		return find[criteria.field] == criteria.value and find.gccode ~= nil
	end
end

function get_icon_for_criteria(criteria)
	if criteria == nil then return nil end
	if (criteria.icon ~= nil) then
		return "<img src='" .. criteria.icon .. "'/>"
	elseif criteria.field =='type' then
		return PGC.Icon.GeocacheType(criteria.value)
	elseif criteria.field =='size' then
		return PGC.Icon.GeocacheSize(criteria.value)
	elseif criteria.field =='country' then
		return PGC.Icon.CountryFlag(criteria.value)
	else
		return nil
	end
end

function get_html_for_criteria(passed, criteria_index)

	local criteria = nil
	for _, c in ipairs(criteria_list) do
		if c.criteria_index == criteria_index then
			criteria = c
			break
		end
	end

	return get_html_for_criteria_struct(passed, criteria)
end

function get_html_for_criteria_struct(passed, criteria)
	local line = ""
	if passed then
		local icon = get_icon_for_criteria(criteria)
		if icon ~= nil then
			line = line .. icon
		elseif criteria.label then
			line = line .. criteria.label
		elseif criteria.value then
			line = line .. string.upper(string.sub(tostring(criteria.value),1,1))
		elseif criteria.func == 'and' then
			line = '('
			for i, subcrit in ipairs(criteria.opt) do
				line = line .. get_html_for_criteria_struct(passed, subcrit)
				if i ~= #criteria.opt then
					line = line .. " & "
				end
			end
			line = line .. ")"
		elseif criteria.func == 'or' then
			line = '('
			for i, subcrit in ipairs(criteria.opt) do
				line = line .. get_html_for_criteria_struct(passed, subcrit)
				if i ~= #criteria.opt then
					line = line .. " | "
				end
			end
			line = line .. ")"
		elseif criteria.func == 'or' then
			line = '('
			for i, subcrit in ipairs(criteria.opt) do
				line = line .. get_html_for_criteria_struct(passed, subcrit)
				if i ~= #criteria.opt then
					line = line .. " | "
				end
			end
			line = line .. " >= " .. criteria.count .. ")"
		elseif criteria.func == 'not' then
			return "!" .. get_html_for_criteria_struct(passed, criteria.opt)
		end
	else
		line = line.. "<font color='#FF0000'>X</font>"
	end
	return line
end

