-- Adapted from: https://www.geeksforgeeks.org/print-subsets-given-size-set/
function combination_util(arr, r, index, data, i, f)

	-- Current combination is ready to be printed, print it
	if (index == r+1) then
		local combo = {}
		for j = 1, r do
			table.insert(combo, data[j])
		end
		return f(combo);
	end

	-- When no more elements are there to put in data[]
	if (i > #arr) then
		return true;
	end

	-- current is included, put next at next location
	data[index] = arr[i];
	local result = combination_util(arr, r, index + 1, data, i + 1, f);

	-- current is excluded, replace it with next (Note that i+1 is passed, but index is not changed)
	result = result and combination_util(arr, r, index, data, i + 1, f);

	return result;
end

function get_all_combinations(arr, r)
	local data = {}
	local result = {}
	combination_util(arr, r, 1, data, 1, function(combo) table.insert(result, combo); return true end)
	return result;
end

function foreach_combination_until(arr, r, f)
	local data = {}
	combination_util(arr, r, 1, data, 1, f)
end
