function FilterFromConfig(conf)
  local filter={}

  filter['country'] = conf.country
  filter['region'] = conf.region
  filter['county'] = conf.county
  filter['minVisitDate'] = conf.minVisitDate
  filter['maxVisitDate'] = conf.maxVisitDate
  filter['minHiddenDate'] = conf.minHiddenDate
  filter['maxHiddenDate'] = conf.maxHiddenDate
  filter['excludeTypes']=conf.excludeTypes
  filter['excludeSizes']=conf.excludeSizes
  filter['types'] = conf.types
  filter['sizes'] = conf.sizes
  filter['difficulties'] = conf.difficulties
  filter['terrains'] = conf.terrains
  filter['minlatitude'] = conf.minlatitude
  filter['maxlatitude'] = conf.maxlatitude
  filter['minlongitude'] = conf.minlongitude
  filter['maxlongitude'] = conf.maxlongitude
  filter['minFavoritePoints'] = conf.minFavoritePoints
  filter['minFavoritePointsPercent'] = conf.minFavoritePointsPercent
  filter['minFinds'] = conf.minFinds
  filter['maxFinds'] = conf.maxFinds
  if conf.excludeMostFoundCountry ~= nil and conf.excludeMostFoundCountry ~= false and conf.excludeMostFoundCountry ~= "false" then
	calculateMostFound()
	if conf.excludeCountries == nil then conf.excludeCountries = {} end
	if type(conf.excludeCountries) ~= "table" then
		local temp = conf.excludeCountries
		conf.excludeCountries = {}
		table.insert(conf.excludeCountries, temp)
	end
	for _,c in ipairs(mostFoundCountry) do
		table.insert(conf.excludeCountries,c)
	end
  end
  if conf.excludeMostFoundRegion ~= nil and conf.excludeMostFoundRegion ~= false and conf.excludeMostFoundRegion ~= "false" then
	calculateMostFound()
	if conf.excludeRegions == nil then conf.excludeRegions = {} end
	if type(conf.excludeRegions) ~= "table" then
		local temp = conf.excludeRegions
		conf.excludeRegions = {}
		table.insert(conf.excludeRegions, temp)
	end
	for _,c in ipairs(mostFoundRegion) do
		table.insert(conf.excludeRegions,matchingRegions[c])
	end
  end
  if conf.excludeMostFoundCounty ~= nil and conf.excludeMostFoundCounty ~= false and conf.excludeMostFoundCounty ~= "false" then
	calculateMostFound()
	if conf.excludeCounties == nil then conf.excludeCounties = {} end
	if type(conf.excludeCounties) ~= "table" then
		local temp = conf.excludeCounties
		conf.excludeCounties = {}
		table.insert(conf.excludeCounties, temp)
	end
	for _,c in ipairs(mostFoundCounty) do
		table.insert(conf.excludeCounties,matchingCounties[c])
	end
  end
  filter['minRegionsInCountry'] = conf.minRegionsInCountry
  filter['maxRegionsInCountry'] = conf.maxRegionsInCountry
  filter['minCountiesInRegion'] = conf.minCountiesInRegion
  filter['maxCountiesInRegion'] = conf.maxCountiesInRegion  
  filter['excludeCountries'] = conf.excludeCountries
  filter['excludeRegions'] = conf.excludeRegions
  filter['excludeCounties'] = conf.excludeCounties
  filter['includeRegions'] = conf.includeRegions
  filter['includeCounties'] = conf.includeCounties
  filter['visitday'] = conf.visitday
  filter['visitweekday'] = conf.visitweekday
  filter['visitmonth'] = conf.visitmonth
  filter['visityear'] = conf.visityear
  filter['visitspecial'] = conf.visitspecial
  filter['hiddenday'] = conf.hiddenday
  filter['hiddenweekday'] = conf.hiddenweekday
  filter['hiddenmonth'] = conf.hiddenmonth
  filter['hiddenyear'] = conf.hiddenyear
  filter['hiddenspecial'] = conf.hiddenspecial
  filter['publishday'] = conf.publishday
  filter['publishweekday'] = conf.publishweekday
  filter['publishmonth'] = conf.publishmonth
  filter['publishspecial'] = conf.publishspecial
  filter['minArchiveDate'] = conf.minArchiveDate
  filter['maxArchiveDate'] = conf.maxArchiveDate
  filter['minAge'] = conf.minAge
  filter['maxAge'] = conf.maxAge
  filter['excludeCaches'] = conf.excludeCaches
  filter['excludeBookmarkList'] = conf.excludeBookmarkList
  filter['radius'] = conf.radius
  filter['minElevation'] = conf.minElevation
  filter['maxElevation'] = conf.maxElevation
  filter['attributeFilter'] = conf.attributeFilter
  filter['owners'] = conf.owners
  filter['filters'] = conf.filters
  filter['dt'] = conf.dt
  filter['excludeDT'] = conf.excludeDT
  filter['maxResults'] = conf.maxResults
  filter['regex'] = conf.regex
  filter['us_state'] = conf.us_state
  filter['bookmarklist'] = conf.bookmarklist
  filter['polyset'] = conf.polyset
  filter['gccodes'] = conf.gccodes

  -- can have an array of numeric filters. If not specified, turn it into an array.
	if conf.numeric~= nil then
		filter['numeric'] = #conf.numeric == 0 and {conf.numeric} or conf.numeric
	end

  	-- If they use a predefined filter, then expand that so it gets further expanded.
  	local predefined_filter = conf.predefined_filter or ((g_conf.filter_aliases or {}).predefined_filter and conf[g_conf.filter_aliases.predefined_filter])
	if predefined_filter ~= nil then
		if type(predefined_filter)~='string' then error("'predefined_filter' must be a single string.") end
		local predef = predefined_filter_groups[predefined_filter] or error("Predefined filter: " .. predefined_filter .. " does not exist." )
		for k,v in pairs(predef) do
			if filter[k] ~= nil then error("Predefined filter " .. predefined_filter .. " specifies '"..k.."', but it's also in the conf. Can't have both.") end
			filter[k]=v
		end
  end

  -- if there are any filter aliases, apply those now.
  for original_key, alias in pairs(g_conf.filter_aliases or {}) do
	if filter[original_key] ~= nil then
		error("You've specified an alias for '"..original_key.."', but that also was specified in the conf.")
	end
	filter[original_key] = conf[alias]
  end  

  -- if the attribute filter is NOT a table, assume it's a number-ish, and convert it to the larger 'set'
  if filter['attributeFilter'] ~= nil and type(filter['attributeFilter']) ~= "table" then
	filter['attributeFilter'] = {func="set",opt={attribute=tonumber(filter['attributeFilter'])}}
  end

  -- NOW, apply any filter transforms.
  for _, ft in ipairs(conf.filter_transforms or {}) do
	DebugPrint("filter_transform: " .. dump(ft).."\n")
	filter[ft.opt.outfield] = function_def[ft.func].read(filter, ft.opt)
  end
  if #(conf.filter_transforms or {}) > 0 then
	DebugPrint("applied filter transforms.\n")
  end

  return filter
end -- end function FilterFromConfig
