function extraInConfig(conf,list)
  	local extra=false
  	local filter={"country","region","county","minVisitDate","maxVisitDate","minHiddenDate",
  				"maxHiddenDate","excludeTypes","types","excludeSizes","sizes","difficulties","terrains",
  				"minlatitude","maxlatitude","minlongitude","maxlongitude","minFavoritePoints", "minFavoritePointsPercent", "minFinds", "maxFinds",
				"excludeCountries","excludeRegions","excludeCounties","includeRegions","includeCounties","excludeCaches", "excludeBookmarkList", "radius", "gccodes",
				"findsTotal","excludeMostFoundCountry","excludeMostFoundRegion","excludeMostFoundCounty","maxPoints","skipPoints",
				"includeLabCaches","include_labs","upperlimit","minElevation","maxElevation", "attributeFilter",
				"visitday","visitweekday","visitmonth","visityear","visitspecial","hiddenday","hiddenweekday","hiddenmonth","hiddenyear", "hiddenspecial",
				"publishday","publishweekday","publishmonth","publishyear", "publishspecial",
				"minAge","maxAge", "owners", "filters", "debug", "transforms", "maxResults", "dt", "excludeDT",
				"regex", "numeric","header", "us_state", "points",
			    "predefined_filter","gethides","bookmarklist", "lookup_cache", "polyset",
				"minRegionsInCountry","maxRegionsInCountry","minCountiesInRegion","maxCountiesInRegion", "minArchiveDate", "maxArchiveDate", "sort_order"}
	for _,alias in pairs(g_conf.filter_aliases or {}) do
		table.insert(filter, alias)
	end
  	local acc={}
  	for _,v in ipairs(filter) do
   		acc[v]=v
    end
  	for _,v in ipairs(list) do
   		acc[v]=v
    end
  	for k,v in pairs(conf) do
    	if acc[k]== nil then
      		PGC.print("\nUnknown config:",k,":",v,"\n")
      		extra=true
      	end
    end
    return extra
end --end extraInConfig(
