function PrintFilter(filter)

	local res=""
    if filter~= nil then
		local l_filters=TableCopy(filter.filters)
		local l_filter=TableCopy(filter)
    	l_filter.filters=nil
    	local loop_filters={}
    	if l_filters==nil then
      		table.insert(loop_filters,TableCopy(l_filter))
    	else
      		for _,t in pairs(l_filters) do
          		local tmp=TableCopy(l_filter)
          		for k,v in pairs(t) do
            		if type(v)=="table" then
                		tmp[k]=TableCopy(v)
              		else
                		tmp[k]=v
              		end
          		end
          		table.insert(loop_filters,tmp)
        	end
    	end
  
		--PGC.print("loop_filters",loop_filters)
    	--count filters
    	local count=0
    	for _,_ in ipairs(loop_filters) do
      		count=count+1
    	end

		function PrintAttributeFilter(filter)
			if (filter.func == 'and') then
				local af = PrintAttributeFilter(filter.opt[1])
				for i, opt in ipairs(filter.opt) do
					if i ~= 1 then
						af = af .. " and " .. PrintAttributeFilter(opt);
					end
				end
				return af
			elseif (filter.func == 'or') then
				local af = PrintAttributeFilter(filter.opt[1])
				for i, opt in ipairs(filter.opt) do
					if i ~= 1 then
						af = af .. " or " .. PrintAttributeFilter(opt);
					end
				end
				return af
			elseif (filter.func == 'any') or (filter.func == 'all') then
				local result = filter.func .. "("
				for _, attr in ipairs(filter.opt.attribute) do
					result = result .. PrintAttributeFilter({func='set',opt={attribute=attr}}) .. ", "
				end
				result = result .. ")"
				return result
			elseif (filter.func == 'n') then
				result = filter.opt.n .. ' attributes set'
				return result
			elseif (filter.func == 'set') then
				local attrs = PGC.GetAttributeList()
				local negative_attribute = (filter.opt.attribute >= 96)
				local attr_index = (filter.opt.attribute % 96)
				local text = (negative_attribute and "Not " or "") .. (attrs[attr_index] and attrs[attr_index].attributeName or "UNKNOWN!")
				if filter.opt.value == false then
					text = "NOT(" .. text .. ")"
				end
				return text
			else
				return "ERROR"
			end
		end

		if count>=1 then
			res=res.."Filters:("
			local count2=0
			for _,f in ipairs(loop_filters) do
				if count2>0 then
					res=res.." OR "
				end
				count2=count2+1
				local count3=0
				for k,v in pairs(f) do
					if g_conf.printfilter_fields == nil or find_in_list(k, g_conf.printfilter_fields) > 0 then					
						count3=count3+1
						if count3>1 then
							res=res..", "
						end
						if k=='attributeFilter' then
							res= res .. 'attributeFilter('..PrintAttributeFilter(v)..')'
						elseif k=='numeric' then
							local numeric_filter_strings = {}
							for _, nf in ipairs(v) do
								local value = nf.field_op ~= nil and nf.field_op or nf.value
								table.insert(numeric_filter_strings, nf.field .. nf.op .. tostring(value))
							end
							res = res .. table.concat(numeric_filter_strings, " AND ")
						elseif type(v)=="table" then
							res=res.." "..k.." ("
							local count4=0
							for kp,d in pairs(v) do
								count4=count4+1
								if count4>1 then
									res=res..", "
								end
								res=res..kp.."="..tostring(d)
							end
							res=res..") "
						else
							res=res.." "..k..":"..tostring(v)
						end
					end
				end
      		end
      		res=res..")"
    	end
    end

	-- If the filter text is empty, just remove it, because it's just clutter.
	if res == "Filters:()" then
		res = ""
	end

	return res
end --- end function PrintFilter
-----------------------------------------------------
function find_fails_filter(filter, v, using_lookup_cache)

	local fail = false
	using_lookup_cache = using_lookup_cache or false

	--exclude types / sizes
	fail = fail or (filter.excludeTypes~= nil and filter.excludeTypes[v.type]~= nil)
	fail = fail or (filter.excludeSizes ~= nil and filter.excludeSizes[v.size]~= nil)	

	--exclude/re-include countries, regions and counties
	if (filter.excludeCountries ~= nil and filter.excludeCountries[v.country] ~= nil) then
		if (filter.includeRegions == nil or filter.includeRegions[v.region] == nil) and (filter.includeCounties == nil or filter.includeCounties[v.county] == nil) then
		fail=true
		end
	end

	if filter.minRegionsInCountry ~= nil or filter.maxRegionsInCountry ~= nil then		
		local num_regions_in_country = GetNumberOfRegionsInCountryCached(v.country)
		if filter.minRegionsInCountry ~= nil and num_regions_in_country < filter.minRegionsInCountry then
			fail = true
		elseif filter.maxRegionsInCountry ~= nil and num_regions_in_country > filter.maxRegionsInCountry then
			fail = true
		end
	end

	if filter.minCountiesInRegion ~= nil or filter.maxCountiesInRegion ~= nil then
		local num_counties_in_region = GetNumberOfCountiesInRegionCached(v.country, v.region)
		if filter.minCountiesInRegion ~= nil and num_counties_in_region < filter.minCountiesInRegion then
			fail = true
		elseif filter.maxCountiesInRegion ~= nil and num_counties_in_region > filter.maxCountiesInRegion then
			fail = true
		end
	end

	if (filter.excludeRegions ~= nil and filter.excludeRegions[v.region] ~= nil) then
		if (filter.includeCounties == nil or filter.includeCounties[v.county] == nil) then
		fail=true
		end
	end
	
	fail = fail or (filter.excludeCounties ~= nil and filter.excludeCounties[v.county] ~= nil)		--exclude countries
	fail = fail or (filter.excludeCaches~= nil and filter.excludeCaches[v.gccode]~= nil)			--exclude specific caches
	fail = fail or (filter.excludeBookmarkList ~= nil and filter.excludeBookmarkList[v.gccode])		-- exclude finds from bookmark list.

	
	-- Limit find dates
	fail = fail or (filter.visitday ~= nil and filter.visitday[string.sub(v.visitdate,9,10)] == nil)
	fail = fail or (filter.visitweekday ~= nil and filter.visitweekday[iso:parse(v.visitdate):weekday_name()] == nil)
	fail = fail or (filter.visitmonth ~= nil and filter.visitmonth[string.sub(v.visitdate,6,7)] == nil)
	fail = fail or (filter.visityear ~= nil and filter.visityear[string.sub(v.visitdate,1,4)] == nil)
	if filter.visitspecial ~= nil then
		v.visitspecial = get_special_day(v.visitdate,filter.visitspecial) 
		if v.visitspecial == nil then
			fail = true
		end
	end

	-- Limit hide dates
	fail = fail or (filter.hiddenday ~= nil and filter.hiddenday[string.sub(v.hidden,9,10)] == nil)
	fail = fail or (filter.hiddenweekday ~= nil and filter.hiddenweekday[iso:parse(v.hidden):weekday_name()] == nil)
	fail = fail or (filter.hiddenmonth ~= nil and filter.hiddenmonth[string.sub(v.hidden,6,7)] == nil)
	fail = fail or (filter.hiddenyear ~= nil and filter.hiddenyear[string.sub(v.hiddenyear,1,4)] == nil)
	if filter.hiddenspecial ~= nil then
		v.hiddenspecial = get_special_day(v.hidden,filter.hiddenspecial) 
		if v.hiddenspecial == nil then
			fail = true
		end
	end

	-- Limit publish dates
	fail = fail or (filter.publishday ~= nil and filter.publishday[string.sub(v.last_publish_date,9,10)] == nil)
	fail = fail or (filter.publishweekday ~= nil and filter.publishweekday[iso:parse(v.last_publish_date):weekday_name()] == nil)
	fail = fail or (filter.publishmonth ~= nil and filter.publishmonth[string.sub(v.last_publish_date,6,7)] == nil)
	fail = fail or (filter.publishyear ~= nil and filter.publishyear[string.sub(v.publishyear,1,4)] == nil)
	if filter.publishspecial ~= nil then
		v.publishspecial = get_special_day(v.last_publish_date,filter.publishspecial) 
		if v.publishspecial == nil then
			fail = true
		end
	end

	-- Limit age
	fail = fail or (filter.minAge ~= nil and (os.time() - os.time({year=string.sub(v.hidden,1,4),month=string.sub(v.hidden,6,7),day=string.sub(v.hidden,9,10)}))/86400 < filter.minAge)
	fail = fail or (filter.maxAge ~= nil and (os.time() - os.time({year=string.sub(v.hidden,1,4),month=string.sub(v.hidden,6,7),day=string.sub(v.hidden,9,10)}))/86400 > filter.maxAge)
	fail = fail or (filter.hiddenmonth ~= nil and filter.hiddenmonth[string.sub(v.hidden,6,7)] == nil)

	-- Lattitude/logitude
	fail = fail or (filter.minlatitude ~= nil  and  tonumber(filter.minlatitude)>=tonumber(v.latitude))
	fail = fail or (filter.maxlatitude ~= nil and  tonumber(filter.maxlatitude)<=tonumber(v.latitude))
	fail = fail or (filter.minlongitude ~= nil and  tonumber(filter.minlongitude)>=tonumber(v.longitude))
	fail = fail or (filter.maxlongitude ~= nil and  tonumber(filter.maxlongitude)<=tonumber(v.longitude))

	-- NOTE: It looks like sometimes elevation is bogus
	local v_e = tonumber(v.elevation)
	if (filter.minElevation ~= nil or filter.maxElevation ~= nil) and v_e == nil then
		DebugPrint("NOTE: min/maxElevation was requested as a filter, but cache " .. v.gccode .. " reported nil. Ignoring.\n")
		fail = true
	end

	fail = fail or (filter.minElevation ~= nil and v_e ~= nil and v_e < tonumber(filter.minElevation))
	fail = fail or (filter.maxElevation ~= nil and v_e ~= nil and v_e > tonumber(filter.maxElevation))
	fail = fail or (filter.maxFinds ~= nil and tonumber(v.num_finds) >= filter.maxFinds)
	fail = fail or (filter.minFinds ~= nil and tonumber(v.num_finds) <= filter.minFinds)

	fail = fail or (filter.attributeFilter ~= nil and not cache_passes_attribute_filter(v, filter.attributeFilter))
	fail = fail or (filter.owners ~= nil and filter.owners[v.owner_id] == nil)
	fail = fail or (filter.dt ~= nil and filter.dt[v.difficulty .."/"..v.terrain] == nil)
	fail = fail or (filter.regex ~= nil and string.find(v[filter.regex.field], filter.regex.pattern) == nil)
	for _, numeric_filter in ipairs(filter.numeric or {}) do
		fail = fail or (numeric_filter ~= nil and not binary_comparison(numeric_filter.op, v[numeric_filter.field], numeric_filter.field_op ~= nil and v[numeric_filter.field_op] or numeric_filter.value))
	end
	fail = fail or (filter.bookmarklist ~= nil and not filter.bookmarklist[v.gccode])	
	fail = fail or (filter.polyset ~= nil and find_fails_polyset(v,filter.polyset))

	-- NOTE: Lab cache doesn't filter by dates when queried in the database, so do that here.
	if v.type == "Lab Cache" then
		fail = fail or (filter.minVisitDate ~= nil and v.visitdate < filter.minVisitDate)										-- minVisitDate (string): YYYY-MM-DD, the date will be included, ie: >= date
		fail = fail or (filter.maxVisitDate ~= nil and v.visitdate > filter.maxVisitDate)										-- maxVisitDate (string): YYYY-MM-DD, the date will be included, ie: <= date
	end

	-- NOTE: last_archive_date might not be set, even if the cache is archived. If so, make up an appropriate date.
	if filter.maxArchiveDate ~= nil or filter.minArchiveDate ~= nil then	
		if tonumber(v.archived) ~= 0 then
			-- Start with the last found date.
			v.last_archive_date = v.last_find_date

			-- Otherwise, if the cache is archived, but we don't have a last found date, then use the visit date.
			if v.last_archive_date == nil then
				v.last_archive_date = v.visitdate
			end

			if v.last_archive_date == nil then
				-- Otherwise, if the cache is archived, but we don't have a last found date or visit date, then use the hidden date.
				v.last_archive_date = v.hidden
			end
		end

		fail = fail or (filter.maxArchiveDate ~= nil and (tonumber(v.archived) == 0 or v.last_archive_date > filter.maxArchiveDate))
		fail = fail or (filter.minArchiveDate ~= nil and (tonumber(v.archived) ~= 0 and v.last_archive_date < filter.minArchiveDate))
	end

	-- These are built-in query ones, but, if we use lookup_cache, they might be required.
	if not fail and using_lookup_cache then
		function cache_fails_filter_field_string_or_array(cache_field, filter_field, cache, filter)
			if filter[filter_field] ~= nil then
				if type(filter[filter_field]) == 'string' then
					return cache[cache_field] ~= filter[filter_field]
				elseif type(filter[filter_field]) == 'table' then
					return filter[filter_field][cache[cache_field]] == nil
				else
					error('Expected ' .. filter_field .. ' to be a string or table.')
				end
			end
			return false
		end
		function cache_fails_filter_field_array(cache_field, filter_field, cache, filter)
			if filter[filter_field] ~= nil then
				return find_in_list(cache[cache_field], filter[filter_field]) <= 0
			end
			return false
		end
		
		fail = fail or (cache_fails_filter_field_string_or_array('country','country',v,filter)) 								-- country (string or array)
		fail = fail or (cache_fails_filter_field_string_or_array('region','region',v,filter))   								-- region (string or array)
		fail = fail or (cache_fails_filter_field_string_or_array('county','county',v,filter))   								-- county (string or array)
		fail = fail or (filter.minVisitDate ~= nil and v.visitdate < filter.minVisitDate)										-- minVisitDate (string): YYYY-MM-DD, the date will be included, ie: >= date
		fail = fail or (filter.maxVisitDate ~= nil and v.visitdate > filter.maxVisitDate)										-- maxVisitDate (string): YYYY-MM-DD, the date will be included, ie: <= date
		fail = fail or (filter.minHiddenDate ~= nil and v.hidden < filter.minHiddenDate)										-- minHiddenDate (string): YYYY-MM-DD, the date will be included, ie: >= date
		fail = fail or (filter.maxHiddenDate ~= nil and v.hidden > filter.maxHiddenDate)										-- maxHiddenDate (string): YYYY-MM-DD, the date will be included, ie: <= date
		fail = fail or (cache_fails_filter_field_array('gccode','gccodes',v,filter)) 											-- gccodes (array): List of gccodes
		fail = fail or (cache_fails_filter_field_array('type','types',v,filter)) 												-- types (array): An array of valid types
		fail = fail or (cache_fails_filter_field_array('size','sizes',v,filter))  												-- sizes (array): An array of valid sizes
		fail = fail or (cache_fails_filter_field_array('difficulty','difficulties',v,filter)) 									-- difficulties (array): An array of valid values
		fail = fail or (cache_fails_filter_field_array('terrain','terrains',v,filter)) 											-- terrains (array): An array of valid values
		fail = fail or (filter.minFavoritePoints ~= nil and tonumber(v.favorite_points) < filter.minFavoritePoints)						-- minFavoritePoints (int): Minimum amount of favorite points required
		fail = fail or (filter.minFavoritePointsPercent ~= nil and tonumber(v.favorite_points_pct) < filter.minFavoritePointsPercent)		-- minFavoritePointsPercent (int): Minimum amount of favorite points percent required
		fail = fail or (filter.minFavoritePointsWilson ~= nil and tonumber(v.favorite_points_wilson) < filter.minFavoritePointsWilson)	-- minFavoritePointsWilson (int): Minimum amount of favorite points wilson score required

		-- Not supported yet, but could be....
		if filter.monthnames ~= nil then error('filter.monthnames not supported (yet).') end	-- monthnames (array): List of January/February/March/April/May/June/July/August/September/October/November/December
		if filter.daynames ~= nil then error('filter.daynames not supported (yet).') end 		-- daynames (array): List of Monday/Tuesday/Wednesday/Thursday/Friday/Saturday/Sunday
		if filter.radius ~= nil then error('filter.radius not supported (yet).') end
		-- radius (array): An associative array
		-- 	algorithm (string): Can be any value of ['Vincenty', 'Haversine']. Defaults to 'Vincenty'.
		-- 	distance (integer): Number of meters.
		-- 	latitude (float): Latitude.
		-- 	longitude (float): Longitude.
		-- 	minMax (string): Can be any value of ['min', 'max']. Defaults to 'max'.	
	end

	return fail
end

 function expandFilter(filter)
	local res={}
	for k,v in pairs(filter) do
	-- add custom groups as types and make excludeTypes accociative
	if k=="types" then
		if type(v)=="string" then
			local tmp=v
			res['types']={}
			table.insert(res.types,tmp)
		else
			res.types={}
			for i,t in ipairs(v) do
				if t=="Physical" then
					table.insert(res.types,"Traditional Cache")
					table.insert(res.types,"Mystery Cache")
					table.insert(res.types,"Multi-Cache")
					table.insert(res.types,"Letterbox Hybrid")
					table.insert(res.types,"Wherigo Cache")
					table.insert(res.types,"Project A.P.E. Cache")
					table.insert(res.types,"Geocaching HQ Cache")
				elseif t=="Events" then
					table.insert(res.types,"Event Cache")
					table.insert(res.types,"Cache In Trash Out Event")
					table.insert(res.types,"Community Celebration Event")
					table.insert(res.types,"GPS Adventures Maze Exhibit")
					table.insert(res.types,"Mega-Event Cache")
					table.insert(res.types,"Geocaching HQ Block Party")
					table.insert(res.types,"Giga-Event Cache")
					table.insert(res.types,"Geocaching HQ Celebration")
				else
					table.insert(res.types,t)
				end
			end
		end

	-- exclude types
	elseif k=="excludeTypes" then
		res.excludeTypes={}
		if type(v)=="string" then
			local tmp=v

			res.excludeTypes[tmp]=tmp
		end
		local types=filter.excludeTypes
		--res.excludeTypes={}
		for i,t in ipairs(v) do
			if t=="Physical" then
			res.excludeTypes['Traditional Cache']="Traditional Cache"
			res.excludeTypes['Mystery Cache']="Mystery Cache"
			res.excludeTypes['Multi-Cache']="Multi-Cache"
			res.excludeTypes['Letterbox Hybrid']="Letterbox Hybrid"
			res.excludeTypes['Wherigo Cache']="Wherigo Cache"
			res.excludeTypes['Project A.P.E. Cache']="Project A.P.E. Cache"
			res.excludeTypes['Geocaching HQ Cache']="Geocaching HQ Cache"
			elseif t=="Events" then
			res.excludeTypes['Event Cache']="Event Cache"
			res.excludeTypes['Cache In Trash Out Event']="Cache In Trash Out Event"
			res.excludeTypes['Community Celebration Event']="Community Celebration Event"
			res.excludeTypes['Mega-Event Cache']="Mega-Event Cache"
			res.excludeTypes['Geocaching HQ Block Party']="Geocaching HQ Block Party"
			res.excludeTypes['Giga-Event Cache']="Giga-Event Cache"
			res.excludeTypes['Geocaching HQ Celebration']="Geocaching HQ Celebration"
			else
			res.excludeTypes[t]=t
			end
		end
	-- exclude sizes
	elseif k=="excludeSizes" then
		res.excludeSizes = {}
		if type(v) == "string" then
			res.excludeSizes[v] = v
		else
			for i,s in ipairs(v) do
				res.excludeSizes[s]=s
			end
		end
	-- countries
	elseif k=="country" then
		res.country={}
		if type(v)=="string" then
		if GetContinentCountries()[v] ~= nil then
			for _,u in ipairs(GetContinentCountries()[v]) do
			res.country[u]=u
			end
		else
			res.country[v]=v
		end
		else
			for i,t in ipairs(v) do
			if GetContinentCountries()[t] ~= nil then
				for _,u in ipairs(GetContinentCountries()[t]) do
				res.country[u]=u
				end
			else
				res.country[t]=t
			end
			end
		end
	-- exclude countries
	elseif k=="excludeCountries" or k=="ExcludedCountries" then
		res.excludeCountries={}
		if type(v)=="string" then
		if GetContinentCountries()[v] ~= nil then
			for _,u in ipairs(GetContinentCountries()[v]) do
			res.excludeCountries[u]=u
			end
		else
			res.excludeCountries[v]=v
		end
		else
			for i,t in ipairs(v) do
			if GetContinentCountries()[t] ~= nil then
				for _,u in ipairs(GetContinentCountries()[t]) do
				res.excludeCountries[u]=u
				end
			else
				res.excludeCountries[t]=t
			end
			end
		end
	-- exclude regions
	elseif k=="excludeRegions" or k=="ExcludedRegions" then
		res.excludeRegions={}
		if type(v)=="string" then
			res.excludeRegions[v]=v
		else
			for i,t in ipairs(v) do
				res.excludeRegions[t]=t
			end
		end
	-- exclude counties
	elseif k=="excludeCounties" or k=="ExcludedCounties" then
		res.excludeCounties={}
		if type(v)=="string" then
			res.excludeCounties[v]=v
		else
			for i,t in ipairs(v) do
				res.excludeCounties[t]=t
			end
		end
	-- include regions
	elseif k=="includeRegions" or k=="IncludedRegions" then
		res.includeRegions={}
		if type(v)=="string" then
			res.includeRegions[v]=v
		else
			for i,t in ipairs(v) do
				res.includeRegions[t]=t
			end
		end
	-- include counties
	elseif k=="includeCounties" or k=="IncludedCounties" then
		res.includeCounties={}
		if type(v)=="string" then
			res.includeCounties[v]=v
		else
			for i,t in ipairs(v) do
				res.includeCounties[t]=t
			end
		end
	-- exclude specific caches
	elseif k=="excludeCaches" then
		res.excludeCaches={}
		if type(v)=="string" then
			res.excludeCaches[v]=v
		else
			for i,t in ipairs(v) do
				res.excludeCaches[t]=t
			end
		end
	-- limit find dates
	elseif k=="visitday" then
		res.visitday={}
		if type(v)=="string" then
			res.visitday[v]=v
		else
			for i,t in ipairs(v) do
				res.visitday[t]=t
