		return log,html,slog,shtml
	end
	--------
	function PrintFieldsLimitDT(okCaches,outputfields,log,html,conf)
		local log={}
		local html={}
		local print_caches = {}
		if conf.brief ~= true then
			--generate html, and log temp
			local logtmp={}
			local done=false
			local loopDT=0
			local loopD=0
			local loopT=0
			local loopNR=0
			if okCaches.caches~= nil then
				for i,c in ipairs(okCaches.caches) do
					local l_done=false
					local l_notdone=false
					if done==false or conf.full==true then
						table.insert(print_caches,c)
					end
					if conf.conditions.dtsum ~= nil then
						loopDT=loopDT+c.dtsum
						if loopDT>=conf.conditions.dtsum then
							l_done=true
						else
							l_notdone=true
						end
					end
					if conf.conditions.dsum ~= nil then
						loopD=loopD+c.dsum
						if loopD>=conf.conditions.dsum then
							l_done=true
						else
							l_notdone=true
						end
					end
					if conf.conditions.tsum ~= nil then
						loopT=loopT+c.tsum
						if loopT>=conf.conditions.tsum then
							l_done=true
						else
							l_notdone=true
						end
					end
					if conf.conditions.limit ~= nil then
						loopNR=loopNR+1
						if loopNR>=conf.conditions.limit then
							l_done=true
						else
							l_notdone=true
						end
					end
					if l_done==true and l_notdone==false then
						done=true
					end
				end
			end
		end

		if conf.print_fields ~= nil then
			outputfields = conf.print_fields
		end

		table.insert(log, PrintFindsText(print_caches, #print_caches, outputfields))
		table.insert(html, PrintFindsHtml(print_caches, #print_caches, outputfields))
		return log, html
	end
	--------
	function PrintFields(Caches,outputfields,log,html,conf)
		if conf.brief ~= true then
			local print_fields = conf.printFields or outputfields

			local print_caches = {}
			for _,c in pairs(Caches) do
				table.insert(print_caches, c)
			end

			table.insert(html,PrintFindsHtml(print_caches, #print_caches, print_fields))
			table.insert(log,PrintFindsText(print_caches, #print_caches, print_fields))
		end
	end
	--------
	local slog=""
	local shtml=""
	local options ={"conditions","brief","period","groupby","debug","pointsPer","pointsField","maxPoints","skipPoints","printFields"}
		if extraInConfig(conf,options)==true then
			return{ok=nil,log=nil,html=nil}
		end
	local filter=FilterFromConfig(conf)
	conf.filter=filter

	-- Do this after the filter is expanded.
	conf.conditions = preprocess_conditions(conf)

	local period=conf.period
	local groupby=conf.groupby
	local fields={'gccode', 'cache_name','size', 'visitdate', 'country','region','county','difficulty','terrain','log_id','type','latitude','longitude'}
	local log = {}
	local html ={}
	local ok = false
	local fail=false
	local myFinds=GetCombinedFinds(profileId,{lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = fields,  order = 'OLDESTFIRST',  filter = filter, includeLabCaches=conf.labcaches })
	local groups =groupFinds(myFinds,period,groupby,filter)
	local okCaches={}
	ok,okCaches=checkTest(groups,conf)
	if ok==false then
		fail=true
	end

	log,html,slog,shtml=createLog1(okCaches,ok,conf)
	--PGC.print(okCaches)
	if fail==true then
	  ok=false
	end

	local points = nil
	if conf.pointsPer ~= nil then
		local pointField = conf.pointsField or error("For 'adv_number', when using points, you must specify the pointsField.")
		if okCaches[conf.pointsField] == nil then
			error("For 'adv_number', points field '" .. conf.pointsField.."' didn't exist.")
		end
		points = calculate_points(conf, ok, okCaches[conf.pointsField])
	end
	
	log = table.concat(log, "\n")
	html = table.concat(html, "<br>")
	slog = table.concat(slog, "\n")
	shtml = table.concat(shtml, "<br>")
	if conf.dt=="sum" then
	  ok=nil
	  html='<h3> "dt":"sum" is a old config and shall be changed to "dtsum":required dt sum limit is no longer used for dtsum<br>please contact script tagger</h3>'
	end
	if conf.brief==true then
		log=""
		html=""
	end

	return{ok = ok, log = log, html = html, slog = slog, shtml = shtml, points=points, caches=okCaches.caches }
end -- end function c_adv_numbers
-----------------------------------------------------
function simple_calendar_evaluation(res, status, conf, filter, extra_unused)
	local cell_fn = conf.cell_fn or {func="n"}										-- the function used to calculate the number in each cell. defaults to just the number in the list
	local placed = get_default(conf.placed, false)									-- whether this is checking hidden date (true), or visitdate (false)
	local limit = get_default(tonumber(conf.limit), 1)								-- the number you need on a day to pass that date

	local fields_required = { 'gccode', 'type', 'visitdate', 'hidden' }
	local cache_list = {}

	collect_opt_fields(cell_fn, fields_required)
	local myFinds = GetCombinedFinds(profileId, {lookup_cache=conf.lookup_cache,transforms=conf.transforms, fields = fields_required, order = 'OLDESTFIRST', filter = filter, includeLabCaches=conf.include_labs, gethides=conf.gethides} )

	for i, f in ipairs(myFinds) do
		if placed then
			if f['hidden'] ~= nil then
				day = string.sub(f['hidden'], 6)
			else
				day = "13-01"	-- Dummy date because lab caches don't have hidden date.
			end
		else
			day = string.sub(f['visitdate'], 6)
		end

		status[day] = (status[day] or 0) + 1
		if status[day] < limit then
			cache_list[day] = cache_list[day] or {}
			table.insert(cache_list[day], f)
		end
	end

	-- Convert the list of caches per day into 'status' which is the calculated number for that day.
	for day, cache_list_day in pairs(cache_list) do
		status[day] = cell_function_def[cell_fn.func](cache_list_day, cell_fn.opt)
		status[day] = math_clamp(status[day], (cell_fn.opt and cell_fn.opt.min) or -math.huge, (cell_fn.opt and cell_fn.opt.max) or math.huge)
	end

	return {} -- no extra output.
end
-----------------------------------------------------
function c_calendar(conf)
	return process_calendar(conf, simple_calendar_evaluation)
end
-----------------------------------------------------
function c_oldest_calendar(conf)
	local top_params = {}
	error_if(conf.placed ~= nil, "Cannot use conf.placed. It must always be true (it doesn't make sense to find the oldest cache on a day that you found it).")
	conf.placed = true 
	top_params.fetch = conf.fetch or 1000
	top_params.get_top_function = get_oldest
	top_params.next_expanded_filter_function = oldest_update_expanded_filter_function
	return process_calendar(conf, process_top_calendar, top_params)
end
-----------------------------------------------------
function c_topfav_calendar(conf)
	local top_params = {}
	local favorite_type = conf.favorite_type or 'points'			-- points, pct or wilson
	local favorite_field = nil
	if (favorite_type == 'wilson') then
		favorite_field = 'favorite_points_wilson'
	elseif (favorite_type == 'pct') then
		favorite_field = 'favorite_points_pct'
	else
		favorite_field = 'favorite_points'
	end

	error_if(conf.placed ~= nil, "Cannot use conf.placed. It must always be true (it doesn't make sense to find the most fav cache on a day that you found it).")
	conf.placed = true 
	top_params.fetch = conf.fetch or 1000
	top_params.get_top_function = get_top_favs
	top_params.next_expanded_filter_function = topfav_update_expanded_filter_function
	top_params.favorite_type = favorite_type
	top_params.fields_required = {favorite_field}
	return process_calendar(conf, process_top_calendar, top_params)
end
-----------------------------------------------------
function c_top_elevation_calendar(conf)
	local top_params = {}
	local top_type = conf.type or 'highest'			            -- 'highest' or 'lowest'. defaults to highest
	error_if(conf.placed ~= nil, "Cannot use conf.placed. It must always be true (it doesn't make sense to find the oldest cache on a day that you found it).")
	conf.placed = true 
	top_params.fetch = conf.fetch or 1000
	top_params.get_top_function = get_top_elevs
	top_params.next_expanded_filter_function = top_elevation_update_expanded_filter_function
	top_params.top_type=top_type
	top_params.fields_required = {"elevation"}
	return process_calendar(conf, process_top_calendar, top_params)
end
-----------------------------------------------------
function process_top_calendar(res, status, conf, filter, top_params)

    local owner_as_found = get_default(conf.owner_as_found, true)					-- count owned caches as found
	local allow_multiple_sameday = get_default(conf.allow_multiple_sameday, false)	-- If two caches were placed on the same day, allow multiple (true), otherwise, only the one with the lowest GCcode is considered

	local expanded_filter = TableCopy(filter)
	local get_top_function = top_params.get_top_function
	local next_expanded_filter_function = top_params.next_expanded_filter_function
	local days_remaining = 366
	local top_finds_date = {}
	local top_gccodes_date = {}
	local all_monthnames = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"}
	local monthnames = all_monthnames
	local month_counts = {0, 0, 0, 0, 0, 0, 0, 0, 0}
	local limit = get_default(conf.limit, 1)
	local fields_required = table_join({ 'gccode', 'visitdate', 'hidden', "cache_name" }, top_params.fields_required or {})
	local print_fields = conf.print_fields or fields_required

	error_if(conf.cell_fn ~= nil, "cell_fn is not supported in a top calendar.")

	while days_remaining > 0 do
		top_params.fetch = 1000

		DebugPrint("Calling get_top_function with top_params=" .. dump(top_params) .. "\n")
		local top_unfiltered = get_top_function(top_params, expanded_filter)

		error_if(#top_unfiltered == 0, "Could not satisfy getting " .. limit .. " caches after fully expanding the search. It may be that the caches do not exist.\n")
		DebugPrint("get_top_function returned " .. #top_unfiltered .. "\n")

		for _, top in ipairs(top_unfiltered) do
			local top_key = string.sub(top.hidden, 6,10)  -- Extract month-day from hidden date
			top_gccodes_date[top_key] = top_gccodes_date[top_key] or {} 
			if top_gccodes_date[top_key][top.gccode] == nil and not find_fails_filter(expanded_filter, top) and (tonumber(top.owner_id) ~= tonumber(profileId) or owner_as_found) then
				top_finds_date[top_key] = top_finds_date[top_key] or {not_archived=0}

				-- If we're not complete, OR they have the same exact hidden date.
				if top_finds_date[top_key].not_archived < limit or top.hidden == top_finds_date[top_key][#top_finds_date[top_key]].hidden then
					DebugPrint("Adding " .. PrintFindsText({top}, 1, {"gccode","cache_name"}, nil, true) .. " to " .. top_key .. "\n")
					table.insert(top_finds_date[top_key], top)
					top_gccodes_date[top_key][top.gccode] = true

					-- need to count the unarchived finds, so we can know if we have enough active caches for this DT.
					local archived = (tonumber(top.archived)~=0)
					top_finds_date[top_key].not_archived = top_finds_date[top_key].not_archived + (archived and 0 or 1)
					if not archived and top_finds_date[top_key].not_archived == limit then
						DebugPrint("Now have " .. top_finds_date[top_key].not_archived .. " for " .. top_key .. ", so marking as complete.\n")
						days_remaining = days_remaining - 1

						-- If we've completely satisfied a month, remove it from the list of available months, so we don't waste time fetching more of those.
						local month_idx = tonumber(string.sub(top_key, 1, 2))
						month_counts[month_idx] = (month_counts[month_idx] or 0) + 1						
						if month_counts[month_idx] == iso:parse(string.format("%04d-%02d-%02d", 2000, month_idx, 1)):last_day():day() then
							remove_from_list(monthnames[month_idx], monthnames)
							expanded_filter.monthnames = monthnames
						end
					end
				end
			end
		end

		-- If we don't have enough, filter only oldest from the newest one we have.
		if days_remaining > 0 then
			-- Allow the expand to modify fetch, which is not really part of the filter, but might give more results
			expanded_filter.fetch = top_params.fetch
			if not next_expanded_filter_function(expanded_filter, top_unfiltered[#top_unfiltered]) then
				error("Could not satisfy getting " .. limit .. " caches after fully expanding the search. It may be that the caches do not exist.\n")
			end
			fetch = expanded_filter.fetch
			expanded_filter.fetch = nil
		end
	end

	-- Go through, and remove all caches on the same hidden date, which are newer than the highest active cache (based on GCCode).
	if not allow_multiple_sameday then
		for top_key, top_date_list in pairs(top_finds_date) do
			table.sort(top_date_list, function(f1, f2) return f1.gccode < f2.gccode end)
			repeat
				while #top_date_list > 0 and tonumber(top_date_list[#top_date_list].archived) ~= 0 do
					table.remove(top_date_list, #top_date_list)
				end
				if #top_date_list > 0 and top_date_list.not_archived > limit then
					top_date_list.not_archived = top_date_list.not_archived - 1 
					table.remove(top_date_list, #top_date_list)
				end
			until #top_date_list == 0 or (top_date_list.not_archived <= limit and tonumber(top_date_list[#top_date_list].archived) == 0)
		end
	end

	-- Now figure out whether we FOUND those caches or not.
	local fetch_fields = table_join(fields_required, print_fields or {})
	local myFinds = GetCombinedFinds(profileId, {lookup_cache=conf.lookup_cache,transforms=conf.transforms, fields = fetch_fields, order = 'OLDESTFIRST', filter = filter, includeLabCaches=conf.include_labs, gethides=conf.gethides} )
	local finds_by_gccode = {}
	for i, f in ipairs(myFinds) do
		finds_by_gccode[f.gccode] = f
	end


	-- fill out the 'status' chart.
	local top_finds = {}
	for top_key, top_date_list in pairs(top_finds_date) do
		for _, cache in ipairs(top_date_list) do
			local archived = (tonumber(cache.archived)~=0)
			local owner = (tonumber(cache.owner_id) == tonumber(profileId)) and owner_as_found
			cache.found = (finds_by_gccode[cache.gccode] ~= nil or owner)
			if (cache.found) then
				local top_key = string.sub(cache.hidden, 6,10)
				status[top_key] = (status[top_key] or 0) + 1
				DebugPrint(top_key .. ": now have " .. status[top_key] .. "\n")

				if (owner) then
					DebugPrint(cache.gccode .. " - owned\n")
					cache.visitdate = "Owner"
				else
					cache.visitdate = finds_by_gccode[cache.gccode].visitdate
					cache.log_id = finds_by_gccode[cache.gccode].log_id
				end
			end

			if not archived or cache.found then
				table.insert(top_finds, cache)
			end
		end
	end

	-- Print out the list to the HTML.
	function get_row_style_log(cache)
		return cache.found or nil
	end
	function get_row_style_html(cache)
		local archived = (tonumber(cache.archived)~=0)
		local should_print = cache.found or (not archived and not print_only_found)
		if should_print then
			return archived and "color : red" or ""
		end		
		return nil
	end

	-- sort the top finds by their calendar date, so the list is more readable.
	table.sort(top_finds, function(f1, f2) return string.sub(f1.hidden, 6, 10) < string.sub(f2.hidden, 6, 10) end)

	-- also provide the list of result caches for a map.
	res.caches = top_finds

	local top_html = {}
	table.insert(top_html, "Considered caches per hidden date shown below. Archived finds will show in <span style='color: red;'>red</span>.<br/>")
	table.insert(top_html, "NOTE: If two caches have the same hidden date, the one with the lowest GCCode will be used.<br/>")
    table.insert(top_html, PrintFindsHtml(top_finds, #top_finds, print_fields, false, get_row_style_html))	
	return top_html
end

-----------------------------------------------------
function process_calendar(conf, calendar_evaluation_fn, calendar_evaluation_params)
	local status = { }
	local print_filter = conf.print_filter or false
	local auto_leap_year = get_default(conf.auto_leap_year, {[1]=false,[4]=true})	-- if true, min/max dates are inspected to determine whether any range includes a leap year. If not, needed autocalculates to 365/366, and the date is printed/not.
	local cell_fn = conf.cell_fn or {func="n"}										-- the function used to calculate the number in each cell. defaults to just the number in the list
	local icontype = conf.icon														-- the icon used for a passing date.
	local auto_icon = get_default(conf.auto_icon,{[1]=true,[5]=false})				-- whether icons are chosen automatically, if not specified.
	local streak = conf.streak														-- number of streak days required.
	local streak_wrap = get_default(conf.streak_wrap, true)							-- whether streaks should "wraparound" from december-january
	local placed = get_default(conf.placed, false)									-- whether this is checking hidden date (true), or visitdate (false)
	local limit = get_default(tonumber(conf.limit), 1)								-- the number you need on a day to pass that date
	local filter =  FilterFromConfig(conf)

	-- the minimum/maximum number of days completed to print the calendar out. Used mainly for "same" on attributes, because otherwise the HTML is too large.
	-- There are many attributes which are uncommon (or fully complete), and thus, we can basically 'ignore' when doing all attribute calendar checks.
	local min_print_calendar = conf.min_print_calendar or 0 
	local max_print_calendar = conf.max_print_calendar or math.huge

	error_if(conf.nooftypes ~= nil, "'calendar' nooftypes is deprecated.")
	error_if(conf.type ~= nil and conf.type ~= "", "usage of 'type' in calendar is deprecated. Use 'types' instead.")
	error_if(conf.placed == "birthday", "usage of 'placed=birthday' in calendar is deprecated.")
	error_if(streak and (type(streak)~='number' or streak <= 0 or streak >= 365), "'streak' must be an integer between 1..365" )
	error_if(streak and conf.needed, "Don't specify both 'streak' and 'needed'.")

	if type(placed) == "string" then
		placed = placed == "true"
	elseif type(placed) ~= "boolean" then
		error("conf.placed must be a boolean or string 'true'/'false'.")
	end

	if conf.leapday == "allow" then
		conf.leapday = "false"
	else
		conf.leapday = "true"
	end

	if icontype == nil and auto_icon then
		if filter.types~= nil and #filter.types== 1 then
			icontype=PGC.Icon.GeocacheType(filter.types[1])
		elseif limit == 1 then
			icontype =PGC.Icon.Check(false)
		end
	elseif icontype ~= nil then
		icontype="<img src='"..icontype.."'/>"
	end

	local process_leap_year = true
	if conf.needed == nil then
		if auto_leap_year then
			if placed then
				process_leap_year = date_range_includes_leapyear(filter['minHiddenDate'], filter['maxHiddenDate'])
			else
				process_leap_year = date_range_includes_leapyear(filter['minVisitDate'], filter['maxVisitDate'])
			end
			DebugPrint("auto_leap_year has determined is will use leap year: " .. (process_leap_year and "yes" or "no").."\n")

			conf.needed = process_leap_year and 366 or 365
		end

		-- if not doing anto_leap_year (or it was inconclusive), assume 366.
		if conf.needed == nil then
			conf.needed = 366
		end
	else
		conf.needed = tonumber(conf.needed)
	end

	local res = {}
	local extra_html = calendar_evaluation_fn(res, status, conf, filter, calendar_evaluation_params)

	-- What is done?
	local numdone = 0
	local monthsdone = {}
	local current_streak = 0
	local max_streak = 0
	local current_streak_start
	local max_streak_start
	local daysinmonth = { 31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 }

	-- need to do two passes for streak calculation, as it may wraparound december-january.
	if streak then
		for streak_pass = 1, (streak_wrap and 2 or 1) do
			for month = 1, 12 do
				local prevnumdone = numdone
				for day = 1, daysinmonth[month] do
					local key = makekey(month, day)
					if status[key] ~= nil and status[key] >= limit then
						if streak_pass == 1 then
							numdone = numdone + 1
						end

						-- check if you've streaked the whole year and shortcircuit.
						if streak_pass == 2 and key == current_streak_start then
							current_streak = -1
						end

						if current_streak == 0 then
							current_streak_start = key
						end
						current_streak = current_streak + 1
						if current_streak > max_streak then
							max_streak = current_streak
							max_streak_start = current_streak_start
						end
					else
						if month ~= 2 or day ~= 29 or conf.leapday == "false" then
							current_streak = 0
							current_streak_start = ""
							if streak_pass > 1 then
								break
							end
						end
					end

					if current_streak <= 0 and streak_pass > 1 then
						break
					end
				end

				if streak_pass == 1 then
					if (numdone - prevnumdone) == daysinmonth[month] or (conf.leapday == "false" and month == 2 and (numdone - prevnumdone) == 28 and
							(status[makekey(2,29)] == nil or (status[makekey(2,29)] ~= nil and status[makekey(2,29)] < limit))) then
						table.insert(monthsdone,month)
					end
				end
			end
		end
	else
		-- just a normal "how many are done" calculation
		for month = 1, 12 do
			for day = 1, daysinmonth[month] do
				local key = makekey(month, day)
				numdone = numdone + ((status[key] ~= nil and status[key] >= limit) and 1 or 0)
			end
		end
	end

    local ok = false
	local log = ""
	local dates = ""
	local html = ""
	local slog=""
	local shtml=""
	local missing = { }
	local statustable = { }

	-- Check if completed.
	if conf.monthsneeded ~= nil then
		if #monthsdone >= conf.monthsneeded then
			ok = true
		end

		slog = #monthsdone .. " months of " .. conf.monthsneeded .. " completed. "
		if conf.leapday == "false" then
			slog = slog .. "This challenge allows leap day to be skipped. "
		end
	elseif streak then
		ok = max_streak >= streak
		slog = slog .. "\nCalendar streak was " .. max_streak .. " out of a required " .. streak .. " days."
	else
		if numdone >= conf.needed then
			ok = true
		-- special case - if you have 365/366, and don't have leapday but didn't need it, it's still a pass.
		elseif conf.needed == 366 and numdone == 365 and conf.leapday == "false" and (status[makekey(2,29)] == nil or (status[makekey(2,29)] ~= nil and status[makekey(2,29)] < limit)) then
			DebugPrint("Had only " .. numdone .. " / " .. conf.needed .. " however, leapday=false, and leapday not satisfied, so it's a pass.\n")
			ok = true
		end

	  slog = numdone .. " dates of " .. conf.needed .. " completed. "
	  if conf.leapday == "false" then
		slog = slog .. "This challenge allows leap day to be skipped. "
	  end
	end

	-- Build log entry.
  local missing = { }
  local statustable = { }

  if (print_filter) then
	table.insert(statustable, PrintFilter(filter))
  end
  
  -- Show what is done and what is missing.
  local streak_days_remaining = 0
	if numdone >= min_print_calendar and numdone < max_print_calendar then 
		table.insert(statustable, "<table class='"..g_table_class.."' style='table-layout: fixed;border:2px solid black;border-collapse: collapse;'>")
		table.insert(statustable, "<tr style='border:2px solid black'>")
		table.insert(statustable, "<th style='width:32px;'></th>")
		for day = 1, 31 do
			table.insert(statustable, "<th style='background-color: #dddddd;width:16px;'>" .. day .. "</th>")
		end
		table.insert(statustable, "</tr>")
		for month = 1, 12 do
			table.insert(statustable, "<tr>")
			table.insert(statustable, "<td style='border-right:2px solid black;background-color: #dddddd'><b>" .. iso:parse(string.format("2000-%02d-01",month)):month_name(false) .. "</b></td>")
			for day = 1, 31 do
				local is_leap_day = month == 2 and day == 29
				local key = makekey(month, day)
				status[key] = status[key] or 0

				if streak and key == max_streak_start then
					streak_days_remaining = max_streak
				end

				if day <= daysinmonth[month] and (not is_leap_day or process_leap_year) then
					local part_of_streak = streak and streak_days_remaining > 0
					local background_color
					local diff = limit - status[key]
					if diff > 0 then
						background_color = string.format("rgba(192, 0,0, %.3f)", 0.15 + 0.5 * diff / limit )
						table.insert(statustable, "<td style='background-color:".. background_color .."'>".. status[key] .."</td>")
					else
						background_color = string.format("rgba(0, 255,0, %.3f)", part_of_streak and 0.8 or 0.5)
						table.insert(statustable, "<td style='background-color:".. background_color .. "'>".. (icontype ~= nil and icontype or status[key]) .."</td>")
					end
					streak_days_remaining = math.max(0,streak_days_remaining - 1)
				else
					table.insert(statustable, "<td style='background-color:grey'></td>")
				end
			end
			table.insert(statustable, "</tr>")
		end
		table.insert(statustable, "</table>")
	else
		if numdone < min_print_calendar then
			table.insert(statustable, "Not printing calendar to reduce HTML output, too few days completed ("..numdone.."/"..min_print_calendar..")")
		else
			table.insert(statustable, "Not printing calendar to reduce HTML output, too many days completed ("..numdone.."/"..max_print_calendar..")")
		end
	end
	
	-- Report results.
	res.ok     = ok
	res.log    = log
	res.slog   = slog .. PrintFilter(filter)
	res.shtml  = res.slog
	res.html   = table.concat(statustable, "")
	res.html   = res.html .. table.concat(extra_html, "")
	res.points = calculate_points(conf,ok, numdone)

	return res
end -- end function c_calendar
