-- https://project-gc.com/Challenges//76461?edit&addTag&tagId=76461
-- Adapted from Calendar with limited number of values by arisoft, except can now use any generic criteria, as with generic_fizzy.
function c_generic_calendar(conf)

	local filter=FilterFromConfig(conf)												-- standard filter.
	local criteria_list = conf.criteria	or error("Must supply 'criteria' list")		-- list of criteria
	local date_field = conf.date_field or "visitdate"								-- field to use for dates from finds (ie. visitdate/hidden/etc)
    local owner_as_found = get_default(conf.owner_as_found, true)					-- count owned caches as found

	local fields_required = {'gccode', date_field}
	local starttime = os.clock()
	local daysleft = 0
			
	-- Calculate the required number of fizzy spots filled, based on the sum of the criteria
	-- Also generate ALL the extra fields that we will required for all fizzy defs, so we can call GetFinds only once.
	local criteria_index = 1
	for _, criteria in ipairs(criteria_list) do
		for _, fi in ipairs(fields_in_criteria(criteria) or {}) do
			insert_into_list_if_unique(fi, fields_required)
		end
	end

	-- Get Finds
	finds = GetCombinedFinds(profileId, { lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = fields_required, order = 'OLDESTFIRST', filter = filter, includeLabCaches = conf.include_labs })

	-- Generate Calendar
	local day_hash = {}
	fmt = Date.Format("mm-dd")
	cal = Date { year = 2000, month = 1, day = 1 }
	repeat
		local date = fmt:tostring(cal)
		day_hash[date] = {date = date, criteria = {}}
		cal:add { day = 1 }
	until cal:year() > 2000

	-- Preprocessing finds
	for _,criteria in ipairs(criteria_list) do 
		criteria.days = {}
		criteria.claimed = 0
		criteria.left = 0
		if criteria.count then
			if criteria.min ~= nil or criteria.max ~= nil then
				error("Supplied criteria.count and criteria.min/max. Can't have both.")
			end
			criteria.min = criteria.count
			criteria.max = criteria.count
		else
			criteria.min = criteria.min or 0
			criteria.max = criteria.max or 366
		end
	end

	for _,cache in ipairs(finds) do
		if owner_as_found or profileId ~= cache.owner_id then
			for _,criteria in ipairs(criteria_list) do
				if find_satisfies_criteria(cache, criteria) then
					local criteria_key = criteria_as_string(criteria)
					local date = string.sub(cache[date_field],6,10)
					local day = day_hash[date]
					if not day.criteria[criteria_key] then
						table.insert(criteria.days, day)
						day.criteria[criteria_key] = cache
						if day.used == nil then
							day.used = false
							daysleft = daysleft + 1 
						end
					end
				end
			end
		end
	end
	for _,criteria in ipairs(criteria_list) do
		criteria.left = #criteria.days
	end
	
	DebugPrint("daysleft="..daysleft.."\n")

	-- Solving calendar

	-- Dynamic search depth limitter 
	-- Limits search depth to rational level if time is running out
	function timeout()
		local timer = os.clock() - starttime
		local depth = math.floor(25 - timer)
		if depth < 1 then depth = 1 end
		if depth < maxdepth then maxdepth = depth end
	end

	-- Insert value to calendar by recursively swapping existing values
	function insert(criteria,deep)

		-- Looking for unused day for value
		while criteria.left > 0 do
			local day = criteria.days[criteria.left]
			criteria.left = criteria.left - 1
			if not day.selected then
				day.selected = criteria
				daysleft = daysleft - 1
				return deep
			end
		end

		deep = deep + 1
		if deep > worstdepth then 
			timeout()
			worstdepth = deep 
		end
		if deep > maxdepth then
			timeout()
			return 0 
		end

		-- Trying to swap value to any conflictiong day
		local tried = {[criteria]=true}
		for _,day in ipairs(criteria.days) do
			local previous = day.selected
			if previous then
				if not tried[previous] and not day.used then
					day.used = true
					local dep = insert(previous,deep)
					day.used = false
					if dep > 0 then
						day.selected = criteria
						return dep
					end
					tried[previous] = true
				end
			end
		end
		return 0
	end

	-- Pushing values to calendar
	function push(criteria)
		timeout()
		worstdepth = 0
		local start = os.clock()
		local dep = insert(criteria,1)
		local timer = os.clock()-start
		if timer >= 0.001 or dep ~= 1 then 
			DebugPrint(criteria.value,", ",dep, '/', worstdepth, '/', maxdepth,' ',string.format('%.3f',timer),"s\n") 
		end
		return dep > 0
	end

	-- Find mandatory values
	maxdepth = 20
	for _,criteria in ipairs(criteria_list) do 
		while daysleft > 0 and criteria.claimed < criteria.min do
			if push(criteria) then 
				criteria.claimed = criteria.claimed + 1
			else
				break
			end
		end
	end
	DebugPrint("Minimum condition achieved in ",string.format('%.3f',os.clock()-starttime),"s\n")

	-- Find remaining values
	maxdepth = 5 -- quick and dirty
	for _,criteria in ipairs(criteria_list) do 
		while daysleft > 0 and criteria.claimed < criteria.max do
			if push(criteria) then 
				criteria.claimed = criteria.claimed + 1
			else
				break
			end
		end
	end
	if daysleft > 0 then -- trying harder
		maxdepth = 20
		for _,criteria in ipairs(criteria_list) do 
			while daysleft > 0 and criteria.claimed < criteria.max do
				if push(criteria) then 
					criteria.claimed = criteria.claimed + 1
				else
					break
				end
			end
		end
	end

	-- Make sure they passed
	local res = {}
	res.shtml = ""
	res.slog =  ""
	res.ok = true

	-- Make that all the min/max are in range.
	for _, criteria in ipairs(criteria_list) do
		local passed_criteria = criteria.claimed >= criteria.min and criteria.claimed <= criteria.max
		res.ok = res.ok and passed_criteria
		res.shtml = res.shtml .. ok_html(passed_criteria) ..": " ..  criteria_as_string(criteria) .. " - found a required " .. criteria.claimed .. " (required range "..criteria.min.." - " .. criteria.max..")<br/>"
		res.slog = res.slog .. ok_text(passed_criteria) ..": ".. criteria_as_string(criteria) .. " - found a required " .. criteria.claimed .. " (required range "..criteria.min.." - " .. criteria.max..")\n"
	end

	function print_calendar(day_hash, cell_pass_fn, cell_print_pass, cell_print_fail, cell_print_na)

		-- Build log entry.
		local missing = { }
		local statustable = { }

		-- If they don't give an N/A then just print "X"
		cell_print_na = cell_print_na or 
			function(key)
				return "X"
			end
		if cell_pass_fn == nil or cell_print_pass == nil or cell_print_fail == nil then
			error("Must pass all of cell_pass_fn, cell_print_pass, cell_print_fail to print_calendar (script error, please report)")
		end

		-- Show what is done and what is missing.
		table.insert(statustable, "<table class=\""..g_table_class.."\"><tr><td></td>")
		table.insert(statustable, "<tr>")
		table.insert(statustable, "<td></td>")
		for day = 1, 31 do
			table.insert(statustable, "<td>" .. day .. "</td>")
		end
		table.insert(statustable, "</tr>")
		for month = 1, 12 do
			local dobj = iso:parse(string.format("2000-%02d-01",month))
			local daysinmonth = dobj:last_day():day()
			table.insert(statustable, "<tr>")
			table.insert(statustable, "<td>" .. dobj:month_name() .. "</td>")
			
			for day = 1, 31 do
				local key = makekey(month, day)
				local cell_result
				local day_struct = day_hash[key]
				if day <= daysinmonth then
					if not cell_pass_fn(key, day_struct) then
						cell_result = cell_print_fail(key, day_struct)
					else
						cell_result = cell_print_pass(key, day_struct)
					end
				else
					cell_result = cell_print_na(key)
				end

				table.insert(statustable, "<td>".. cell_result .. "</td>")
			end
			table.insert(statustable, "</tr>")
		end
		table.insert(statustable, "</table>")
		return statustable, missing
	end

	local calendar_html, missing = 
		print_calendar(day_hash, 
			function(key, day) return day ~= nil and day.selected ~= nil end,
			function(key, day) return get_html_for_criteria_struct(true, day.selected) end,
			function(key,day) return res.ok and "" or ok_html(false) end )
	

	res.shtml = res.shtml .. "<br/>" .. table.concat(calendar_html, "<br/>")
	res.html = ""
	res.log = ""
	return res

end -- generic_calendar

