function c_ok(conf)
  local tmp="OK:"
  if conf.txt~= nil then
    tmp=tmp..conf.txt
  end
  return {ok=true,slog=tmp,log=tmp,shtml=tmp,html=tmp}
end
-----------------------------------------------------
function c_info(conf)
  local tmp=conf.txt
  return {ok="info",slog=tmp,log=tmp,shtml=tmp,html=tmp}
end
