function c_number(conf)
  	local options ={"limit","brief","pointsPer", "printFields", "print_fields", "print_limit","limit_results"}
  	if extraInConfig(conf,options)==true then
    	return{ok=nil,log=nil,html=nil}
    end
  	local filter=FilterFromConfig(conf)
	local fields = get_default(conf.printFields or conf.print_fields, {[0]={'gccode', 'cache_name'},[3]={'gccode','visitdate','icon','cache_name'}})
	local limit = conf.limit or 1

	-- special case: if maxPoints is passed in, calculate the number of points required to reach max points, and limit to that.
	if limit == "maxPoints" then
		error_if(conf.maxPoints == nil or conf.pointsPer == nil, "If using limit='maxPoints', must supply maxPoints and pointsPer")
		limit = conf.maxPoints / conf.pointsPer
	end

	local limit_results = get_default(conf.limit_results, true)
    local print_limit = conf.print_limit or (limit_results and limit or math.huge)
	local finds = GetCombinedFinds(profileId, { sort_order=conf.sort_order, lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = fields, order = 'OLDESTFIRST', filter = filter, includeLabCaches = conf.include_labs,gethides=conf.gethides })
	local ok=false
	if #finds >= limit then
		if conf.upperlimit == nil or conf.upperlimit >= #finds then
			ok = true
		end
	end
	local slog = "User has " .. #finds .. " finds (" .. limit .. " needed) "
	if conf.upperlimit ~= nil then
		slog = slog .. "(max " .. conf.upperlimit .. ") "
	end
	slog = slog..PrintFilter(filter).."\n"
	local shtml = "User has " .. #finds .. " finds (" .. limit .. " needed) "
	if conf.upperlimit ~= nil then
		shtml = shtml .. "(max " .. conf.upperlimit .. ") "
	end
	shtml = shtml..PrintFilter(filter)
	local log = slog..PrintFindsText(finds,print_limit,fields)
	local html = shtml..PrintFindsHtml(finds,print_limit,fields)
  	if conf.brief== true then
    	log=""
    	html=""
    end

	local points = calculate_points(conf, ok, finds)

	local caches = finds
	if (limit_results) then
		caches = array_splice(finds,1,limit)
	end
	return{ok = ok, log = log, html = html, slog = slog, shtml = shtml, points = points, caches =  caches}
end -- end function c_number

