function c_elevation(conf)

	-- note: pointType can be 'finds', 'total_elevation' or 'delta' (if conf.delta is non-nil)
	local options ={"limit","brief","pointsPer","pointType","elevation", "total_elevation","lowest"}
	local filter=FilterFromConfig(conf)
	local fields = {'gccode', 'visitdate', 'cache_name', 'elevation'}
	local print_fields = conf.print_fields or fields
	local lowest = conf.lowest or false	-- lowest tries to find below a ceratin threshold, otherwise, find above.
	local delta = conf.delta			-- if non-nil, you need to have an elevation delta of at least 'delta' meters.
	local limit = conf.limit or 0
	conf.elevation = conf.elevation or 0

	local finds = GetCombinedFinds(profileId, { lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = table_join(fields,print_fields), order = 'OLDESTFIRST', filter = filter })
	for _,f in ipairs(finds) do
		f.elevation = tonumber(f.elevation)
  	end

	if lowest then
		table.sort(finds, function(f1,f2) return f1.elevation < f2.elevation end)
	else
  		table.sort(finds, function(f1,f2) return f1.elevation > f2.elevation end)
  	end

  local ok=false
  local okfinds = {}
  local total_elevation = 0
  if delta == nil then
	for _, c in ipairs(finds) do
		if ((not lowest and c.elevation >= conf.elevation) or (lowest and c.elevation <= conf.elevation)) and #okfinds < limit then
			total_elevation = total_elevation + c.elevation
			table.insert(okfinds, c)
		end
	end
  end

   local delta_value = #finds >0 and math.abs(finds[1].elevation - finds[#finds].elevation) or 0
  if conf.total_elevation ~= nil then
	ok = (not lowest and total_elevation >= conf.total_elevation) or (lowest and total_elevation <= conf.total_elevation)
  elseif conf.delta ~= nil then
	ok = delta_value >= delta
  elseif #okfinds >= limit then
	ok = true
  end

  local log = ""
  local html = ""
  local slog = ""
  local shtml = ""

	if delta == nil then
		pointType = pointType or "finds"
		slog = "User has " .. #okfinds .. " finds (" .. limit .. " needed) "
		slog = slog..PrintFilter(filter).." at elevation "..conf.elevation.."m or " .. (lowest and "less" or "more") .. "\n"
		if conf.total_elevation ~= nil then
			slog = slog .. "\nTotal elevation of these finds is " .. total_elevation .. " (" .. conf.total_elevation .. " needed)"
		end
		log = slog..PrintFindsText(finds,limit,print_fields)
		shtml = slog.gsub(slog, "\n", "<br/>")..PrintFindsHtml(finds,limit,print_fields)
	else
		-- delta between values required
		if #finds >= 2 then
			local highest_lowest = {finds[1], finds[#finds]}
			slog = "User has " .. (delta_value) .. "m between highest and lowest finds (" .. delta  .. " needed) " ..PrintFilter(filter)
			log = slog..PrintFindsText(highest_lowest,#highest_lowest, print_fields)
			shtml = slog.gsub(slog, "\n", "<br/>")..PrintFindsHtml(highest_lowest,#highest_lowest,print_fields)
		else
			log = "You have less than 2 finds. Go find a couple, and try again."
			shtml = log
		end
	end

	if conf.brief== true then
		log=""
		html=""
	end

  local points = nil
	if conf.pointsPer ~= nil then
		points = 0
		function points_per_find(f, pointType, pointsPer)
			if pointType == "finds" then
				return pointsPer
			elseif pointType == "total_elevation" or pointType == "total" then
				if lowest then
					return -f.elevation * pointsPer
				else
					return f.elevation * pointsPer
				end
			elseif pointType == "delta" then
				return pointsPer * delta_value
			else
				error("Unrecognized pointType = " .. pointType)
			end
		  end

		for _, f in ipairs(okfinds) do
			points = points + points_per_find(f, conf.pointType, conf.pointsPer)
		end


		if conf.skipPoints ~= nil then
			if points <= conf.skipPoints then
				points = 0
			else
				points = points - conf.skipPoints
			end
		end
		if conf.maxPoints ~= nil and points > conf.maxPoints then
			points = conf.maxPoints
		end
	end

  return{ok = ok, log = log, html = html, slog = slog, shtml = shtml, points = points }
end -- end function c_elevation

