function c_range(conf)
  	local options ={"limit","brief","pointsPer"}
  	local filter=FilterFromConfig(conf)
	local fields = {'gccode', 'cache_name', conf.field}
	local print_fields = conf.print_fields or fields
	local fetch_fields = array_join(fields, print_fields)
	local myFinds = GetCombinedFinds(profileId, { lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = fetch_fields, order = 'OLDESTFIRST', filter = filter, includeLabCaches=conf.include_labs })
	local ok=false
	local finds = {}

	for _,f in ipairs(myFinds) do
    	local val = tonumber(f[conf.field])
    	if val == nil then
      		DebugPrint("Value not available. Field: "..conf.field..", cache: "..f.gccode.."\n")
    	else
			if (conf.min == nil or conf.min <= val) then
				if (conf.max == nil or conf.max >= val) then
					table.insert(finds,f)
          		end
			end
		end
	end

	if #finds >= conf.limit then
	    ok = true
	end

	local fieldInfo = " Field: "..conf.field
	if (conf.min ~= nil) then
		fieldInfo = fieldInfo .. ", min: " .. conf.min
	end
	if (conf.max ~= nil) then
		fieldInfo = fieldInfo .. ", max: " .. conf.max
	end

	local slog = "User has " .. #finds .. " finds (" .. conf.limit .. " needed)."..PrintFilter(filter)..fieldInfo.."\n"
	local shtml = "User has " .. #finds .. " finds (" .. conf.limit .. " needed)."..PrintFilter(filter)..fieldInfo
	local log = slog..PrintFindsText(finds,conf.limit,print_fields)
	local html = shtml..PrintFindsHtml(finds,conf.limit,print_fields)
  	if conf.brief== true then
    	log=""
    	html=""
    end

	local points = calculate_points(conf, ok, #finds)

	return{ok = ok, log = log, html = html, slog = slog, shtml = shtml, points = points }
end -- end function c_range

