      res.shtml="<tbody><tr><td>"..ok_html(false).."</td><td>".."No in pre_check found" .."</td></tr>"
    end
    res.shtml='<table class=\"'..g_table_class..'\"><thead><tr><th>'..ok_html(res.ok)..'</th><th>in_a_year:pre_check:only years with found in :'..PrintFilter(y_filter)..'are checked</th></tr></thead>'
              ..res.shtml.."</tbody></table>"
    res.slog=ok_text(res.ok)..": in_a_year{\n"..res.slog.."}\n"

	return res
end --end function l_in_a_year
-----------------------------------------------------
function l_points(arg,filter,opt)
    local res={}
    local count=0

	local logic_short_circuit = opt.logic_short_circuit or false												-- If you reach points_total, then don't process further
	local exclude_result_caches = opt.exclude_result_caches or false											-- If true, any caches returned from res.caches will be excluded from further searches.
	local points_op = opt.points_op or '+'																		-- Binary operator to perform between subsequent point calcuations (eg. can set to "*" to multiply point results together)
	local exclude_caches = exclude_result_caches and opt.excludeCaches or {}									-- Caches to exclude from sub-ops.
	local was_short_circuit = false																				-- Whether short-circuiting was used in calculating the points total.
	local log_headers = opt.log_headers or false
	local html_headers = opt.html_headers or false

	if type(arg) ~= 'table' then
		error("func='points' expects 'conf' to be an array.")
	end

    local l_arg=TableCopy(arg)
	local points_total=0
	local req_points_total = opt.points_total or opt.maxPoints or error("opt.points_total required an not provided in func='points'.")
	res.ok=false
	local thousands_separator = ","
	if opt.thousands_separator ~= nil then
		thousands_separator = opt.thousands_separator
	end
	local prefix = ""
	if opt.prefix ~= nil then
		prefix = opt.prefix
	end
	local postfix = ""
	if opt.postfix ~= nil then
		postfix = opt.postfix
	end

	function points(i,o)
		if o.ok == true then
			if i.points ~= nil then
				return i.points
			elseif o.points ~= nil then
				return o.points
			else
				return 1
			end
		else
			local points_struct = 
				i.conf ~= nil and i.conf.point or 
				(g_globals[i.func] ~= nil and g_globals[i.func].conf ~= nil) and g_globals[i.func].conf.points or nil
			if type(points_struct) == "table" and points_struct.points_require_pass then
				return points_struct.fail_points or 0
			else
				return 0
			end
		end
	end

	function printPoints(p,res, was_sc)
		was_sc = was_sc or false
		if res.ok == "info" then
			return ""
		elseif opt.round ~= nil then
			return prefix .. string.format("%."..opt.round.."f",p) .. postfix .. (was_sc and " (truncated)" or "")
		elseif p < 10000 then
			return prefix .. p .. postfix .. (was_sc and " (truncated)" or "")
		else
			local pp = {}
			while p >= 1000 do
				tmp = math.floor(p / 1000)
				r = p - (tmp * 1000)
				hun = math.floor(r/100)
				ten = math.floor((r-(hun*100))/10)
				one = r - (hun*100) - (ten*10)
				rStr = hun .. ten .. one
				table.insert(pp,1,rStr)
				p = tmp
			end
			table.insert(pp,1,p)
			return prefix .. table.concat(pp,thousands_separator) .. postfix .. (was_sc and " (truncated)" or "")
		end
	end

    for _,t in pairs(l_arg) do

		if opt ~= nil and opt.func ~= nil and t.func == nil then
			t.func = opt.func
		end
		if opt ~= nil and opt.conf ~= nil then
			t.conf = t.conf or {}
			for n,v in pairs(opt.conf) do
				if t.conf[n] == nil then
					t.conf[n] = v
				end
			end
		end

		if t.func == nil and g_conf.default_func == nil then
			error("t.func is nil, and default_func is nil. Don't know what to do here. While processing " .. dump(t).."\n")
		end

		count=count+1
		if filter~= nil then
			apply_conf_filter_to_subconfs(t, filter)
		end

		-- If caches from subsequent operations should not be returned in future results, add them to the exclude list.
		if exclude_result_caches then
			-- Possible that t.conf is an array of conf - in that case, pass filter down to opt, which array funcs pick up on.
			if #t.conf == 0 then
				t.conf['excludeCaches']=exclude_caches
			else
				t.opt['excludeCaches']=exclude_caches
			end
		end

		-- Also, we may apply an iterative maxPoints
		if opt.maxPoints ~= nil then
			local remaining_points = math.max(0, opt.maxPoints - points_total)
			apply_conf_filter_to_subconfs(t, {maxPoints=remaining_points})
		end

		-- Now actually do the lookup.
		local tmp=lookup(t.func,t.conf,filter,t.opt)
		if tmp.log == nil then tmp.log = "" end
		if tmp.html == nil then tmp.html = "" end
		if tmp.slog == nil then tmp.slog = "" end
		if tmp.shtml == nil then tmp.shtml = "" end

		-- Add in a header, which is kind of like an "info" statement.
		if t.header ~= nil then
			local header = (t.header_bold and "<b>" or "").. t.header .. (t.header_bold and "</b>" or "")
			tmp.shtml = "<table class=\""..g_table_class.."\" width='100%'><tbody><tr><td>"..header.."</td></tr><tr><td>"..tmp.shtml.."</td>/<tr></tbody></table>"
		end

		if count==1 then
			res.log=tmp.log
			res.html=( (html_headers and t.header ~= nil) and (t.header.."<br/>") or "" )..tmp.html
			res.slog=printPoints(points(t,tmp),tmp)..": ".. ( (log_headers and t.header ~= nil) and (t.header.."\n") or "" ) .. tmp.slog
			res.shtml="<tbody><tr><td>"..printPoints(points(t,tmp),tmp).."</td><td>"..tmp.shtml.."</td></tr>"
			points_total = points(t,tmp)
		else
			res.log=res.log.."\n"..tmp.log
			res.html=res.html.."<br>"..( (html_headers and t.header ~= nil) and (t.header.."<br/>") or "" )..tmp.html
			res.slog=res.slog.."\n"..printPoints(points(t,tmp),tmp)..": ".. ( (log_headers and t.header ~= nil) and (t.header.."\n") or "" ) .. tmp.slog
			res.shtml=res.shtml.."<tr><td>"..printPoints(points(t,tmp),tmp).."</td><td>"..tmp.shtml.."</td></tr>"
			points_total = binary_operation(points_op, points_total, points(t,tmp))
		end

		-- If caches from subsequent operations should not be returned in future results, add them to the exclude list.
		if exclude_result_caches and tmp.ok == true then
			exclude_caches = array_join(exclude_caches, array_field_as_array(tmp.caches or {},'gccode'))
		end
		res.caches = array_join(res.caches or {}, tmp.caches or {})

		if logic_short_circuit then
			if points_total >= req_points_total then
				was_short_circuit = true
				break
			end
		end
	end

	if points_total >= req_points_total then
		res.ok = true
	end

	if opt.skipPoints ~= nil then
		if points_total <= opt.skipPoints then
			points_total = 0
		else
			points_total = points_total - opt.skipPoints
		end
	end

	if opt.maxPoints ~= nil and points_total > opt.maxPoints then
		points_total = opt.maxPoints
	end
	res.points = points_total

	if opt.points ~= nil then 
		res.points = opt.points 
	end

	res.shtml='<table class=\"'..g_table_class..'\"><thead><tr><th>'..printPoints(points_total,res, was_short_circuit)..'</th><th>Points (out of a required '.. req_points_total..')</th></tr></thead>'..res.shtml.."</tbody></table>"
	res.slog=ok_text(res.ok)..": Points ("..printPoints(points_total,res, was_short_circuit).."){\n"..res.slog.."\n}"
	return res
end --end function l_points
-----------------------------------------------------
function l_bingo(conf,filter,opt)

	opt = opt or {}
	local column_names = opt.column_names or {'B','I','N','G','O'}
	local row_names = opt.row_names or {'1','2','3','4','5'}
	local patterns = opt.match_patterns or opt.patterns
	local required_matches = opt.required_matches or opt.minPatterns or 1
	local require_descs = get_default(opt.require_descs, true)
	local show_cell_logs = opt.cell_logs or "none"  -- "none" (don't show any logs from individual cells), "pass" (only show passing cells), "fail" (only show failing cells), "all" (show all)

	-- If they don't supply the patterns, then just generate every row, column and diagonal.
	if patterns == nil then
		patterns = {}
		for c=1,#column_names do			
			local newp = {}
			for r=1,#row_names do
				table.insert(newp, column_names[c]..row_names[r])
			end
			table.insert(patterns,newp)
		end
		for r=1,#row_names do
			local newp = {}
			for c=1,#column_names do			
				table.insert(newp, column_names[c]..row_names[r])
			end
			table.insert(patterns,newp)
		end
		if #column_names == #row_names then
			local newp = {}
			local newp2 = {}
			for i=1,#column_names do
				table.insert(newp , column_names[i]..row_names[i])
				table.insert(newp2, column_names[#column_names-i+1]..row_names[i])
			end
			table.insert(patterns,newp)
			table.insert(patterns,newp2)
		end
	end

	-- Make sure that they've specificed every item. 
	local cells = {}
	for _, cn in pairs(column_names) do
		for _, rn in pairs(row_names) do
			local computed_name = cn .. rn
			cells[computed_name] = {}
			if conf[computed_name] == nil then
				error("'conf' has not entry for '"..computed_name.."'.")
			end
			-- Also make sure there's a 'nice' description.
			if conf[computed_name].desc == nil then
				if require_descs then
					error("'conf["..computed_name.."].desc' is not specified.")
				else
					conf[computed_name].desc = computed_name
				end
			end
		end
	end

	-- Make sure there are no conf items that aren't one of the names in the card.
	for name, c in pairs(conf) do
		if cells[name] == nil then
			error("'conf' has an entry '"..name.."', but it doesn't exist in the bingo card.")
		end
	end
		
	-- Now actually run the tests.
	local results = {}
    for name,t in pairs(conf) do

		-- Copy the config from opt, if it's there, and doesn't exist.
		if opt ~= nil and opt.func ~= nil and t.func == nil then
			t.func = opt.func
		end
		if opt ~= nil and opt.conf ~= nil then
			for n,v in pairs(opt.conf) do
				if t.conf[n] == nil then
					t.conf[n] = v
				end
			end
		end

		if filter~= nil then
			apply_conf_filter_to_subconfs(t, filter)
		end

		local tmp=lookup(t.func,t.conf,filter,t.opt)
		results[name]=tmp
	end

	-- Figure out which patterns they've passed
	local passing_patterns = {}
	local cell_status = {}
	for _,pattern in ipairs(patterns) do
		local pattern_result = true
		for _, entry in ipairs(pattern) do
			local tmp = results[entry]
			if tmp == nil then
				error("results of '" .. entry .. "' didn't exist.")
			elseif pattern_result == "info" then
				error("You can't have an 'info' result as a bingo entry.")
			elseif tmp.ok ~= "info" then
				pattern_result=pattern_result and tmp.ok
			end	
		end

		if pattern_result == true then
			table.insert(passing_patterns, pattern)
			for _, e in ipairs(pattern) do
				cells[e].ok = true
			end
		end
	end

	-- Now build the final results.
	local res = {}
	res.ok = #passing_patterns >= required_matches

	local result_text = ok_text(res.ok) .. ": You passed " .. #passing_patterns .. " out of a required " .. required_matches
	local pass_table = {result_text}
	for _, pass in ipairs(passing_patterns) do
		table.insert(pass_table, "You passed: " .. table.concat(pass, ", "))
	end

	local html = TableCopy(pass_table)
	table.insert(html,"")
	table.insert(html, "<table class=\""..g_table_class.."\"><thead><tr><td width='50'/>")
	for _, cn in ipairs(column_names) do
		table.insert(html, "<td width='200' style='font-size:36pt'><center><b>"..cn.."</b></center></td>")
	end
	table.insert(html, "</tr></thead>")

	for _, rn in ipairs(row_names) do
		table.insert(html,"<tr><td style='font-size:36pt'><center><b>"..rn.."</b></center></td>")
		for _, cn in ipairs(column_names) do
			local cell_name = cn..rn
			local cell_bgstyle = ""
			if cells[cell_name].ok == true then 
				cell_bgstyle = "style='background-color:rgba(0,255,0,0.5)'"
			end
			table.insert(html, "<td " .. cell_bgstyle .. "><center>")
			table.insert(html, conf[cell_name].desc.."<br/>"..ok_html(results[cell_name].ok).."</center></td>")
		end		
		table.insert(html,"</tr>")
	end

	for _, rn in ipairs(row_names) do
		for _, cn in ipairs(column_names) do
			local cell_name = cn..rn
			if show_cell_logs == "pass" and results[cell_name].ok == true then
				table.insert(html, "<b>" .. cell_name .. ": " .. conf[cell_name].desc .. "</b>")
				table.insert(html, results[cell_name].shtml or "")
			elseif show_cell_logs == "fail" and results[cell_name].ok == false then
				table.insert(html, "<b>" .. cell_name .. ": " .. conf[cell_name].desc .. "</b>")
				table.insert(html, results[cell_name].shtml or "")
			elseif show_cell_logs == "all" then
				table.insert(html, "<b>" .. cell_name .. ": " .. conf[cell_name].desc .. "</b>")
				table.insert(html, results[cell_name].shtml or "")
			end
		end
	end

	res.shtml = table.concat(html, "<br/>")
	res.html = ""
	res.log = table.concat(pass_table,"\n")
	res.slog = ""

	return res
end --end function l_bingo
-----------------------------------------------------
function l_sameCRC(arg,filter,opt)
    local res={}
	res.ok = false
    local count=0
	local level = opt.level
	local limit = opt.limit
	local showAll = false
	if opt.showAll ~= nil then
		showAll = opt.showAll
	end
	if limit == nil then
		limit = 1
	end

	calculateMostFound()
	
	local areas = findsInCountry
	if level == "region" then
		areas = findsInRegion
	elseif level == "county" then
		areas = findsInCounty
	end

	for area,_ in spairs(areas) do
		local t=TableCopy(arg)
		if opt ~= nil and opt.func ~= nil and t.func == nil then
			t.func = opt.func
		end
		if opt ~= nil and opt.conf ~= nil then
			for n,v in pairs(opt.conf) do
				if t.conf[n] == nil then
					t.conf[n] = v
				end
			end
		end
		if t.opt == nil then
			t.opt = {}
			t.opt.conf = {}
		end
		t.opt.conf.country = matchingCountries[area]
		if level == "region" then
			t.opt.conf.region = matchingRegions[area]
		elseif level == "county" then
			t.opt.conf.region = matchingRegions[area]
			t.opt.conf.county = matchingCounties[area]
		end
		
		if t.func~= nil then
			if filter~= nil then
				apply_conf_filter_to_subconfs(t, filter)
			end

			local tmp=lookup(t.func,t.conf,filter,t.opt)
			if tmp.ok == true then
				count=count+1
				if count ==1 then
					res.log=tmp.log
					res.html=area.."<br>"..tmp.html
					res.slog=tmp.slog
					res.shtml="<tr><td>"..ok_html(tmp.ok).."</td><td>"..area.."</td><td>"..tmp.shtml.."</td></tr>"
				else
					res.log=res.log..tmp.log
					res.html=res.html.."<br>"..area.."<br>"..tmp.html
					res.slog=res.slog..tmp.slog
					res.shtml=res.shtml.."<tr><td>"..ok_html(tmp.ok).."</td><td>"..area.."</td><td>"..tmp.shtml.."</td></tr>"
				end
			end
		end
	end
	if count == 0 and showAll ~= true then
		  res.log="No matching "..plural(level).." found"
		  res.html=res.log
			res.slog=res.log
			res.shtml="<tr><td>"..ok_html(false).."</td><td></td><td>"..res.log.."</td></tr>"
	elseif count == 0 then
		  res.log="No matching "..plural(level).." found"..res.log
		  res.html="No matching "..plural(level).." found<br>"..res.html
			res.slog="No matching "..plural(level).." found"
			res.shtml="<tr><td>"..ok_html(false).."</td><td></td><td>No matching "..plural(level).." found</td></tr>"
	end
	if count >= limit then
		res.ok = true
		res.shtml = "<tr><td></td><td></td><td>"..count.." "..plural(level).." found out of a needed "..limit.."</td></tr>"..res.shtml
	end
    res.shtml='<table class=\"'..g_table_class..'\"><thead><tr><th>'..ok_html(res.ok)..'</th><th>'..level..'</th><th>Results</th></tr></thead><tbody>'
              ..res.shtml.."</tbody></table>"
    res.slog=ok_text(res.ok)..": same "..level.."{\n"..count.." "..plural(level).." found out of a needed "..limit.."\n"..res.slog.."}\n"
	return res
end --end function l_sameCRC
-----------------------------------------------------
function l_same(arg,filter,opt)

	local fieldVals = (opt and opt.fieldVals) or (arg and arg.fieldVals) or {}									-- opt.fieldVals, you can specify the values you want to iterate over.
	local fieldValDependencies = (opt and opt.fieldValDependencies) or (arg and arg.fieldValDependencies) or {}	-- opt.fieldValDependencies. The fields that are required in addition to the opt.field.
	local min_finds_per_value = opt.min_finds_per_value or 1													-- must have at least this number of finds in a field value to consider this as an option.
	local exclude_result_caches = opt.exclude_result_caches or false											-- If true, any caches returned from res.caches will be excluded from further searches.
	local log_result_caches = opt.log_result_caches ~= nil and opt.log_result_caches or false					-- If true, will print any intermediate results from the operations returned in result.caches as a single table into the log.
	local html_result_caches = opt.html_result_caches ~= nil and opt.html_result_caches or false				-- If true, will print any intermediate results from the operations returned in result.caches as a single table into the html.
	local print_fields = opt.print_fields or {'gccode', 'visitdate', 'cache_name'}								-- Fields to print if either the two above are true. Better ensure these are returned from the sub-operations.
	local limit = opt.limit																						-- Number of subtests that need to pass in order to pass.
	local join_incoming_filter = opt.join_incoming_filter or false												-- If true, combines the 'filter' parameter with filters from conf (well arg in this case).
	local pass_filter_down = get_default(opt.pass_filter_down, true)											-- If true, passes the values from the input filter to this, down to the sub-confs.
	local logic_short_circuit = opt.logic_short_circuit or false												-- If you don't have enough fieldVals to make the limit, then don't bother doing the check.
	local print_only_statuses_log = opt.print_only_status_log or opt.print_only_status							-- If this is present, only print the results of the sub-functions that match in the log (does not affect HTML)
	local print_only_statuses_html = opt.print_only_status_html	or opt.print_only_status						-- If this is present, only print the results of the sub-functions that match in the HTML (does not affect log)
	local exclude_caches = exclude_result_caches and opt.excludeCaches or {}

	local res={}
	res.ok = false
    local count=0
	local passCount = 0
	if filter == nil or join_incoming_filter then
		filter = table_join(FilterFromConfig(arg), filter or {})
	end

	if opt.field == nil and opt.fieldVals == nil then
		error("You did not specify 'opt.field' OR 'opt.fieldVals'.")
	end

	if print_only_statuses_log ~= nil and type(print_only_statuses_log) ~= 'table' then
		print_only_statuses_log = {print_only_statuses_log}
	end
	if print_only_statuses_html ~= nil and type(print_only_statuses_html) ~= 'table' then
		print_only_statuses_html = {print_only_statuses_html}
	end

	-- If fieldVals was already supplied, then don't need to even get the finds
	-- Special case: using "attribute", all attributes are iterated over, not just the ones that you've found.
	if #fieldVals == 0 and opt.field ~= "attributes" then
		local reqFields = {opt.field}
		-- If you specify county as the field, then you also need region.
		if opt.field == "county" then
			table.insert(reqFields, "region")
		end
		-- If you specify region or county as the field, then you also need country.
		if opt.field == "county" or  opt.field == "region" then
			table.insert(reqFields, "country")
		end
	
		local finds = GetCombinedFinds(profileId, { lookup_cache=conf.lookup_cache, transforms=arg.transforms,fields = reqFields, order = 'OLDESTFIRST', filter = filter, gethides=conf.gethides })
		local field_value_counts = {}
		for _,f in pairs(finds) do
			function add_field()
				field_value_counts[f[opt.field]] = (field_value_counts[f[opt.field]] or 0) + 1
				if field_value_counts[f[opt.field]] >= min_finds_per_value then
					insert_into_list_if_unique(f[opt.field], fieldVals)

					-- If they chose county or region, add the region and country as dependencies
					if opt.field == "county" and f[opt.field] ~= nil then
						fieldValDependencies[f[opt.field]] = {region = f.region, country = f.country}
					elseif opt.field == "region" and f[opt.field] ~= nil then
						fieldValDependencies[f[opt.field]] = {country = f.country}
					end
				end
			end
			local function print_error_handler(err)
				DebugPrint("Exception: " .. err .. "\n")
			end
			if not xpcall(function() return add_field() end, print_error_handler) then
				DebugPrint("Error with cache: ".. dump(f.gccode) .. "\n")
			end
		end

		-- if we generated the field values, then sort them.
		table.sort(fieldVals)
	end

	-- Special case: generate the attributes
	if #fieldVals == 0 and opt.field == 'attributes' then
		fieldVals = get_attribute_numbers()
	end

	DebugPrint("Values for 'same': " .. dump(fieldVals).."\n")

	if limit == nil then
		limit = 1
	end
	if limit == "all" then
		limit = 0
		for k,_ in pairs(fieldVals) do 
			limit = limit+1
		end
	end

	res.log = ""
	res.html = ""
	res.slog = ""
	res.shtml = ""
	local results = {}
	local any_points = false

	-- If shortcircuiting, just return now if you didn't have enough to pass the limit.
	if logic_short_circuit and limit > #fieldVals then
		res.ok = false
		res.slog = "You did not have enough unique values of "..opt.field.." to pass."
		res.shtml = "You did not have enough unique values of "..opt.field.." to pass."
		return res
	end

	local field_to_filter_array = 
	{
		["type"] = function(field_value) return {types={field_value}} end,
		["terrain"] = function(field_value) return {terrains={field_value}} end,
		["difficulty"] = function(field_value) return {difficulties={field_value}} end,
		["size"] = function(field_value) return {sizes={field_value}} end,
		["country_region"] = function(field_value) 
			-- NOTE: This only works because no countries have commas in them.
			-- NOTE: Some countries have no regions, and the country_region is just the region
			local country = nil
			local region = nil
			if string.match(field_value, ", ") then
				for v in string.gmatch(field_value,"[^,]+") do
					if region==nil then 
						region = string.gsub(v,"^%s*","")
					else
						country = string.gsub(v,"^%s*","")
					end
				end
			else
				country = field_value
			end

			if region ~= nil then
				return {country={country}, region=region} 
			else
				return {country={country}}
			end
		end,
		["visitdate"] = function(field_value)
			return {minVisitDate=field_value, maxVisitDate=field_value}
		end,
		["visit_mmdd"] = function(field_value)
			_, _, m, d = string.find(field_value, "(%d+)-(%d+)")
			return {visitday=d, visitmonth=m}
		end,
		["hidden"] = function(field_value)
			_, _, y, m, d = string.find(field_value, "(%d+)-(%d+)-(%d+)")
			return {hiddenday=d, hiddenmonth=m, hiddenyear=y}
		end,
		["hidden_mmdd"] = function(field_value)
			_, _, m, d = string.find(field_value, "(%d+)-(%d+)")
			return {hiddenday=d, hiddenmonth=m}
		end,
		["publish_mmdd"] = function(field_value)
			_, _, m, d = string.find(field_value, "(%d+)-(%d+)")
			return {publishday=d, publishmonth=m}
		end,
		["last_publish_date"] = function(field_value)
			_, _, y, m, d = string.find(field_value, "(%d+)-(%d+)-(%d+)")
			return {publishday=d, publishmonth=m, publishyear=y}
		end,
		["visit_year"] = function(field_value)
			return {minVisitDate=field_value.."-01-01", maxVisitDate=field_value.."-12-31" }
		end,
		["hidden_year"] = function(field_value)
			return {minHiddenDate=field_value.."-01-01", maxHiddenDate=field_value.."-12-31" }
		end,
		["publish_year"] = function(field_value)
			return {minHiddenDate=field_value.."-01-01", maxHiddenDate=field_value.."-12-31" }
		end,
		["visit_month"] = function(field_value)
			return {visitmonth=field_value}
		end,
		["hidden_month"] = function(field_value)
			return {hiddenmonth=field_value}
		end,
		["publish_month"] = function(field_value)
			return {publishmonth=field_value}
		end,
		["gccode"] = function(field_value)
			return {gccodes={field_value}}
		end
	}

	for _,fieldVal in ipairs(fieldVals) do
		local t=TableCopy(arg)
		if opt ~= nil and opt.func ~= nil and t.func == nil then
			t.func = opt.func
		end
		if opt ~= nil and opt.conf ~= nil then
			for n,v in pairs(opt.conf) do
				if t.conf[n] == nil then
					t.conf[n] = v
				end
			end
		end

		-- Passing it the opt.conf, for logical operations, which then filter their subops.
		t.opt = t.opt or {}
		t.opt.conf = t.opt.conf or {}
		t.opt.conf[opt.field] = fieldVal

		-- If there were dependent fields, then pass those in too.
		for depField,depFieldVal in spairs(fieldValDependencies[fieldVal] or {}) do
			t.opt.conf[depField] = depFieldVal
		end

		
		-- THIS passes in the fieldVal into the 'child' conf, so it can be used with FilterFromConfig:
		if opt.field ~= 'attributes' then
			if field_to_filter_array[opt.field] ~= nil then
				local filter_table = field_to_filter_array[opt.field](fieldVal)
				DebugPrint(opt.field .. " has produced an array: " .. dump(filter_table)..". #t.conf="..#t.conf.."\n")
				for k,v in pairs(filter_table) do
					if #t.conf == 0 then
						t.conf[k] = v
					else
						t.opt.conf[k]=v
					end
				end

				if #t.conf == 0 then
					t.conf[opt.field] = nil
				else
					t.opt.conf[opt.field] = nil
				end
			elseif opt.custom_filter ~= nil then
				if #t.conf == 0 then
					t.conf[opt.custom_filter.field] = opt.custom_filter.template
					t.conf[opt.custom_filter.field][opt.custom_filter.template_value_field] = fieldVal
				else
					t.opt.conf[opt.custom_filter.field] = opt.custom_filter.template
					t.opt.conf[opt.custom_filter.field][opt.custom_filter.template_value_field] = fieldVal
				end
			else
				t.conf = t.conf or {}
				if #t.conf == 0 then
					t.conf[opt.field] = fieldVal
				else
					t.opt.conf[opt.field]=fieldVal
				end
			end

			-- If there were dependent fields, then pass those in too.
			for depField,depFieldVal in spairs(fieldValDependencies[fieldVal] or {}) do
				if #t.conf == 0 then
					t.conf[depField] = depFieldVal
				else
					t.opt.conf[depField] = depFieldVal
				end					
			end
		else
			if t.conf.attributeFilter ~= nil then 
				error("Can't iterate attributes and also supply an attribute filter.")
			end
			t.conf.attributeFilter = {func="set",opt={attribute=fieldVal}}
		end

		if t.func == nil and g_conf.default_func == nil then
			error("t.func is nil, and default_func is nil. Don't know what to do here. While processing " .. dump(t).."\n")
		end

		count=count+1
		
		if filter~= nil and pass_filter_down then
			apply_conf_filter_to_subconfs(t, filter)
		else
			filter = nil
		end

		-- If caches from subsequent operations should not be returned in future results, add them to the exclude list.
		if exclude_result_caches then
			-- Possible that t.conf is an array of conf - in that case, pass filter down to opt, which array funcs pick up on.
			if #t.conf == 0 then
				t.conf['excludeCaches']=exclude_caches
			else
				t.opt['excludeCaches']=exclude_caches
			end
		end

		-- Do the operation
		local tmp=lookup(t.func,t.conf,filter,t.opt)
		if tmp.ok ~= "info" and tmp.ok ~= false then
			passCount = passCount + 1
		end

		if exclude_result_caches and tmp.ok == true then
			exclude_caches = array_join(exclude_caches, array_field_as_array(tmp.caches or {},'gccode'))
		end

		tmp.fieldVal = fieldVal
		table.insert(results, tmp)
		any_points = any_points or tmp.points ~= nil

		-- If you've definitely passed or failed, then shortcircuit, if desired.
		if logic_short_circuit and logic_func_short_circuit('same', passCount, count, opt) then
			was_short_circuit = true
			break
		end
	end

	DebugPrint("There are " .. #results .. " in l_same.")

	-- Sort the results by the number of points. 
	local process_results = #results
	if opt.top_points ~= nil then
		if opt.invert_top_points then
			table.sort(results, function(f1, f2) return (f1.points or f1.ok and 1 or 0) < (f2.points or f2.ok and 1 or 0) end)
		else
			table.sort(results, function(f1, f2) return (f1.points or f1.ok and 1 or 0) > (f2.points or f2.ok and 1 or 0) end)
		end
		process_results = math.min(opt.top_points, #results)
	end

	for i=1,process_results do
		local tmp = results[i]
		if print_only_statuses_log == nil or find_in_list(tmp.ok, print_only_statuses_log) > 0 then
			if tmp.log ~= "" then
				res.log=res.log.."\n"..opt.field .. " = ".. tmp.fieldVal..":\n"..tmp.log
			end
			if tmp.slog ~= "" then
				res.slog=res.slog.."\n"..opt.field .. " = ".. tmp.fieldVal..":\n"..tmp.slog
			end
		end
		if print_only_statuses_html == nil or find_in_list(tmp.ok, print_only_statuses_html) > 0 then
			if tmp.html ~= "" then
				res.html=res.html.."<br>"..tmp.html
			end
			local pnts = any_points and tostring(tmp.points or 0) or nil
			res.shtml=res.shtml.."<tr><td>" .. tmp.fieldVal .. "</td><td>"..ok_html(tmp.ok).."</td>"..(pnts~=nil and ("<td>"..pnts.."</td>") or "").."<td>"..tmp.shtml.."</td></tr>"
		end
		
		if tmp.points~= nil then
			res.points=(res.points or 0)+tmp.points
		end

		res.caches = array_join(res.caches or {}, tmp.caches or {})
	end

	if res.ok and res.points ~= nil then
		res.points = math.min(opt.maxPoints or math.huge, math.max(res.points - (opt.skipPoints or 0), 0))
	end

	if passCount >= limit then
		res.ok = true
		res.shtml = "<tr><td></td><td></td>".. (res.points~=nil and "<td/>" or "").."<td>"..passCount.." "..opt.field.." found out of a needed "..limit.."</td></tr>"..res.shtml
	else
		res.shtml = "<tr><td></td><td></td>".. (res.points~=nil and "<td/>" or "").."<td>"..passCount.." "..opt.field.." found out of a needed "..limit.."</td></tr>"..res.shtml
	end

	local points_header = res.points ~= nil and "<th>Points</th>" or ""

    res.shtml='<table class=\"'..g_table_class..'\"><thead><tr><th>'..opt.field..'</th><th>Results</th>'..points_header..'</tr></thead><tbody>'
              ..res.shtml.."</tbody></table>"
    res.slog=ok_text(res.ok)..": same "..opt.field.."{\n"..passCount.." "..opt.field.." found out of a needed "..limit.."\n"..res.slog.."}\n"

	if log_result_caches then
		if #res.caches == 0 then
			DebugPrint("You wanted log_result_caches, but there are no results.\n")
		end
		res.log = res.log .. PrintFindsText(res.caches, #res.caches, print_fields)
	end
	if html_result_caches then
		if #res.caches == 0 then
			DebugPrint("You wanted html_result_caches, but there are no results.\n")
		end
		res.html = res.html .. PrintFindsHtml(res.caches, #res.caches, print_fields)
	end

	return res
end --end function l_same
-----------------------------------------------------
function l_visit_date(conf, filter, opt)

	local filter = filter or FilterFromConfig(conf)				 	 -- Generate the filter from the config (if it's not explicitly passed)
	local limit = opt.limit or 1								 	 -- The number of visit dates that 'pass', for you to pass (in total, over all years).
	local additional_fields = opt.required_fields or {}	    	 	 -- All additional fields needed for suboperations. Caches will not be re-fetched, so this must be complete.
	local condensed = opt.condensed								 	 -- 'condensed' ie. output into a single calendar, with a count of how many years pass the single date.
	local condensed_leap_day = opt.condensed_leap_day			 	 -- If condensed is true, then this specifies whether you want to include leap day (Feb 29th).
	local condensed_limit = opt.condensed_limit	or 1				 -- The number of you need to pass (per calendar day) to pass a date (ie. number of years with a passing cell).
	local condensed_limit_per_day = opt.condensed_limit_per_day or 1 -- The number of you need to pass (per calendar day) to pass a date (ie. number of years with a passing cell).
	local condensed_summary = opt.condensed_summary or true			 -- Whether to print out a summary of condensed mode after the main calendar
	local no_calendar = opt.no_calendar or false					 -- If true, no calendar will be printed, the output of each visitdate check that passes will print out.
	local start_date = opt.start_date or "2000-05-03"			 	 -- Visit date start.
	local end_date = opt.end_date or "today"					 	 -- Visit date end.

	if condensed == nil then condensed = true end

	function print_year(year, result_hash, condensed)

		local table_html_out = {}
		local current_date = iso:parse(year.."-01-01")
		local start_date = iso:parse(start_date)
		local end_date = iso:parse(end_date)
	
		current_date:year(tonumber(year))
		current_date:month(1)
		current_date:day(1)

		table.insert(table_html_out,'<div>')
		if not condensed then
			table.insert(table_html_out,'<div class="header">')
			table.insert(table_html_out,'<span>' .. year .. '</span>')
			table.insert(table_html_out,'</div>')
		end
		table.insert(table_html_out,'<table class=\"'..g_table_class..'\">')
		table.insert(table_html_out,'<tbody><tr>')
		table.insert(table_html_out,'<th colspan="32">Date</th>')
		table.insert(table_html_out,'<th></th>')
		table.insert(table_html_out,'</tr>')
		table.insert(table_html_out,'<tr>')
		table.insert(table_html_out,'<td></td>')
		for i=1,31 do
			table.insert(table_html_out,'<td class="align-center" width="32"><b>'..tostring(i)..'</b></td>')
		end
		table.insert(table_html_out,'<td class="nobgcolor"></td>')
		table.insert(table_html_out,'</tr>')
		for month=1,12 do
			pass_total = 0
			current_date:day(1)
			current_date:month(month)
			local last_day_of_month = current_date:last_day().tab.day
			table.insert(table_html_out,'<tr>')
			table.insert(table_html_out,'<td><b>' .. current_date:month_name() .. '</b></td>')
			for day=1,31 do
				current_date:day(day)
				local date_valid = day <= last_day_of_month and (condensed or (current_date >= start_date and current_date <= end_date))
				local current_date_str = iso:tostring(current_date)
				local count = result_hash[current_date_str] and #result_hash[current_date_str] or 0
				if date_valid then
					local cell_pass = condensed and count >= condensed_limit_per_day or (not condensed and count >= 1)
					local bgcol = cell_pass and 'style="background:#00FF00"' or 'style="background:#FF0000"'
					table.insert(table_html_out,'<td class="align-center" ' .. bgcol..'>' .. count ..'</td>')
					pass_total = pass_total+ (cell_pass and 1 or 0)
				else
					table.insert(table_html_out,'<td class="align-center" style="background:#FFFF00">X</td>')
				end
			end
			table.insert(table_html_out,'<td class="align-right">'.. pass_total ..'</td>')
			table.insert(table_html_out,'</tr>')
		end
		table.insert(table_html_out,'</tbody></table>')
		table.insert(table_html_out,'<br>')
		table.insert(table_html_out,'</div>')
	
		return table.concat(table_html_out, " ")
	end

	if end_date == 'today' then
		end_date = iso:tostring(Date())
	end

	-- Go through all the finds. It's likely that *most* visit dates will be empty, and we don't need to run the lookups for them.
	local required_fields = array_join( {'gccode', 'visitdate'}, additional_fields)
	local finds = GetCombinedFinds(profileId, { lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = required_fields , order = 'OLDESTFIRST', filter = filter })
	local visit_dates_found = {}
	for _,f in ipairs(finds) do
		visit_dates_found[f.visitdate] = visit_dates_found[f.visitdate] or {}
		table.insert(visit_dates_found[f.visitdate],f)
	end	

	-- If they have no finds, g'bye. Otherwise, fast forward the start date to the beginning of their first find.
	if #finds == 0 then
		start_date  = end_date
	elseif start_date < finds[1].visitdate then
		start_date  = finds[1].visitdate
	end

	-- REPLACE GetCombinedFinds, so that, we can just immediately return the caches for this date.
	local tempGetCombinedFinds = GetCombinedFinds
	function GetCombinedFindsVisitDate(profileId, conf)
		local result=  visit_dates_found[conf.filter.minVisitDate] or {}
		return result
	end
	GetCombinedFinds = GetCombinedFindsVisitDate


	local result_by_visit_date_hash = {}
	local current_date = iso:parse(start_date)
	local current_date_string = iso:tostring(current_date)
	while (current_date_string <= end_date) do

		-- Don't bother running the check if they haven't found a cache with this visit date, presumably the check will fail.
		if visit_dates_found[current_date_string] ~= nil then
			local t=TableCopy(conf)

			if t.func == nil and g_conf.default_func == nil then
				error("t.func is nil, and default_func is nil. Don't know what to do here.")
			end
	
			if filter~= nil then
				apply_conf_filter_to_subconfs(t, filter)
			end

			-- Set the magical visit date field, so we only get things we've already filtered.
			t.conf.maxVisitDate = current_date_string
			t.conf.minVisitDate = current_date_string

			-- Do the operation
			result_by_visit_date_hash[current_date_string]=lookup(t.func,t.conf,filter,t.opt)
		end

		-- Go to the next date.
		current_date = current_date:add({day=1})
		current_date_string = iso:tostring(current_date)
	end

	-- Now put GetCombinedFinds back.
	GetCombinedFinds = tempGetCombinedFinds

	local ok = false
	local log = {}
	local html = {}
	local result_list = {}
	local actual_limit = math.huge

	if (not condensed) then
		actual_limit = limit
		for date, res in spairs(result_by_visit_date_hash) do
			if res.ok then
				res.date = date
				table.insert(result_list, res)
			end
		end
			
		if not no_calendar then
			-- print all the years
			local start_year = tonumber(string.sub(start_date, 1, 4))
			local end_year = tonumber(string.sub(end_date, 1, 4))

			for year = start_year,end_year do
				table.insert(html, print_year(year, result_by_visit_date_hash, false, 1))
			end
		else
			for _, res in ipairs(result_list) do				
				table.insert(log, res.date .. ":\n" .. res.slog .. "\n")
				table.insert(html, "<b>"..res.date.."</b>" .. "<br/>"..res.shtml .. "<br/>")
			end
		end	
	else
		actual_limit = condensed_limit

		-- sum the number of years that pass.
		local fake_year = condensed_leap_day and '2000' or '2001'	-- if you want a leap year, pretend it's 2000, otherwise, pretend it's 2001.
		local condensed_results = {}
		local condensed_summary = {}

		for date,res in pairs(result_by_visit_date_hash) do
			if res.ok then
				res.date = date
				local real_year = string.sub(date,1,4)
				local fake_date = fake_year .. string.sub(date, 5, 10)
				condensed_results[fake_date] = condensed_results[fake_date] or {}
				table.insert(condensed_results[fake_date], res)
				condensed_summary[real_year] = (condensed_summary[real_year] or 0)+1
			end
		end

		for _, res_list in spairs(condensed_results) do
			if #res_list >= condensed_limit_per_day then
				table.insert(result_list, res_list)
			end
		end

		if not no_calendar then
			table.insert(html, print_year(fake_year, condensed_results, true, condensed_limit_per_day))
		else
			for _, res in ipairs(result_list) do
				table.insert(log, res.date .. ":\n" .. res.slog .. "\n")
				table.insert(html, "<b>"..res.date.."</b>" .. "<br/>"..res.shtml .. "<br/>")
			end
		end

		if condensed_summary then
			local grand_total = 0
			for year, count in spairs(condensed_summary) do
				grand_total = grand_total + count
				table.insert(html, year .. ": " .. count)
			end
			table.insert(html, "Total: " .. grand_total)
		end
	end

	ok = #result_list >= actual_limit
	table.insert(log, "You have " .. #result_list .. " dates passed, out of a required " .. actual_limit)
	table.insert(html, "You have " .. #result_list .. " dates passed, out of a required " .. actual_limit)
	
	local shtml=table.concat(html,"<br/>"):gsub("%*%*(.-)%*%*","<b>%1</b>"):gsub("%[(GC.-)%]%((http.-)%)","<a href='%2'>%1</a>")
	local slog=table.concat(log,"\n")

	local res={}
	res.ok = ok
	res.log = ""
    res.html = ""
    res.slog = ok_text(res.ok) .. ": " .. slog
    res.shtml = ok_text(res.ok) .. ": " ..  shtml

	res.points = calculate_points(opt, res.ok, #result_list)

	return res
	
end
-----------------------------------------------------
function l_generate(conf, filter, opt)

	if PGC[conf.method] == nil then
		error('PGC did not contain a method: ' .. conf.method)
	end

	if (conf.conf == nil) then
		error('After you generate something, you need to DO something with that.')
	end

	if (conf.transfer == nil) then
		error("If you don't 'transfer' anything to the sub conf, then this is pointless.")
	end

	-- Special - replace $profileId with the actual profile Id.
	function replace_profileId(f)
		if type(conf.param) == 'table' then
			for _,v in pairs(conf.param) do
				replace_profileId(v)
			end
		end
		if type(f) == 'string' then
			if conf.param == "$profileId" then 
				conf.param = profileId
			end
		end
	end
	replace_profileId(conf.param)

	-- Now actually DO it.
	local result = PGC[conf.method](conf.param)

	-- If desired, run transforms on the output.
	local generate_table = {["generated"] = result}
	apply_transforms(conf.transforms, {generate_table})
	
	-- Transfer any filters from this conf to the child conf.
	if conf ~= nil and conf.conf ~= nil then
		for n,v in pairs(conf) do
			if conf.conf[n] == nil then
				conf.conf[n] = v
			end
		end
	end

	-- Now transfer any fields in the fake_finds to the sub-configuration, and run that.
	for _, f in ipairs(conf.transfer) do
		conf.conf[f] = generate_table[f]
	end

	-- Now run the sub function.
	return lookup(conf.func, conf.conf, filter, conf.opt)
	
end
-----------------------------------------------------
function get_oldest(opt, new_filter)
	return PGC.GetOldestCaches({alternativeDBCluster=true, limit=opt.fetch, filter=new_filter})
end
function oldest_update_expanded_filter_function(expanded_filter, last_cache)
	-- If we don't have enough, filter only oldest the the newest one we have.
	local current_date = iso:parse(last_cache.hidden)		
	expanded_filter['minHiddenDate']=iso:tostring(current_date:add({day=1}))
	DebugPrint("Not enough results. Running with minHiddenDate=" .. expanded_filter['minHiddenDate'] .."\n")
	return true
end

function c_oldest(conf)
	local res = process_top_list(get_oldest, oldest_update_expanded_filter_function, {"hidden"}, conf, {})
	local includes_archived_statement = res.archived_finds > 0 and " This includes " .. res.archived_finds .. " find(s), which are now archived." or ""

	res.slog = "You found " .. res.found_count .. " out of a required " .. res.num .. " of the oldest caches " .. res.limit .. " cache(s)." .. includes_archived_statement .. "\n\n" .. res.slog
    res.shtml = "You found " .. res.found_count .. " out of a required " .. res.num .. " of the oldest caches " .. res.limit .. " cache(s)." .. includes_archived_statement .. "<br/><br/>" .. res.shtml

    return res
end
-----------------------------------------------------
function c_oldest_fizzy(conf)
	local res = process_top_fizzy(get_oldest, oldest_update_expanded_filter_function, {"hidden"}, conf, {})
	local includes_archived_statement = res.archived_finds > 0 and " This includes " .. res.archived_finds .. " find(s), which are now archived." or ""
	local include_per_dt_statement = res.limit > 0 and " (".. res.limit .. " per DT)." or ""

	res.slog = "You satisfied " .. res.dt_passed_count .. " DTs out of a required " .. res.num .. " of the oldest caches" .. include_per_dt_statement .. includes_archived_statement .. "\n\n" .. res.slog
    res.shtml = "You satisfied " .. res.dt_passed_count .. " DTs out of a required " .. res.num .. " of the oldest caches " .. include_per_dt_statement .. includes_archived_statement .. "<br/><br/>" .. res.shtml

    return res
end
-----------------------------------------------------
function get_top_favs(opt, expanded_filter)
	DebugPrint("Fetching top favs with favorite_type=" .. opt.favorite_type .. " fetch=" .. opt.fetch .. " and expanded_filter="..dump(expanded_filter).."\n")
	return PGC.GetFavorites(opt.favorite_type,{limit=opt.fetch, alternativeDBCluster=true, dontCountArchivedTowardsLimit=true, dontCountDisabledTowardsLimit=true, filter=expanded_filter})
end
function topfav_update_expanded_filter_function(expanded_filter, last_cache)
	-- We can't filter by maximum FPs, to get the lower one, the only thing we can do is fetch more.
	if expanded_filter.fetch < 1000 then
		expanded_filter.fetch = math.min(expanded_filter.fetch * 2,1000)
		DebugPrint("Could not satisfy request. Increasing fetch to " .. expanded_filter.fetch .. "\n")
		return true
	end
	
	-- Can't fetch any more, so, set only looking for active caches. This may cause an archived find to be excluded, but gonna be pretty rare.
	if not expanded_filter.excludeArchived then
		expanded_filter.excludeArchived = true
		DebugPrint("Could not satisfy request. Removing archived caches from query.\n")
		return true
	end

	return false
end

function c_topfav(conf)

	local favorite_type = conf.favorite_type	or 'points'			-- points, pct or wilson
	local favorite_field = nil
	if (favorite_type == 'wilson') then
		favorite_field = 'favorite_points_wilson'
	elseif (favorite_type == 'pct') then
		favorite_field = 'favorite_points_pct'
	else
		favorite_field = 'favorite_points'
	end

	local res = process_top_list(get_top_favs, topfav_update_expanded_filter_function, {favorite_field}, conf, {favorite_type=favorite_type})
	local includes_archived_statement = res.archived_finds > 0 and " This includes " .. res.archived_finds .. " find(s), which are now archived." or ""

	res.slog = "You found " .. res.found_count .. " out of a required " .. res.num .. " of the favorite caches " .. res.limit .. " cache(s)." .. includes_archived_statement .. "\n\n" .. res.slog
    res.shtml = "You found " .. res.found_count .. " out of a required " .. res.num .. " of the favorite caches " .. res.limit .. " cache(s)." .. includes_archived_statement .. "<br/><br/>" .. res.shtml

	return res
end
-----------------------------------------------------
function c_topfav_fizzy(conf)

	local favorite_type = conf.favorite_type	or 'points'			-- points, pct or wilson
	local favorite_field = nil
	if (favorite_type == 'wilson') then
		favorite_field = 'favorite_points_wilson'
	elseif (favorite_type == 'pct') then
		favorite_field = 'favorite_points_pct'
	else
		favorite_field = 'favorite_points'
	end

	local res = process_top_fizzy(get_top_favs, topfav_update_expanded_filter_function, {favorite_field}, conf, {favorite_type=favorite_type})
	local includes_archived_statement = res.archived_finds > 0 and " This includes " .. res.archived_finds .. " find(s), which are now archived." or ""
	local include_per_dt_statement = res.limit > 0 and " (".. res.limit .. " per DT)." or ""

	res.slog = "You satisfied " .. res.dt_passed_count .. " DTs out of a required " .. res.num .. " of the most favorite caches" .. include_per_dt_statement .. includes_archived_statement .. "\n\n" .. res.slog
    res.shtml = "You satisfied " .. res.dt_passed_count .. " DTs out of a required " .. res.num .. " of the most favorite caches" .. include_per_dt_statement .. includes_archived_statement .. "<br/><br/>" .. res.shtml

	return res
end
-----------------------------------------------------
function get_top_elevs(opt, new_filter)
	if opt.top_type == 'highest' then
		topelevation = PGC.GetHighestCaches({limit=opt.fetch, alternativeDBCluster=true, dontCountDisabledTowardsLimit=true, dontCountDisabledTowardsLimit=true, filter=new_filter})
		DebugPrint('GetHighestCaches returned ' .. #topelevation .. " caches "..opt.fetch.." requested\n" )
	elseif opt.top_type == 'lowest' then
		topelevation = PGC.GetLowestCaches({limit=opt.fetch, alternativeDBCluster=true, dontCountDisabledTowardsLimit=true, dontCountDisabledTowardsLimit=true, filter=new_filter})
		DebugPrint('GetLowestCaches returned ' .. #topelevation .. " caches " ..opt.fetch.." requested\n" )
	else
		error("conf.type must be one of 'highest' or 'lowest' (but was " .. opt.top_type .. ")")
	end

	-- Turn the 'elevation' field into a number, because it's for some reason a string.
	for _, t in ipairs(topelevation) do
		t.elevation = tonumber(t.elevation)
	end

	return topelevation
end

function top_elevation_update_expanded_filter_function(expanded_filter, last_cache)
	-- Apparently we can't filter by elevation in GetHighest/LowestCaches. Likely, we're here because we requested caches and they were archived... so just ask for more.
	if expanded_filter.fetch < 1000 then
		expanded_filter.fetch = math.min(expanded_filter.fetch * 2,1000)
		DebugPrint("Could not satisfy request. Increasing fetch to " .. expanded_filter.fetch .. "\n")
		return true
	end
	
	-- Can't fetch any more, so, set only looking for active caches. This may cause an archived find to be excluded, but gonna be pretty rare.
	if not expanded_filter.excludeArchived then
		expanded_filter.excludeArchived = true
		DebugPrint("Could not satisfy request. Removing archived caches from query.\n")
		return true
	end

	return false
end

function c_top_elevation(conf)
	local top_type = conf.type or 'highest'			            -- 'highest' or 'lowest'. defaults to highest
	local res = process_top_list(get_top_elevs, top_elevation_update_expanded_filter_function, {"elevation"}, conf, {top_type=top_type})
	local includes_archived_statement = res.archived_finds > 0 and " This includes " .. res.archived_finds .. " find(s), which are now archived." or ""

	res.slog = "You found " .. res.found_count .. " out of a required " .. res.num .. " of the " .. top_type .. " elevation caches " .. res.limit .. " cache(s)." .. includes_archived_statement .. "\n\n" .. res.slog
    res.shtml = "You found " .. res.found_count .. " out of a required " .. res.num .. " of the " .. top_type .. " elevation caches " .. res.limit .. " cache(s)." .. includes_archived_statement .. "<br/><br/>" .. res.shtml

	return res
end

function c_top_elevation_fizzy(conf)
	local top_type = conf.type or 'highest'			            -- 'highest' or 'lowest'. defaults to highest
	local res = process_top_fizzy(get_top_elevs, top_elevation_update_expanded_filter_function, {"elevation"}, conf, {top_type=top_type})
	local includes_archived_statement = res.archived_finds > 0 and " This includes " .. res.archived_finds .. " find(s), which are now archived." or ""
	local include_per_dt_statement = res.limit > 0 and " (".. res.limit .. " per DT)." or ""

	res.slog = "You satisfied " .. res.dt_passed_count .. " DTs out of a required " .. res.num .. " of the " .. top_type .. " caches" .. include_per_dt_statement .. includes_archived_statement .. "\n\n" .. res.slog
    res.shtml = "You satisfied " .. res.dt_passed_count .. " DTs out of a required " .. res.num .. " of the " .. top_type .. " caches " .. include_per_dt_statement .. includes_archived_statement .. "<br/><br/>" .. res.shtml

	return res
end

----------------------------------------
function process_top_list(get_top_function, next_expanded_filter_function, test_fields, conf, top_params)

	-- Sometimes this parameter is used instead, same meaning.
	if (conf.owned_as_found ~= nil) then
		if (conf.owner_as_found ~= nil) then
			error("Using owned_as_found and owner_as_found, which have the same meaning. Use one instead.")
		end
		conf.owner_as_found = conf.owned_as_found
	end

	local limit = conf.num_considered or conf.limit or 1                       			-- num of top caches considered.
	local num = conf.num_required or conf.num or 1										-- The number of caches required to pass
	local fetch = conf.fetch or limit													-- number of oldest to fetch from the database. You can override this, if for example you filter post-database query, and will need more results.
    local owner_as_found = get_default(conf.owner_as_found, {[1]=true,[2]=false})       -- count owned caches as found.
	local print_only_found = get_default(conf.print_only_found, false)					-- Whether the only print the caches that count as a find (or all). Defaults to all.
	local print_fields = conf.print_fields												-- Fields that should be printed when printing out the results
    local filter = conf.filter or FilterFromConfig(conf) or {}   						-- filter for the caches.
	local number_archived = get_default(conf.number_archived, {[1]=true,[5]=false})		-- Whether to number archived caches as part of the limit. Otherwise, they will just show 'dashes'.
	
	filter.excludeArchived = get_default(conf.exclude_archived, {[1]=1,[2]=0})			-- Whether to exclude archived caches (default to false in new challenges, *generally* only valid for grandfathered challenges)
	filter.excludeDisabled = conf.exclude_disabled or 0      							-- Whether disabled caches are considered as top

	local expanded_filter = expandFilter(filter)
	local fetch_fields = test_fields

	if (print_fields == nil) then
		print_fields = array_join({'n','gccode', 'visitdate', 'cache_name'},test_fields)
	end
	for _, f in ipairs(print_fields) do
		insert_into_list_if_unique(f, fetch_fields)
	end

	local base_fields = {'gccode', 'cache_name', 'visitdate', 'owner_id', 'type', 'archived'}
	for _, f in ipairs(base_fields) do
		insert_into_list_if_unique(f, fetch_fields)
	end

	if conf.skip ~= nil then
		error("'skip' is deprecated. Don't use it.")
	end

	if num > limit then
		error("You cannot possibly find " .. num .. " caches, when the limit is only " .. limit)
	end
	if fetch < limit then
		error("You're only fetching ".. fetch.." but the limit is " .. limit .. ", which doesn't make sense.")
	end

	local unarchived_count = 0
	local top_finds = {}
	local top_gccodes = {}
	while unarchived_count < limit do
		top_params.fetch = fetch
		local top_unfiltered = get_top_function(top_params, expanded_filter)
		if #top_unfiltered == 0 then
			DebugPrint("Could not satisfy getting " .. limit .. " caches after fully expanding the search. It may be that the caches do not exist.\n")
			break
		end

		DebugPrint("get_top_function returned " .. #top_unfiltered .. "\n")
		for _, top in ipairs(top_unfiltered) do
			if top_gccodes[top.gccode] == nil and not find_fails_filter(expanded_filter, top) and (tonumber(top.owner_id) ~= tonumber(profileId) or owner_as_found) then
				if (tonumber(top.archived)==0) then
					unarchived_count = unarchived_count +1 
				end
				table.insert(top_finds, top)
				top_gccodes[top.gccode] = true

				if unarchived_count >= limit then
					DebugPrint("Now have " .. unarchived_count .. " so quitting.")
					break
				end
			end
		end

		-- If we don't have enough, filter only oldest the the newest one we have.
		if unarchived_count < limit then
			-- Allow the expand to modify fetch, which is not really part of the filter, but might give more results
			expanded_filter.fetch = fetch
			if not next_expanded_filter_function(expanded_filter, top_unfiltered[#top_unfiltered]) then
				DebugPrint("Could not satisfy getting " .. limit .. " caches after fully expanding the search. It may be that the caches do not exist.\n")
				break
			end
			fetch = expanded_filter.fetch
			expanded_filter.fetch = nil
		end
	end

	DebugPrint("The top array has " .. #top_finds .. " of which " .. unarchived_count .. " are not archived.\n")

    local finds = GetCombinedFinds(profileId, { lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = fetch_fields, order = 'OLDESTFIRST', filter = filter })
    local finds_by_gccode = {}
    for _, find in ipairs(finds) do
        finds_by_gccode[find.gccode] = find
    end

    local top_log = {}
    local top_html = {}
    local found_count = 0
	local archived_finds = 0

	if unarchived_count < limit then
		table.insert(top_html, "<b>Warning</b> - there were not enough unarchived caches found to satisfy the top query.<br/>")
	end

	if #keys(expanded_filter) > 0 then
		table.insert(top_html, PrintFilter(expanded_filter))
	end

	local top_found = {}
	local cache_n = 0
	for _,cache in ipairs(top_finds) do
		local archived = (tonumber(cache.archived)~=0)
    	local owner = (tonumber(cache.owner_id) == tonumber(profileId)) and owner_as_found
        cache.found = (finds_by_gccode[cache.gccode] ~= nil or owner)
		if (cache.found) then
			found_count = found_count + 1 
			if archived then
				archived_finds = archived_finds + 1
			end
			
			if (owner) then
				DebugPrint(cache.gccode .. " - owned\n")
				cache.visitdate = "Owner"
			else
				cache.visitdate = finds_by_gccode[cache.gccode].visitdate
				cache.log_id = finds_by_gccode[cache.gccode].log_id
			end
		end

		-- Give it a number if it's not archived, or if it is archived and we are numbering archived finds.
		if not archived or cache.found then
			if number_archived then
				cache_n = cache_n + 1
				cache.n = cache_n
			elseif not archived then
				cache_n = cache_n + 1
				cache.n = cache_n
			else
				cache.n = "-"
			end
			table.insert(top_found, cache)
		end
	end

	function get_row_style_log(cache)
		return cache.found or nil
	end
	function get_row_style_html(cache)
		local archived = (tonumber(cache.archived)~=0)
		local should_print = cache.found or (not archived and not print_only_found)
		if should_print then
			return archived and "color : red" or ""
		end		
		return nil
	end
	
    table.insert(top_log, PrintFindsText(top_finds, #top_finds, print_fields, get_row_style_log))
    table.insert(top_html, PrintFindsHtml(top_finds, #top_finds, print_fields, false, get_row_style_html))

    local res = {}
    res.ok = found_count >= num
    res.log = ""
    res.html = ""
    res.slog = table.concat(top_log, "\n") .. "\n"
    res.shtml = table.concat(top_html, "<br/>")
	res.caches = top_found
	res.points = calculate_points(conf, res.ok, found_count)

	-- These might be needed to add a custom message for the test (and don't hurt anything)
	res.found_count = found_count
	res.num  = num 
	res.limit = limit
	res.archived_finds = archived_finds
	res.filter = filter

    return res
end
-----------------------------------------------------
function process_top_fizzy(get_top_function, next_expanded_filter_function, test_fields, conf, top_params)

	local limit = get_default(conf.limit, 1)  			                -- num of top caches considered (per DT)
	local num = get_default(conf.num, 1)								-- The number of DTs satisfied required to pass
	local fetch = get_default(conf.fetch, limit*81)						-- number of oldest to fetch from the database. You can override this, if for example you filter post-database query, and will need more results.
    local owner_as_found = get_default(conf.owner_as_found, false)		-- Count owned caches as found.
	local print_only_found = get_default(conf.print_only_found, false)	-- Whether the only print the caches that count as a find (or all). Defaults to all.
	local print_fields = conf.print_fields								-- Fields that should be printed when printing out the results
    local filter = conf.filter or FilterFromConfig(conf) or {}   		-- Filter for the caches.
	
	filter.excludeArchived = get_default(conf.exclude_archived, false)	-- Whether to exclude archived caches (default to false in new challenges, *generally* only valid for grandfathered challenges)
	filter.excludeDisabled = get_default(conf.exclude_disabled, false)	-- Whether disabled caches are considered as top

	local expanded_filter = expandFilter(filter)
	local fetch_fields = test_fields

	if (print_fields == nil) then
		print_fields = array_join({'dt', 'gccode', 'difficulty', 'terrain', 'visitdate', 'cache_name'},test_fields)
	end
	for _, f in ipairs(print_fields) do
		insert_into_list_if_unique(f, fetch_fields)
	end

	local base_fields = {'gccode', 'difficulty', 'terrain','cache_name', 'visitdate', 'owner_id', 'type', 'archived'}
	for _, f in ipairs(base_fields) do
		insert_into_list_if_unique(f, fetch_fields)
	end

	-- print out the filter before doing the query, because the query might modify it, and that looks confusing.
    local top_html = {}
	if #keys(expanded_filter) > 0 then
		table.insert(top_html, PrintFilter(expanded_filter))
	end

	local dts_remaining = 81
	local top_finds_dt = {}
	local top_gccodes_dt = {}
	local difficulties = {"1.0", "1.5", "2.0", "2.5", "3.0", "3.5", "4.0", "4.5", "5.0"}
	local terrains = {"1.0", "1.5", "2.0", "2.5", "3.0", "3.5", "4.0", "4.5", "5.0"}
	local d_counts = {0, 0, 0, 0, 0, 0, 0, 0, 0}
	local t_counts = {0, 0, 0, 0, 0, 0, 0, 0, 0}
	while dts_remaining > 0 do
		top_params.fetch = fetch
		DebugPrint("Calling get_top_function with top_params=" .. dump(top_params) .. "\n")
		local top_unfiltered = get_top_function(top_params, expanded_filter)

		error_if(#top_unfiltered == 0, "Could not satisfy getting " .. limit .. " caches after fully expanding the search. It may be that the caches do not exist.\n")

		DebugPrint("get_top_function returned " .. #top_unfiltered .. "\n")
		for _, top in ipairs(top_unfiltered) do
			local top_key = top.difficulty .. "/" .. top.terrain
			top_gccodes_dt[top_key] = top_gccodes_dt[top_key] or {} 
			if top_gccodes_dt[top_key][top.gccode] == nil and not find_fails_filter(expanded_filter, top) and (tonumber(top.owner_id) ~= tonumber(profileId) or owner_as_found) then
				top_finds_dt[top_key] = top_finds_dt[top_key] or {not_archived=0}
				if top_finds_dt[top_key].not_archived < limit then
					DebugPrint("Adding " .. PrintFindsText({top}, 1, {"gccode","cache_name"}) .. " to " .. top_key .. "\n")
					table.insert(top_finds_dt[top_key], top)
					top_gccodes_dt[top_key][top.gccode] = true

					-- need to count the unarchived finds, so we can know if we have enough active caches for this DT.
					local archived = (tonumber(top.archived)~=0)
					top_finds_dt[top_key].not_archived = top_finds_dt[top_key].not_archived + (archived and 0 or 1)
					if top_finds_dt[top_key].not_archived == limit then
						DebugPrint("Now have " .. top_finds_dt[top_key].not_archived .. " for " .. top_key .. ", so marking as complete.\n")
						dts_remaining = dts_remaining - 1

						-- If we've completely satisfied a difficulty or terrain row/col, remove it from the list of available difficulties and terrains, so we don't waste time fetching more of those.
						local d_idx = tonumber(top.difficulty)*2-1
						local t_idx = tonumber(top.terrain)*2-1
						d_counts[d_idx] = (d_counts[d_idx] or 0) + 1						
						t_counts[t_idx] = (t_counts[t_idx] or 0) + 1
						if d_counts[d_idx] == 9 then
							remove_from_list(top.difficulty, difficulties)
							expanded_filter.difficulties = difficulties
						end
						if t_counts[t_idx] == 9 then
							remove_from_list(top.terrain, terrains)
							expanded_filter.terrains = terrains
						end
					end
				end
			end
		end

		-- If we don't have enough, filter only oldest from the newest one we have.
		if dts_remaining > 0 then
			-- Allow the expand to modify fetch, which is not really part of the filter, but might give more results
			expanded_filter.fetch = fetch
			if not next_expanded_filter_function(expanded_filter, top_unfiltered[#top_unfiltered]) then
				error("Could not satisfy getting " .. limit .. " caches after fully expanding the search. It may be that the caches do not exist.\n")
			end
			fetch = expanded_filter.fetch
			expanded_filter.fetch = nil
		end
	end

    local finds = GetCombinedFinds(profileId, { lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = fetch_fields, order = 'OLDESTFIRST', filter = filter })
    local finds_by_gccode = {}
    for _, find in ipairs(finds) do
        finds_by_gccode[find.gccode] = find
    end

    local top_log = {}
	local archived_finds = 0

	if dts_remaining > 0 then
		table.insert(top_html, "<b>Warning</b> - there were not enough unarchived caches found to satisfy the top query.<br/>")
	end

	local dt_passed_count = 0
	local DT = {}
	local top_finds = {}
	local top_found = {}
	for d = 1, 9 do
		DT[d] = {}
		for t = 1, 9 do
			local top_found_dt = {}
			local top_key = string.format("%0.1f/%0.1f", (d+1)/2, (t+1)/2)
			for _,cache in ipairs(top_finds_dt[top_key] or {}) do
				table.insert(top_finds, cache)
				cache.dt = top_key
				local archived = (tonumber(cache.archived)~=0)
				local owner = (tonumber(cache.owner_id) == tonumber(profileId)) and owner_as_found
				cache.found = (finds_by_gccode[cache.gccode] ~= nil or owner)

				if not archived or cache.found then
					table.insert(top_found, cache)
				end

				if (cache.found) then
					table.insert(top_found_dt, cache)
					if archived then
						archived_finds = archived_finds + 1
					end
					
					if (owner) then
						DebugPrint(cache.gccode .. " - owned\n")
						cache.visitdate = "Owner"
					else
						cache.visitdate = finds_by_gccode[cache.gccode].visitdate
						cache.log_id = finds_by_gccode[cache.gccode].log_id
					end
				end
					
			end
			if #top_found_dt >= limit then
				dt_passed_count = dt_passed_count + 1
			end
			DT[d][t] = #top_found_dt
		end
	end

	function get_row_style_log(cache)
		return cache.found or nil
	end
	function get_row_style_html(cache)
		local archived = (tonumber(cache.archived)~=0)
		local should_print = cache.found or (not archived and not print_only_found)
		if should_print then
			return archived and "color : red" or ""
		end		
		return nil
	end

    table.insert(top_log, PrintFindsText(top_finds, #top_finds, print_fields, get_row_style_log))
	table.insert(top_html, PrintDT(DT,nil,nil,nil,nil,nil, {conditions={entries=num}}))
	table.insert(top_html, "Considered caches per DT shown below. Archived finds will show in <span style='color: red;'>red</span>.<br/>")
    table.insert(top_html, PrintFindsHtml(top_finds, #top_finds, print_fields, false, get_row_style_html))

    local res = {}
    res.ok = dt_passed_count >= num
    res.log = ""
    res.html = ""
    res.slog = table.concat(top_log, "\n") .. "\n"
    res.shtml = table.concat(top_html, "<br/>")
	res.caches = top_found
	res.points = calculate_points(conf, res.ok, found_count)

	-- These might be needed to add a custom message for the test (and don't hurt anything)
	res.found_count = found_count
	res.dt_passed_count = dt_passed_count
	res.num  = num 
	res.limit = limit
	res.archived_finds = archived_finds
	res.filter = filter

    return res
end
-----------------------------------------------------
function c_continents(opt)
	local continents_required = opt.num or 1				-- number of continents you need.
	local types_required = opt.types_required or 1		    -- number of types you need in each continent.
	local countries_required = opt.countries_required or 1	-- number of countries you need in each continent.
	local filter = opt.filter or {}							-- filter for finds.

    local finds = GetCombinedFinds(profileId, { lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = {'gccode', 'cache_name', 'visitdate', 'owner_id', 'country', 'type'}, order = 'OLDESTFIRST', filter = filter })

	-- Create a country -> continent map, so we can quickly identify which continent each country is in.
	local country_to_continent_map = {}
	for continent, country_list in pairs(GetContinentCountries()) do
		for _, country in ipairs(country_list) do
			if type(country_to_continent_map[country]) =='string' then
				local current_continent = country_to_continent_map[country]
				country_to_continent_map[country] = {}
				table.insert(country_to_continent_map[country], current_continent)
				table.insert(country_to_continent_map[country], continent)
			elseif type(country_to_continent_map[country]) == 'table' then
				table.insert(country_to_continent_map[country], continent)
			else
				country_to_continent_map[country] = continent
			end
		end
	end

	local continent_results = {continents=0}
	for _, find in ipairs(finds) do
		local continent_entry = country_to_continent_map[find.country]
		local continents_to_process = {}
		if (type(continent_entry) == 'table') then
			continents_to_process = continent_entry
		else
			continents_to_process = {continent_entry}
		end

		for _, continent in ipairs(continents_to_process) do
			if  continent ~= nil then
				if (continent_results[continent] == nil) then
					continent_results[continent] = {}
					continent_results[continent].countries = {}
					continent_results[continent].types = {}
					continent_results.continents = continent_results.continents +1
				end
				insert_into_list_if_unique(find.country, continent_results[continent].countries)
				insert_into_list_if_unique(find.type, continent_results[continent].types)
			else
				DebugPrint("**Country**: " .. find.country .. " not categorized into a continent. Will be ignored.\n")
			end
		end

	end

	local res = {}
	local log = {}
	local llog = {}
	local passing_continents = 0

	table.insert(log, "")
	for continent, result in pairs(continent_results) do
		if (type(result) == 'table') then
			local continent_passes = (#result.countries >= countries_required and #result.types >= types_required)
			passing_continents = passing_continents + (continent_passes and 1 or 0)
			if (continent_passes) then
				local continent_line = continent .. ": "
				if countries_required > 1 then
					continent_line = continent_line .. "found " .. #result.countries .. " countries "
					table.insert(llog, "**"..continent.."**")
					for _, country in ipairs(result.countries) do
						table.insert(llog, country)
					end
					table.insert(llog, "")
				end
				if types_required > 1 then
					continent_line = continent_line .. "found " .. #result.types .. " types "
					table.insert(llog, "**"..continent.."**")
					for _, ctype in ipairs(result.types) do
						table.insert(llog, ctype)
					end
					table.insert(llog, "")
				end
				continent_line = continent_line .. (continent_passes and "(pass)" or "(fail)").."\n"
				table.insert(log, 1, continent_line)
			end
		end
	end

	local head_log_line = "("
	if (countries_required > 1) then
		head_log_line = head_log_line .. countries_required .. " countries, "
	end
	if (types_required >1) then
		head_log_line = head_log_line .. types_required.. " types, "
	end
	head_log_line = head_log_line .. continents_required .. " continents)"
	table.insert(log, 1, head_log_line)


	res.ok = passing_continents >= continents_required
	if (not	res.ok) then
		table.insert(log, "You have not found enough passing continents.")
	end

	res.log = table.concat(llog, "\n") .. table.concat(log, "\n") .. "\n"
	res.html= ""
    res.slog = ok_text(res.ok) .. ": " .. table.concat(log, "\n") .. "\n"
    res.shtml = ok_text(res.ok) .. ": " ..  table.concat(log, "<br/>")
	res.points = calculate_points(opt, res.ok, passing_continents)

	return res
end

