function c_maxdist(opt)

	local conf=opt
	-- Adapted from:
	-- https://www.geeksforgeeks.org/maximum-distance-between-two-points-in-coordinate-plane-using-rotating-calipers-method/
	-- Function to detect the orientation

	function orientation(p, q, r)
		local x = area(p, q, r);

		-- If area > 0 then points are clockwise
		if (x > 0) then
			return 1;
		end

		-- If area<0 then points are counterclockwise
		if (x < 0) then
			return -1;
		end

		-- If area is 0 then p, q and r are co-linear
		return 0;
	end

	-- Function to find the area
	function area(p, q, r)
		-- 2*(area of triangle)
		return ((p.latitude - q.latitude) * (q.longitude - r.longitude) - (q.latitude - r.latitude) * (p.longitude - q.longitude));
	end

	-- Function to find the absolute Area
	function absArea(p, q, r)
		-- Unsigned area 2*(area of triangle)
		return math.abs(area(p, q, r));
	end

	-- Function to find the distance
	function dist(p1, p2)
		-- squared-distance b/w p1 and p2 for precision
		return ((p1.longitude - p2.longitude) * (p1.longitude - p2.longitude)
				+ (p1.latitude - p2.latitude) * (p1.latitude - p2.latitude));
	end

	function compareAngle(o1, o2)
		local a1 = angle(minPoint, o1)
		local a2 = angle(minPoint, o2)
		return a1 > a2
	end


	function angle(mp, p1)
		local v1 = {x = p1.latitude-mp.latitude, y = p1.longitude-mp.longitude}
		return math.atan(v1.y / v1.x)
	end

	function dumpFind(f)
		DebugPrint(f.gccode .. " :" .. f.latitude .. " " .. f.longitude .. "\n")
	end

	-- Function to implement Convex Hull Approach
	function convexHull(points)

		local n = #points;

		local min = {latitude=360, longitude=360}; -- higher than max possible values

		DebugPrint("convexHull start ("..#points..") points.\n")

		-- Choose point having min y-coordinate and if two points have same y-coordinate choose
		-- the one with minimum x-coordinate
		local ind = -1;
		for i = 1,n do
			if (min.latitude > points[i].latitude) then
				min.latitude = points[i].latitude;
				min.longitude = points[i].longitude;
				ind = i;
			elseif (min.latitude == points[i].latitude and min.longitude > points[i].longitude) then
				min.longitude = points[i].longitude;
				ind = i;
			end
		end

		-- NOTE: minPoint is global, as it's used in the compareOrientation function
		minPoint = points[ind]
		points[ind] = points[1];
		points[1] = minPoint;

		if (conf.debug) then
			DebugPrint("Find with lowest latitude/longitude:\n")
			dumpFind(minPoint)
		end

		-- Sort points which have minimum polar angle wrt Point 'minPoint'
		-- temporarily remove the first point, because it should always be first.
		table.remove(points, 1)
		table.sort(points, compareAngle)
		table.insert(points, 1, minPoint)

		local st = {}

		-- Uncomment this for debugging... but, not by default because it's huge.
		if (conf.debug) then
			-- DebugPrint("Sorted points by angle:\n")
			-- for i = 1,n-1 do
			--     dumpFind(points[i])
			--     DebugPrint("angle = " .. angle(minPoint, points[i]) .. "\n")
			-- end
		end

		-- First hull point
		table.insert(st, points[1])

		-- Second hull point
		local secondPointIndex = n
		for k = 2,n-1 do
			if (orientation(points[1], points[k], points[k + 1]) ~= 0) then
				secondPointIndex = k
				break;
			end
		end
		table.insert(st, points[secondPointIndex]);

		-- Here's the actual scan:
		for i = secondPointIndex + 1, n do

			local top = table.remove(st);

			while (orientation(st[#st], top, points[i]) >= 0) do
				top = table.remove(st);
			end

			table.insert(st, top);
			table.insert(st, points[i]);
		end

		return st;
	end

	-- To help with index wrapping lua, because it's annoyingly 1-indexed
	function idxwrap(i, n)
		if (i > n) then
			return i % n + 1
		end
		return i
	end

	-- Function to find the maximum distance between any two finds from a set. Returns the two finds.
	function rotatingCaliper(points)

		-- Takes O(n)
		local maxdist = 0
		local hull = convexHull(points);
		local n = #hull

		-- Convex hull output, is useful for debugging, and not that huge (well, usually).
		if (conf.debug) then
			DebugPrint("\nComputed convex hull:\n")
			for _,cvp in ipairs(hull) do
				DebugPrint(cvp.gccode .. ", ")
			end
			DebugPrint("\n")
		end

		-- Base Cases
		if (n == 1) then
			return {};
		end
		if (n == 2) then
			return {hull[1], hull[2]}
		end


		-- Find the farthest vertex from hull[1] and hull[n]
		local k = 1;
		while (absArea(hull[n], hull[1], hull[idxwrap(k+1, n)]) > absArea(hull[n], hull[1], hull[k])) do
			k = k + 1;
		end

		local res = {}

		-- Check points from 0 to k
		local j = k
		local i = 1
		while i <= k and j <= n do

			local newdist = math.sqrt(dist(hull[i], hull[j]))
			if (maxdist < newdist) then
				maxdist = newdist;
				res = {hull[i], hull[j]}
			end

			while (j < n and absArea(hull[i], hull[idxwrap(i + 1, n)], hull[idxwrap(j + 1, n)]) >
				absArea(hull[i], hull[idxwrap(i + 1, n)], hull[j])) do

				-- Update res
				newdist = dist(hull[i], hull[idxwrap(j + 1, n)])
				if (maxdist < newdist) then
					res = {hull[i], hull[idxwrap(j + 1, n)]}
					maxdist = newdist;
				end
				j = j+1;
			end

			i = i + 1
		end

		-- Return the result distance
		return res;
	end

	-- convert lat/long members to numbers, because they come out as strings
	function latlong_tofloat(finds)
		for _, f in ipairs(finds) do
			f.latitude = tonumber(f.latitude)
			f.longitude = tonumber(f.longitude)
		end
	end

	-- Here's where the actual execution begins
	local min_distance = opt.min_distance					-- the minimum distance required to pass.
	local filter = opt.filter or FilterFromConfig(opt)		-- filter for finds.

    local finds = GetCombinedFinds(profileId, { lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = {'gccode', 'visitdate', 'latitude', 'longitude', 'cache_name'}, order = 'OLDESTFIRST', filter = filter })

	-- need lat/lng as numbers.
	latlong_tofloat(finds)

	-- find the two furthest points
    local furthestPoints = rotatingCaliper(finds)

	local log = {}
	local llog = {}
	local res = {}
    if #furthestPoints == 2 then
        local c1 = furthestPoints[1]
        local c2 = furthestPoints[2]
        local furthestDistance = PGC.DistanceHaversine(c1.latitude, c1.longitude, c2.latitude, c2.longitude)
        local passed = (furthestDistance >= min_distance)
        table.insert(log, "\tTwo furthest caches are " .. string.format("%.2f", furthestDistance/1000) .. "km from each other (needed ".. min_distance/1000 .. "km):")
        table.insert(llog, c1.visitdate .. ': <a href=\"http://coord.info/' .. c1.gccode .. '">' .. c1.cache_name .. " (" .. c1.gccode ..")</a>")
        table.insert(llog,  c2.visitdate .. ': <a href=\"http://coord.info/' .. c2.gccode .. '">' .. c2.cache_name .. " (" .. c2.gccode ..")</a>")
        if (not passed) then
            table.insert(llog, "\t\t**Caches are not far enough apart.**")
        end
        res.ok = passed
    else
        -- If there's nothing in the set, then you have one or less finds, so can't pass
        table.insert(log, "\tYou have less than two finds that passed the filter.")
        table.insert(log, "\tYou need more finds to qualify.")
        res.ok = false
    end

	res.log = ""
	res.html= table.concat(log, "<br/>") ..  "<br/>" .. table.concat(llog, "<br/>")
    res.slog = ok_text(res.ok) .. ": " .. table.concat(log, "\n") .. "\n"
    res.shtml = ok_text(res.ok) .. ": " ..  table.concat(log, "<br/>")
	return res

end
-----------------------------------------------------
function c_grid(conf)

	local filter = FilterFromConfig(conf)
	local x_axis = conf.x_axis or error("Must supply 'x_axis'")
	local y_axis = conf.y_axis or error("Must supply 'y_axis'")
	local x_axis_values = conf.x_axis_values
	local y_axis_values = conf.y_axis_values
	local x_axis_autofill = conf.x_axis_autofill or false		  -- Whether "gaps" in a sequence of x-axis values should be filled in. Eg. For visit_year, values 2002, 2004 autofilled would add 2003.
	local y_axis_autofill = conf.y_axis_autofill or false		  -- Whether "gaps" in a sequence of y-axis values should be filled in.
	local limit_per_cell = conf.limit_per_cell or 1               -- number of entries in a cell, required for a passing cell.
	local cell_limit = conf.cell_limit or 1                       -- number of passed cells you need to qualify
	local clamped_total_limit = conf.clamped_total_limit or 1     -- total number (limited by conf.per_cell) you need to qualify
	local total_limit = conf.total_limit or clamped_total_limit   -- total number (unlimited) you need to qualify
	local limit_per_row = conf.limit_per_row or 0			      -- number of cells per row you need for the row to count.
	local limit_per_column = conf.limit_per_column or 0			  -- number of cells per column you need for the column to count.
	local row_limit = conf.row_limit or 0						  -- number of passing rows you need to qualify
	local row_sum_limit = conf.row_sum_limit or 0				  -- the sum of the values in a row, for the row to count as a passed row
	local always_show_row_sum = get_default(conf.always_show_row_sum, false)	-- whether to always show the row sum
	local col_sum_limit = conf.col_sum_limit or 0				  -- the sum of the values in a column, for the column to count as a passed column
	local always_show_col_sum = get_default(conf.always_show_col_sum, false)	-- whether to always show the column sum
	local column_limit = conf.column_limit or 0					  -- number of passing columns you need to qualify
	local rect_size_limit = conf.rect_size_limit				  -- the minimum dimensions of a rectangle you need to pass.
	local unique_row_limit = conf.unique_row_limit or 0					  -- number of must-have unique passes per row. EG. you must have an entry in at least this many columns 
	local unique_cell_total = conf.unique_cell_total or 0				  -- used in conjunction with unique_cell_total, the sum of all the unique cells picked must be greater than or equal to this to pass
	local x_axis_header_format = conf.x_axis_header_format or 'default'  -- the output format of the x-axis headers. one of 'default' or 'icon_only' (only works if x-axis is type)
	local y_axis_header_format = conf.y_axis_header_format or 'default'  -- the output format of the y-axis headers. one of 'default' or 'icon_only' (only works if y-axis is type)
	local cell_format = conf.cell_format or 'gccode_link_with_n'  -- the output format of the cell. one of 'gccode_with_n', 'gccode_link_with_n', 'gccode_link', 'n', 'n_link'
	local cell_print_count = conf.cell_print_count or 1			  -- The number of caches printed, if cell_format is a table of fields to print for the cache.
	local log_verbosity = conf.log_verbosity or 'normal'          -- the verbosity of the example log - 'normal', 'verbose'. 'verbose' mode includes the finds in every passing grid.
	local cell_fn = conf.cell_fn or {func="n"}					  -- the function used to calculate the number in each cell. defaults to just the number in the list
	local point_type = conf.point_type or "cells"				  -- If calculating points, then type of points ("cells"= passed cells, "rows" = passed rows, "cols" = passed cols)
	local show_pass_count_row = get_default(conf.show_row_pass_count, false)	-- Whether to show a row at the bottom of the table with the number of passing cells in each column
	local show_pass_count_column = get_default(conf.show_col_pass_count, false)	-- Whether to show a column at the right of the table with the number of passing cells in each row

	local transforms = conf.transforms or {}
	local x_axis_attributes = x_axis == 'attributes'
	local y_axis_attributes = y_axis == 'attributes'
	local unique_cell_sum = 0

	error_if(unique_cell_total > 0 and unique_row_limit <= 0, "if using unique_cell_total, unique_row_limit must also be >= 0.")

	function print_html_table(y_by_x, x_axis_values, y_axis_values, passed_rows, passed_columns)

		local html = {}
		local show_row_total = row_sum_limit ~= 0 or always_show_row_sum
		local show_col_total = col_sum_limit ~= 0 or always_show_col_sum

		table.insert(html, "<table class=\""..g_table_class.."\" style='table-layout: fixed;border:2px solid black;border-collapse: collapse;'><tr><th style='border:2px solid black;'>" .. y_axis .. " / " .. x_axis .."</th>")
		for _, x in ipairs(x_axis_values) do
			if x_axis_attributes then
				table.insert(html, "<th style='border-bottom:2px solid black;background-color: #dddddd'>" .. get_header_for_attribute(tonumber(x), x_axis_header_format ~= 'icon_only') .. "</th>")
			else
				if x_axis_header_format == 'icon_only' then
					table.insert(html, "<th style='border-bottom:2px solid black;background-color: #dddddd'>" .. get_icon_html_if_type(x) .. "</th>")
				else
					table.insert(html,"<th style='border-bottom:2px solid black;background-color: #dddddd'>" .. get_icon_html_if_type(x) .. tostring(x).. "</th>")
				end
			end
		end
		if show_row_total then
			table.insert(html,"<th style='border-bottom:2px solid black;background-color: #dddddd'><strong>Total</strong></th>")
		end
		if show_pass_count_row then
			table.insert(html,"<th style='border-bottom:2px solid black;background-color: #dddddd'><strong>Passes</strong></th>")
		end

		table.insert(html,"</tr>")

		for _, y in ipairs(y_axis_values) do
			table.insert(html, "<tr>")
			if y_axis_attributes then
				table.insert(html, "<td style='border-right:2px solid black;background-color: #dddddd'><strong>" .. get_header_for_attribute(tonumber(y), y_axis_header_format ~= 'icon_only') .. "</strong></td>")
			else
				if y_axis_header_format == 'icon_only' then
					table.insert(html, "<td style='border-right:2px solid black;background-color: #dddddd'><strong>" .. get_icon_html_if_type(y) .. "</strong></td>")
				else
					table.insert(html, "<td style='border-right:2px solid black;background-color: #dddddd'><strong>" .. get_icon_html_if_type(y) .. tostring(y) .. "</strong></td>")
				end
			end

			local row_sum = 0
			local cells_passed_this_row = 0
			for _, x in ipairs(x_axis_values) do
				local row_pass = find_in_list(y, passed_rows) > 0
				local column_pass = find_in_list(x, passed_columns) > 0
				local cell_value = y_by_x[y] and y_by_x[y][x] and y_by_x[y][x].value or 0
				local cell_pass = cell_value >= limit_per_cell
				local cell_line = ""
				local n_text =  cell_value .. (limit_per_cell > 1 and ("/" .. limit_per_cell) or "")
				row_sum = row_sum + cell_value
				if cell_pass then
					cells_passed_this_row = cells_passed_this_row + 1
				end

				if cell_pass then
					if type(cell_format) == 'table' then
						cell_line = PrintFindsHtml(y_by_x[y][x], math.min(cell_print_count, #y_by_x[y][x]), cell_format,true)
					elseif (cell_format == 'gccode_with_n') then
						cell_line = y_by_x[y][x][1].gccode .. " (" .. cell_value.. ")"
					elseif (cell_format == 'gccode_link_with_n') then
						cell_line = "<a href='http://coord.info/"..y_by_x[y][x][1].gccode.."'>".. y_by_x[y][x][1].gccode .. "</a> (" .. n_text .. ")"
					elseif (cell_format == 'gccode_link') then
						cell_line = "<a href='http://coord.info/"..y_by_x[y][x][1].gccode.."'>".. y_by_x[y][x][1].gccode .. "</a>"
					elseif(cell_format == 'n') then
						cell_line = n_text
					elseif (cell_format =='n_link') then
						cell_line = "<a href='http://coord.info/"..y_by_x[y][x][1].gccode.."'>"..n_text.. "</a>"
					else
						error("Tag error - 'cell_format' needs to be one of 'gccode_with_n', 'gccode_link_with_n', 'gccode_link' or 'n'. (but was " .. cell_format .. ")")
					end
				else
					cell_line = n_text
				end

				local bgcol = ""
				if cell_pass and row_pass and column_pass then
					bgcol = 'style="background:#00FF00"'
				elseif (not row_pass or not column_pass) then
					-- Only color red/yellow if a row/col doesn't pass - and highlight the one(s) that are making it fail in red.
					if cell_pass then
						bgcol = 'style="background:#FFFF00"'
					else
						bgcol = 'style="background:#FF0000"'
					end
				end

				-- If we're doing unique cells, 
				if y_by_x[y] and y_by_x[y][x] then
					local doing_unique_cell = y_by_x[y][x].unique ~= nil
					if doing_unique_cell and not y_by_x[y][x].unique then
						bgcol = cell_pass and 'style="background:#00AF00"' or ''
					end
				end

				table.insert(html, "<td " .. bgcol ..">" .. cell_line  .. "</td>")
			end

			if show_row_total then
				table.insert(html,"<td style='border-top:2px solid black;background-color: #dddddd'>".. row_sum .."</td>")
			end
			if show_pass_count_row then
				table.insert(html,"<td style='border-top:2px solid black;background-color: #dddddd'>".. cells_passed_this_row .."</td>")
			end
			table.insert(html, "</tr>")
		end

		if show_col_total or show_pass_count_column then
			if show_col_total then
				table.insert(html,"<tr><td style='border-top:2px solid black;background-color: #dddddd'><strong>Totals</strong></td>")
			end
			if show_pass_count_column then
				table.insert(html,"<tr><td style='border-top:2px solid black;background-color: #dddddd'><strong>Passes</strong></td>")
			end
			for _, x in ipairs(x_axis_values) do
				local col_sum = 0
				local col_pass_count = 0
				for _, y in ipairs(y_axis_values) do
					if y_by_x[y] ~= nil and y_by_x[y][x] ~= nil then
						col_sum = col_sum + y_by_x[y][x].value
						if y_by_x[y][x].value >= limit_per_cell then
							col_pass_count = col_pass_count + 1
						end
					end
				end
				if show_col_total then
					table.insert(html, "<td style='border-top:2px solid black;background-color: #dddddd'>"..col_sum.."</td>")
				end
				if show_pass_count_column then
					table.insert(html, "<td style='border-top:2px solid black;background-color: #dddddd'>"..col_pass_count.."</td>")
				end
			end
			table.insert(html,"</tr>")
		end
		table.insert(html, "</table>")

		return table.concat(html, "<br/>")
	end


	function get_icon_html_if_type(v)		
		local icontag = type(v) == "string" and PGC.Icon.GeocacheType(v) or nil
		return icontag or ""
	end

	function get_header_for_attribute(attribute_index, include_name)
		local attributes = PGC.GetAttributeList()
		local attr_tag = "<div style='margin-bottom:2px' height='30'>"
		local negative = attribute_index > 96
		if (negative) then
			attribute_index = attribute_index-96
		end
		attr_tag = attr_tag .. attributes[attribute_index][negative and 'imageUnset' or 'imageSet']
		if (include_name) then
			attr_tag = attr_tag .. "<p>" .. (negative and "Not " or "") .. attributes[attribute_index].attributeName .. "</p>"
		end
		attr_tag = attr_tag .. "</div>"
		return attr_tag
	end

	function string_minus_encoding(str, str_prefix, max_value)
		if str == str_prefix then
			return max_value
		end
		local prefix_len = string.len(str_prefix)
		if string.sub(str,1, prefix_len) ~= str_prefix then
			error(str .. " does not begin with ".. str_prefix)
		end
		local num_substr = string.sub(str,prefix_len+1,-1)
		DebugPrint(num_substr.."\n")
		local addend = tonumber(num_substr)
		return max_value + addend
	end

	local fields_required = {'gccode'}

	if log_verbosity == 'verbose' then
		table.insert(fields_required, "cache_name")
		table.insert(fields_required, "visitdate")
	end

	function get_min_year_from_filter(filter)
		local start_year = 2000 			-- default to 2000 if not set in filter.
		if filter.minVisitDate ~= nil then
			start_year = math.max(start_year, tostring(string.sub(filter.minVisitDate, 1, 4)))
		end
		if filter.minHiddenDate ~= nil then
			start_year = math.max(start_year, tostring(string.sub(filter.minHiddenDate, 1, 4)))
		end
		return start_year
	end

	local x_axis_fields = {x_axis}
	if x_axis_attributes then
		x_axis_fields = {'attributes_set','attributes_unset'}
		if x_axis_values == "attributes_111" then
			x_axis_values = get_attribute_numbers()			
			remove_from_list({42, 45, 61}, x_axis_values) -- Remove NM, LF and partnership
		elseif x_axis_values == "attributes_positive" then
			x_axis_values = get_positive_attribute_numbers()
		elseif x_axis_values == "attributes_negative" then
			x_axis_values = get_negative_attribute_numbers()
		end
	end
	if type(x_axis_values)=='string' and x_axis_values == 'years' then
		local max_year = string_minus_encoding(x_axis_values, "years", Date().tab.year)
		local min_year = get_min_year_from_filter(filter)
		x_axis_values = {}
		for x = min_year,max_year do
			table.insert(x_axis_values, tostring(x))
		end
	end

	local y_axis_fields = {y_axis}
	if x_axis_attributes then
		y_axis_fields = {'attributes_set','attributes_unset'}
		if y_axis_values == "attributes_111" then
			y_axis_values = get_attribute_numbers()			
			remove_from_list({42, 45, 61}, y_axis_values) -- Remove NM, LF and partnership
		elseif y_axis_values == "attributes_positive" then
			y_axis_values = get_positive_attribute_numbers()
		elseif x_axis_values == "attributes_negative" then
			y_axis_values = get_negative_attribute_numbers()
		end
	end
	if type(y_axis_values)=='string' and string.sub(y_axis_values,1,5) == 'years' then
		local max_year = string_minus_encoding(y_axis_values, "years", Date().tab.year)
		local min_year = get_min_year_from_filter(filter)
		y_axis_values = {}
		for y = min_year,max_year do
			table.insert(y_axis_values, tostring(y))
		end
	end

	-- If either if these is a transformed field, it'll just be ignored.
	for _,f in ipairs(x_axis_fields) do
		insert_into_list_if_unique(f, fields_required)
	end
	for _,f in ipairs(y_axis_fields) do
		insert_into_list_if_unique(f, fields_required)
	end

	-- If cell_format is a table, it's a list of fields we want to print from the caches
	if type(cell_format)=='table' then
		for _,f in ipairs(cell_format) do
			insert_into_list_if_unique(f, fields_required)
		end
	end

	-- If there's a cell_fn, we might need something from that as well
	collect_opt_fields(cell_fn, fields_required)

	DebugPrint("Fields: " .. dump(fields_required) .. "\n")
	DebugPrint("Filter: " .. dump(filter) .. "\n")

	local finds = GetCombinedFinds(profileId, { lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields=fields_required, order = 'OLDESTFIRST', filter = filter, includeLabCaches=conf.include_labs })

	-- Now, go thourgh every find, and put it in the appropriate X and Y entry.
	local y_by_x = {}
	local y_values = {}
	local x_values = {}
	for _, find in ipairs(finds) do
		local x_vs = x_axis_attributes and get_attribute_list(find) or find[x_axis]
		local y_vs = y_axis_attributes and get_attribute_list(find) or find[y_axis]

		if type(x_vs) ~= 'table' then x_vs = {x_vs} end
		if type(y_vs) ~= 'table' then y_vs = {y_vs} end

		for _, x in ipairs(x_vs) do
			for _, y in ipairs(y_vs) do
				-- If specific values are specified for x and/or y, then only record the value if it's in there.
				if (y_axis_values == nil or find_in_list(y, y_axis_values) > 0) and (x_axis_values == nil or find_in_list(x, x_axis_values) > 0) then
					y_by_x[y] = y_by_x[y] or {}
					y_by_x[y][x] = y_by_x[y][x] or {}

					-- Special case - if you're doing attributes by attributes, don't record any where the one attribute is greater than the other, because that will cause double-counting.
					if not x_axis_attributes or not y_axis_attributes or x > y then
						-- Premark this as NOT unique, if we're doing a unique value lookup.
						if unique_row_limit > 0 then
							y_by_x[y][x].unique = false
						end
						table.insert(y_by_x[y][x], find)
					end
				end
				insert_into_list_if_unique(y, y_values)
				insert_into_list_if_unique(x, x_values)
			end
		end
	end

	table.sort(y_values)
	table.sort(x_values)

	-- If they didn't specify values for the x/y axes, then use all the values we found.
	y_axis_values = y_axis_values or y_values
	x_axis_values = x_axis_values or x_values

	-- Autofill the values (eg. if it's a sequence type, like years, fill in any gaps)
	function autofill(field, values)
		local i = 1
		while i < #values do
			local next = next_value(field, values[i])
			insert_into_list_if_unique(next, values)
			table.sort(values)
			i = i + 1
		end
	end
	if y_axis_autofill then
		autofill(y_axis, y_axis_values)
	end
	if x_axis_autofill then
		autofill(x_axis, x_axis_values)
	end

	-- Calculate the values, in case it's not just a simple list size
	for iy, y in ipairs(y_axis_values) do
		for ix, x in ipairs(x_axis_values) do
			if y_by_x ~= nil and y_by_x[y] ~= nil and y_by_x[y][x] ~= nil then
				y_by_x[y][x].value = cell_function_def[cell_fn.func](y_by_x[y][x], cell_fn.opt)
				y_by_x[y][x].value = math_clamp(y_by_x[y][x].value, (cell_fn.opt and cell_fn.opt.min) or -math.huge, (cell_fn.opt and cell_fn.opt.max) or math.huge)
			end
		end
	end

	DebugPrint("x axis:" .. dump(x_axis_values) .. "\n")
	DebugPrint("y axis:" .. dump(y_axis_values) .. "\n")

	-- Convert any limit values that are "all"
	local total_rows = #y_axis_values
	local total_cols = #x_axis_values
	local total_cells = total_rows * total_cols
	cell_limit = type(cell_limit) ~= 'string' and cell_limit or string_minus_encoding(cell_limit,"all",total_cells)
	limit_per_row = type(limit_per_row) ~= 'string' and limit_per_row or string_minus_encoding(limit_per_row, "all", total_cols)
	limit_per_column = type(limit_per_column) ~= 'string' and limit_per_column or string_minus_encoding(limit_per_column, "all", total_rows)
	row_limit = type(row_limit) ~= 'string' and row_limit or string_minus_encoding(row_limit, "all",total_rows)
	column_limit = type(column_limit) ~= 'string' and column_limit or string_minus_encoding(column_limit, "all", total_cols)

	local clamped_total = 0
	local total = 0
	local passed_cells = 0
	local passed_rows = {}
	local passed_columns = {}
	for _,y in pairs(y_axis_values) do

		local cells_passed_this_row = 0
		local row_total = 0
		for _,x in pairs(x_axis_values) do
			local find_list = y_by_x[y] and y_by_x[y][x] or {value=0}
			local cell_value = find_list.value
			if cell_value >= limit_per_cell then
				passed_cells = passed_cells+1
				cells_passed_this_row = cells_passed_this_row+1
			end
			row_total = row_total + cell_value
			clamped_total = clamped_total + math.min(cell_value, limit_per_cell)
			total = total + cell_value
		end

		if cells_passed_this_row >= limit_per_row then
			if row_sum_limit == 0 or row_total >= row_sum_limit then
				table.insert(passed_rows, y)
			end
		end
	end

	for _,x in pairs(x_axis_values) do
		local cells_passed_this_column = 0
		local col_total = 0
		for _,y in pairs(y_axis_values) do
			if y_by_x[y] ~= nil and y_by_x[y][x] ~= nil then				
				col_total = col_total + y_by_x[y][x].value
				if y_by_x[y][x].value >= limit_per_cell then
					cells_passed_this_column = cells_passed_this_column+1
				end
			end
		end

		if cells_passed_this_column >= limit_per_column then
			if col_sum_limit == 0 or col_total >= col_sum_limit then
				table.insert(passed_columns, x)
			end
		end
	end

	-- Now do unique row check, if applicable.
	local passed_unique = true
	if unique_row_limit > 0 then
		local unique_array = {}
		for ix,x in ipairs(x_axis_values) do
			local next_row_passes = {}
			for iy,y in ipairs(y_axis_values) do
				if y_by_x[y] ~= nil and y_by_x[y][x] ~= nil and y_by_x[y][x].value >= limit_per_cell then
					table.insert(next_row_passes, {y=y, x=x, ix=ix, iy=iy})
				end
			end
			table.insert(unique_array, next_row_passes)
		end
		-- To reduce the search space, iteratively remove items from other arrays, that only have one option.
		reduce_array_choices({"y"}, unique_array, unique_row_limit)

		local unique_rows = choose_unique_fields_per_array(unique_array, 1, {"y"}, {}, {unique_row_limit})
		passed_unique = unique_rows.ok
		if unique_rows.ok then
			for _,value_pairs in ipairs(unique_rows.best_solution) do
				if y_by_x[value_pairs.y] ~= nil and y_by_x[value_pairs.y][value_pairs.x] ~= nil then
					unique_cell_sum = unique_cell_sum + y_by_x[value_pairs.y][value_pairs.x].value
					y_by_x[value_pairs.y][value_pairs.x].unique = true
				end
			end
		end

		if unique_cell_total >= 0 and unique_cell_sum < unique_cell_total then
			DebugPrint("failed, because unique_cell_sum < unique_cell_total")
			passed_unique = false
		end
	end

	local passed_area = true
	local valid_rects = {}
	local passing_rect
	if rect_size_limit then
		function largest_rect_area(heights, min_width, min_height)
			local stack = {}
			local maxArea = 0
			local max_rect = {x=0,y=0,w=0,h=0}
			local n = #heights
			for i = 1, n + 1 do
				-- Use 0 height at the end to process remaining bars in stack
				local currentHeight = i <= n and heights[i] or 0
				while #stack > 0 and currentHeight < heights[stack[#stack]] do
					height = heights[stack[#stack]]
					table.remove(stack)
					width = #stack > 0 and (i - stack[#stack] - 1) or (i-1)
					if width >= min_width and height >= min_height then
						maxArea = math.max(maxArea, height * width)
						max_rect = {x=i-width, w=width, h=height}
					end
				end
				table.insert(stack, i)
			end

			return maxArea, max_rect
		end

		function largest_rect(grid, min_width, min_height)
			local rows = #grid
			local cols = #grid[1]
			local heights = {}
			for i = 1, cols do table.insert(heights, 0) end
			local max_area = 0

			for y = 1, rows do
				for x = 1, cols do
					if grid[y][x] then
						heights[x] = heights[x] + 1
					else
						heights[x] = 0
					end
				end
				local area, new_max_rect = largest_rect_area(heights, min_width, min_height)
				DebugPrint("\tprocessing row "..y.. " maxarea = " .. area .. " rect = " .. dump(new_max_rect).."\n")
				if area > max_area then
					max_area = area
					max_rect = new_max_rect
					max_rect.y = y - max_rect.h + 1
				end
			end
				
			return max_rect
		end

		local grid = {}
		for iy,y in ipairs(y_axis_values) do
			local next_row_passes = {}
			table.insert(grid, {})
			for ix,x in ipairs(x_axis_values) do
				table.insert(grid[#grid], y_by_x[y] ~= nil and y_by_x[y][x] ~= nil and y_by_x[y][x].value >= limit_per_cell)
			end
		end

		DebugPrint("finding largest rect for grid: " .. dump(grid).."\n\n")
		passing_rect = largest_rect(grid, rect_size_limit[1], rect_size_limit[2])

		passed_area = passing_rect ~= nil
		DebugPrint("Test required passing rectangle of size " .. rect_size_limit[1] .."x"..rect_size_limit[2].. " passing rect:" .. dump(passing_rect).."\n")
	end

	local ok = passed_cells >= cell_limit and total >= total_limit and clamped_total >= clamped_total_limit
					and #passed_rows >= row_limit and #passed_columns >= column_limit and passed_unique and passed_area
	local html = {}
	local log = {}
	local vlog = {}

	if cell_limit > 1 then
		table.insert(log, "You had " .. passed_cells .. " cells with at least "..limit_per_cell .. " find(s), out of a required " .. cell_limit .. ".\n")
	end
	if total_limit > 1 then
		table.insert(log, "You had " .. total .. " find(s) in all cells, out of a required " .. total_limit .. ".\n")
	end
	if clamped_total_limit > 1 then
		table.insert(log, "You had " .. clamped_total .. " find(s) in all cells (maximum of "..limit_per_cell.."), out of a required " .. clamped_total_limit .. ".\n")
	end
	if row_limit > 0 then
		table.insert(log, "You had " .. #passed_rows .. " " .. y_axis .. (#passed_rows>1 and "s" or "")..", which had at least " .. limit_per_row .. " cells with "..limit_per_cell..", out of a required " .. row_limit .. ".\n")
	end
	if column_limit > 0 then
		table.insert(log, "You had " .. #passed_columns .. " " ..  x_axis .. (#passed_columns>1 and "s" or "")..", which had at least " .. limit_per_column .. " cells with "..limit_per_cell..", out of a required " .. column_limit .. ".\n")
	end
	if unique_row_limit > 0 then
		if passed_unique then
			table.insert(log, "You had " .. unique_row_limit .. " unique " ..  y_axis .. " values, which had cells with at least "..limit_per_cell..".\n")
		else
			table.insert(log, "You did not have " .. unique_row_limit .. " unique " ..  y_axis .. " values, which had cells with at least "..limit_per_cell..".\n")
		end
		if unique_cell_total > 0 then
			table.insert(log, "The total sum of the unique rows was " .. unique_cell_sum .. " out of a required " .. unique_cell_total .. "\n")
		end
	end
	if rect_size_limit ~= nil then
		if passed_area then
			local rect_string = "from ".. x_axis_values[passing_rect.x] .. " to " .. x_axis_values[passing_rect.x+passing_rect.w-1] .. " and from " .. y_axis_values[passing_rect.y] .. " to " .. y_axis_values[passing_rect.y+passing_rect.h-1]
			table.insert(log, "You had a rectangular area " .. rect_string .. " which met the required size of " .. rect_size_limit[1] .. "x".. rect_size_limit[2] .. "\n")
		else
			table.insert(log, "You did not have any rectangular area which met the required size of " .. rect_size_limit[1] .. "x".. rect_size_limit[2] .. "\n")
		end
	end

	table.insert(html, print_html_table(y_by_x, x_axis_values, y_axis_values, passed_rows, passed_columns))

	local passed_cell_n = 1
	if log_verbosity == 'verbose' then
		for y,row in pairs(y_by_x) do
			for x,find_list in pairs(y_by_x[y]) do
				local cell_value = find_list.value
				if cell_value >= limit_per_cell then
					table.insert(vlog, passed_cell_n .. ". " .. PrintFindsText(find_list, limit_per_cell, fields_required, true))
					passed_cell_n = passed_cell_n + 1
				end
			end
		end
	end

	function get_points()
		if point_type == "cells" then
			return passed_cells
		elseif point_type == "rows" then
			return #passed_rows
		elseif point_type =="cols" then
			return #passed_columns
		elseif point_type == "total" then
			return total
		end
		error ("Unknown points type: ".. pointType .. " valid are: loops and entries" )
	end

	local points = calculate_points(conf, ok, get_points())


	local shtml = table.concat(array_join(html, log), "<br/>")
	local slog = table.concat(array_join(log, vlog), "\n")
	local result = {ok=ok, log=slog, html=shtml}

	local res = {}
	res.ok = ok
	res.log = ""
	res.html= ""
	res.slog = ok_text(res.ok) .. ": " .. slog
	res.shtml = ok_text(res.ok) .. ": " ..  shtml
	res.points = points
	
	return res
end

-----------------------------------------------------
-- Copied from SameX / DifferentY by GreyHams
function c_samex_diffy(conf)

	-- Input parameters: (see original SameX / DifferentY script for more details)
	-- conf.SameX - string or list, dimensions that must be the same.
	-- conf.DifferentY - string, dimension that must be unique.
	-- conf.Groups - number of groups of DifferentY required to pass.
	-- conf.Minimum - minimum number of members of a group, that allows the group to pass.
	-- conf.Countdown - positive number, the 'Minimum' parameter is reduced by this amount on a successful group.
	-- conf.Minimums - a list of numbers, that must be in non-increasing order, specifying the 'Minimum' parameter, that changes on each subsequent pass. (eg. used for fibo decreasing tests)
	-- conf.Require - require finds to pass a function.
	-- conf.Exclude - exclude finds that pass a function.
	-- conf.Divisible - groups must be divisible by this number to pass (?)

	-- conf.Show - Output control. One of: "all"/"best"/"nothing"/"X only"/"Y counts"/"all Y counts"
	-- conf.ShowFields - Ouptut control. One of: "string"/"table"
	-- conf.GiveAdvice - Output control. true/false
	-- conf.GiveAdviceFinds - Whether to list of finds you have in the not-yet-completed group.
	-- conf.WeekStartsOn - Output control. "M" or not.
	local filter = FilterFromConfig(conf)

	local mintuplesize = 2
	local minimums_original = TableCopy(conf.Minimums)
	if (conf.Minimums ~= nil) then
		error_if(conf.Minimum ~= nil, "specified both Minimum and Minimums, only use one.")
		error_if(conf.Countdown ~= nil, "specified both Countdown and Minimums, only use one.")
		error_if(type(conf.Minimums) ~= 'table' or #conf.Minimums == 0, "Minimums must be an array")
		error_if(conf.Groups ~= nil and conf.Groups ~= #conf.Minimums, "Specified Groups and Minimums, and Groups != Minimums.")
		conf.Groups = #conf.Minimums
		for i=1, #conf.Minimums-1 do error_if(conf.Minimums[i] < conf.Minimums[i+1], "Minimums value "..i.." ("..conf.Minimums[i] ..") is less than the next value.") end		
		mintuplesize = table.remove(conf.Minimums,1)
		conf.Minimum = mintuplesize
	elseif (conf.Minimum ~= nil) and (tonumber(conf.Minimum)>0) then
		mintuplesize = tonumber(conf.Minimum)
	end

	local needed = 1
	if (conf.Groups ~= nil) and (tonumber(conf.Groups)>0) then
		needed = tonumber(conf.Groups)
	end

	-- The number to subtract from 
	local countdown = conf.Countdown or 0
	if (countdown < 0) then
	error({msg="conf.Countdown must be non-negative."})
	end

	local showall = false
	local buildall = false
	local showresults = true
	local showY = true
	local showcounts = true
	if conf.Show ~= nil then
	if conf.Show == "all" then
		showall = true
		buildall = true
	elseif conf.Show == "best" then
		buildall = true
	elseif conf.Show == "nothing" then
		showresults = false
	elseif conf.Show == "X only" then
		showY = false
		showcounts = false
	elseif conf.Show == "Y counts" then
		showY = false
		buildall = true
	elseif conf.Show == "all Y counts" then
		showall = true
		showY = false
		buildall = true
	end
	end
	if conf.Divisible then
		buildall = true
	end
	if conf.Countdown or conf.Minimums ~= nil then
		buildall = true
	end

	local showfields = {"gccode", "visitdate", conf.DifferentY, "cache_name"}
	if conf.ShowFields ~= nil then
		if type(conf.ShowFields) == "string" then
			showfields = {conf.ShowFields}
		elseif type(conf.ShowFields) == "table" then
			showfields = conf.ShowFields
		end
	end

	local giveadvice = get_default(conf.GiveAdvice, 1)
	if type(giveadvice) == 'boolean' then
		giveadvice = giveadvice and 1 or 0
	end
	local give_advice_finds = get_default(conf.GiveAdviceFinds, true)

	local startsonmonday = false
	if conf.WeekStartsOn ~= nil then
	if string.sub(conf.WeekStartsOn,1,1)=="M" then
		startsonmonday = true
	end
	end

	local x = conf.SameX
	if x == nil then x='same' end
	local y = conf.DifferentY
	if y == nil then y='gccode' end

	local needpublishers = false
	local allfields = {y}

	-- It used to be that samex_diffy had its own special transform. Convert these into the GetCombinedFinds verison.
	local transforms = conf.transforms or {}

	if (type(x) == "table") then
		for _, v in ipairs(x) do
			table.insert(allfields, v)
			if function_def[v] ~= nil then
				table.insert(transforms, {['func']=v})
			end
		end
	else
		table.insert(allfields, x)
		if function_def[x] ~= nil then
			table.insert(transforms, {['func']=x})
		end
	end

	if  y ~= nil and function_def[y] ~= nil then
		table.insert(transforms, {['func']=y})
	end

	if conf.Require ~= nil then
		for _,w in ipairs (conf.Require) do
			table.insert (allfields, w[1])
		end
	end
	if conf.Exclude ~= nil then
		for _,w in ipairs (conf.Exclude) do
			table.insert (allfields, w[1])
		end
	end

	for _,w in ipairs(showfields) do
		table.insert (allfields, w)
	end

	local fields = {}
	for _,f in ipairs(allfields) do
		table.insert (fields, f)
	end

	local finds = GetCombinedFinds(profileId, { lookup_cache=conf.lookup_cache, transforms=transforms, fields = fields, filter = filter, includeLabCaches = conf.labcaches or conf.include_labs }) -- NOTE: Legacy 'labcaches'

	-- It appears that some caches are coming up with nil counties, which causes an exception. Go through and assign invalid entries to those.
	local nil_id = 1
	for _,f  in ipairs(finds) do
	if type(x) == 'table' then
		for _,v in ipairs(x) do
		if f[v] == nil then
			DebugPrint("WARNING: a cache has a nil field for the SameX ("..v..") value:\n" .. dump(f) .. "\n")
			f[v] = "INVALID_" .. nil_id
			nil_id = nil_id + 1
		end
		end
	elseif type(x) == 'string' then
		if f[x] == nil then
		DebugPrint("WARNING: a cache has a nil field for the SameX ("..x..") value:\n" .. dump(f) .. "\n")
		f[x] = "INVALID_" .. nil_id
		nil_id = nil_id + 1
		end
	else
		error("'x' (".. dump(x) .." must be a table or string.")
	end

	if f[y] == nil then
		DebugPrint("WARNING: a cache has a nil field for the DifferentY ("..y..") value:\n" .. dump(f) .. "\n")
		f[y] = "INVALID_" .. nil_id
		nil_id = nil_id + 1
	end
	end

	if needpublishers then
	local gccode2i = {}
	for i,f in ipairs(finds) do
		gccode2i[f.gccode] = i
	end
	local publishers = PGC.GetPublishers( profileId, {filter = filter })
	for _,p in ipairs(publishers) do
		if gccode2i[p.gccode] ~= nil then
		if finds[gccode2i[p.gccode]].reviewer == nil then
			finds[gccode2i[p.gccode]].reviewer = p.publisher_name
		end
		end
	end
	end

	if conf.Require ~= nil then
	for i=#finds,1,-1 do
		for _,r in ipairs (conf.Require) do
		local v,func,c = finds[i][r[1]], r[2], r[3]
		if type(c)=="number" and type(v)=="string" and string.find(func,"[<>=]") ~= nil then
			v = tonumber(v)
		end
		if (func == "regex" and string.find (v,c) == nil)
			or (func == "exists" and (v==nil or v==""))
			or (func == "=" and (v==nil or v~=c))
			or (func == ">" and (v==nil or v<=c))
			or (func == ">=" and (v==nil or v<c))
			or (func == "<" and (v==nil or v>=c))
			or (func == "<=" and (v==nil or v>c)) then
			table.remove (finds, i)
			break
		end
		end
	end
	end
	if conf.Exclude ~= nil then
	for i=#finds,1,-1 do
		for _,r in ipairs (conf.Exclude) do
		local v,func,c = finds[i][r[1]], r[2], r[3]
		if type(c)=="number" and string.find(v,"[<>=]") ~= nil then
			v = tonumber(v)
		end
		if (func == "regex" and string.find (v,c) ~= nil)
			or (func == "exists" and (v~=nil and v~=""))
			or (func == "=" and (v~=nil and v==c))
			or (func == ">" and (v~=nil and v>c))
			or (func == ">=" and (v~=nil and v>=c))
			or (func == "<" and (v~=nil and v<c))
			or (func == "<=" and (v~=nil and v<=c)) then
			table.remove (finds, i)
			break
		end
		end
	end
	end

	if #finds == 0 then
		local res = {}
		res.ok = false
		res.log = ""
		res.html= ""
		res.slog = ok_text(res.ok) .. ": " .. profileName..' does not have any qualifying finds.\n'
		res.shtml = ok_text(res.ok) .. ": " ..  '<b>'..profileName..'</b> does not have any qualifying finds.</b>'
		return res
	end

	local tuples = {}
	local tuplesize = {}
	local qualified_tuples = {}
	local unqualified_tuples = {}

	function same(f,x)
		if (type(x)=="table") then
			local same_field = ""
			for i,v in ipairs(x) do
				same_field = same_field .. (i >1 and " / " or "") .. f[v]
			end
			return same_field
		elseif (type(x) =="string") then
			return f[x]
		end
		error("'x' must be a table or string, but it's a " .. type(x) .. " = " .. dump(x))
	end

	function valid_fields(f,x)
		if (type(x)=="table") then
			local all_valid = true
			for _,v in ipairs(x) do
				all_valid = all_valid and valid_fields(f,v)
			end
			return all_valid
		elseif (type(x) ~="boolean") then
			return true
		end
		return false
	end

	for n,f in ipairs (finds) do
		if valid_fields(f,x) and valid_fields(f,y) then
			if tuples[same(f,x)] == nil then
				tuples[same(f,x)] = {}
				tuplesize[same(f,x)] = 0
			end
			if tuples[same(f,x)][f[y]] == nil then
				if tuplesize[same(f,x)] < mintuplesize or buildall then
					local sx = same(f,x)
					local sy = f[y]
					if sx == nil or sy == nil then
						error("sx = " .. dump(sx) .. " sy=" .. dump(sy) )
					end
					tuples[same(f,x)][f[y]] = n
					tuplesize[same(f,x)] = tuplesize[same(f,x)] + 1
					if tuplesize[same(f,x)] == mintuplesize or countdown > 0 or conf.Minimums ~= nil then
						insert_into_list_if_unique(same(f,x), qualified_tuples)
						if #qualified_tuples >= needed and not buildall then
							break
						end
					end
				end
			end
		end
	end

	if conf.Divisible and conf.Divisible>1 then
		local q = {}
		for k,v in pairs(qualified_tuples) do
			if ((tuplesize[v] % conf.Divisible) == 0) then
				table.insert(q,v)
			else
				DebugPrint("dropping "..v..":"..tuplesize[v].." not divisible by "..conf.Divisible.."\n")
			end
		end
		qualified_tuples = q
	end

	table.sort (qualified_tuples, function(a,b) return tuplesize[a] > tuplesize[b] end)

	if countdown > 0 or conf.Minimums ~= nil then
		local q = {}
		while #qualified_tuples > 0 do
			local passed_tuple = tuplesize[qualified_tuples[1]] >= mintuplesize
			DebugPrint(qualified_tuples[1] .. " had " .. tuplesize[qualified_tuples[1]] .. " entries. " .. (passed_tuple and "PASS" or "FAIL") .."\n")
			if passed_tuple then
				table.insert(q, qualified_tuples[1])

				if countdown > 0 then
					mintuplesize = math.max(1, mintuplesize - countdown) -- reduce the minimum size by 'countdown' if it passes
				elseif #conf.Minimums > 0 then
					mintuplesize = table.remove(conf.Minimums, 1)
				end
			end
			table.remove(qualified_tuples, 1)
		end
		qualified_tuples = q
	end

	-- Find all the unqualified tuples now. Literally just all tuples that aren't qualified.
	for same, tuple in pairs(tuples) do
		if find_in_list(same, qualified_tuples) <= 0 then
			table.insert(unqualified_tuples, tuple)
		end
	end

	local ok = false
	local log = ""
	local html = ""

	local for_the_same = ""
	if type(x) == "table" then
		for i,v in ipairs(x) do
			if function_def[v].name>"" then
				for_the_same = for_the_same .. (i > 1 and " and " or "") .. function_def[v].name
			end
		end
	else
		if function_def[x].name>"" then
			for_the_same = function_def[x].name
		end
	end


	ok = (#qualified_tuples >= needed)
	local needed_size = conf.Minimum
	local minimum_index = 2 -- start at 2, because 1 is already the value of conf.Minimum
	if showresults then
		if not showall then
			while #qualified_tuples > needed do
				table.remove (qualified_tuples)
			end
		end

		local log_html = {}
		local log_text = {}
		for _,k in ipairs(qualified_tuples) do
			local same_output_html = ""
			local same_output_text = ""
			if for_the_same > "" and showY then
				same_output_html = same_output_html .. for_the_same .. ": "
				same_output_text = same_output_text .. for_the_same .. ": "
			end
			if k.."" > "" then
				same_output_html = same_output_html .. "<b>"..k.."</b>"
				same_output_text = same_output_text .. "**"..k.."**"
				if showcounts then
					same_output_html = same_output_html .. " (" .. tuplesize[k] .. "/" .. needed_size .. ")"
					same_output_text = same_output_text .. " (" .. tuplesize[k] .. "/" .. needed_size .. ")\n"
				end

				if conf.Minimums ~= nil then
					needed_size = minimum_index <= #minimums_original and minimums_original[minimum_index] or 1
					minimum_index = minimum_index + 1
				else
					needed_size = math.max(1, needed_size - countdown)
				end
			end
			if showY then
				local ys = {}
				for i,c in pairs (tuples[k]) do
					finds[tuples[k][i]].i = i
					table.insert (ys, finds[tuples[k][i]])
					if function_def[y].write ~= nil then
						finds[tuples[k][i]].y = function_def[y].write(finds[tuples[k][i]])
					end
				end
				table.sort (ys, function(f1, f2) return f1.i < f2.i end )
				same_output_html = same_output_html .. PrintFindsHtml(ys, #ys, showfields, true)
				same_output_text = same_output_text .. PrintFindsText(ys, #ys, showfields, nil, true)
			end

			table.insert(log_html, same_output_html)
			table.insert(log_text, same_output_text)
		end
		
		html = table.concat (log_html, "<br/>")
		log = table.concat (log_text, showY and "\n\n" or "\n")
	end

	html = html .. "<br/>" .. profileName .. " found " .. #qualified_tuples .. " groups of " .. ((countdown or conf.Minimums) and "" or (mintuplesize .. " or more ")) .. "different " .. function_def[y].name .. " for the same " .. for_the_same .." out of a required " .. needed .. " such groups.<br/>"

	if not ok and giveadvice and x~="visitdate" then
		unqualified_find_tuples = {}
		for _, unq_tuple in ipairs(unqualified_tuples) do
			local ys = {}
			for i,c in pairs (unq_tuple) do
				finds[unq_tuple[i]].i = i
				table.insert (ys, finds[unq_tuple[i]])
				if function_def[y].write ~= nil then
					finds[unq_tuple[i]].y = function_def[y].write(finds[unq_tuple[i]])
				end
			end
			table.sort (ys, function(f1, f2) return f1.i < f2.i end )
			table.insert(unqualified_find_tuples, ys)
		end

		table.sort(unqualified_find_tuples, function(t1, t2) return #t1 > #t2 end )
		for i = 1, math.min(giveadvice,#unqualified_find_tuples) do
			ys = unqualified_find_tuples[i]
			html = html .. "<br/><b>To continue working on this challenge, try adding additional " .. function_def[y].name .. " to the following " .. for_the_same .. " for already has " .. #ys .. " " .. function_def[y].name .. ":</b><br/><br/>"
			local xstring = ""
			if type(x) == 'table' then
				local xvs = {}
				for _, xv in ipairs(x) do
					table.insert(xvs, ys[1][xv])
				end
				xstring = table.concat(xvs, " and ")
			else
				xstring = ys[1][x]
			end
			html = html .. for_the_same .. ": <b style='color: red'>"..xstring.."</b>"
			if showcounts then
				html = html .. " (" .. #ys .. "/" .. needed_size .. ")"	
			end
			if give_advice_finds then
				html = html .. PrintFindsHtml(ys, #ys, showfields, true) .. "<br/>"
			end
		end
	end

	local res = {}
	res.ok = ok
	res.log = ""
	res.html= ""
	res.slog = log
	res.shtml = html
	return res
end

