function c_sequence(conf)

	-- parameters
	local filter = FilterFromConfig(conf)				-- standard filter.
	local field = conf.field 							-- the field that must be sequential. eg. gccode, cache_name, etc.
	local transforms = conf.transforms or {}			-- transforms to be applied to each cache.
	local limit = conf.limit     						-- number in the sequence required to pass
	local continuous = (conf.continuous==nil and true or conf.continuous) 			-- whether the sequence must be continuous
	local brief = conf.brief or false					-- whether to print the caches out
	local print_all_sequences = conf.print_all or false	-- whether ALL sequences, even failing ones are printed.
	local fields = {'gccode', 'cache_name', 'visitdate'}
	local print_fields = conf.print_fields or fields 	-- the fields to print out in the log, if not brief.
	local sort_field = conf.sort_field or field			-- The field to sort the printed results
	local start_criteria = conf.start_criteria			-- {field = 'field_name', value = ?}
	local end_criteria = conf.end_criteria				-- same format as start criteria
	local end_count = conf.end_count or 1				-- number of times you need to get a 'true' on the end criteria to actually end.
	local ignore_dupes = conf.ignore_dupes or true		-- allows duplicate values in sequence. Eg. if going for a date, two dates in a row do not count as a broken sequence
	local leapday = conf.leapday or true				-- if you're using a mmdd criteria, whether leapday is included.

	if end_criteria == nil and conf.end_count ~= nil then
		error("You didn't specify end_criteria, but used end_count.")
	end

	if field == nil and (start_criteria ==nil and end_criteria==nil) then
		error ("Must specify a field to be sequenced, OR start_criteria and end_criteria must be specified.")
	end

	-- If they don't give a field, assume it's the start_criteria field.
	if field == nil then
		field = start_criteria.field
		sort_field = sort_field or field
	end

	insert_into_list_if_unique(conf.field, fields)
	insert_into_list_if_unique(sort_field, fields)
	for _, pf in ipairs(print_fields) do
		insert_into_list_if_unique(pf, fields)
	end

	local finds = GetCombinedFinds(profileId, { lookup_cache=conf.lookup_cache,transforms=conf.transforms, fields = fields, order = 'OLDESTFIRST', filter = filter, includeLabCaches=conf.include_labs })

	if sort_field ~= nil then
		DebugPrint("Sorting by " .. sort_field .. "\n")
		table.sort(finds, function(f1, f2) return f1[sort_field] < f2[sort_field] end)
	end

	function can_start_sequence(find)
		if start_criteria ~= nil then
			return find[start_criteria.field] == start_criteria.value
		end
		return true
	end

	function sequence_complete(sequence)
		if end_criteria ~= nil then
			if #sequence > 0 then
				local find = sequence[#sequence]
				sequence.count = (sequence.count or 0)
				if find[end_criteria.field] == end_criteria.value then
					sequence.count = sequence.count + 1
					DebugPrint("Another sequence.count: " .. PrintFindsText({find},1,{'gccode','cache_name'}))
				end
				return sequence.count >= end_count
			else
				return false -- nothing in it.
			end
		end
		
		return #sequence >= limit
	end

	-- search for the sequence
	local start_index = 1
	local sequence = {}
	local longest_passing_sequence = {}
	local sequence_outputs = {}
	for i = start_index, #finds do

		if #sequence==0  then
			-- If it's first, then it always passes

			if can_start_sequence(finds[i]) then
				table.insert(sequence, finds[i])
			else
				-- You would think start_index+1, but when you run the next loop iteration, i will be incremented again.
				i = start_index
				start_index = start_index+1
			end
		else
			if next_value(field, sequence[#sequence][field]) == finds[i][field] then
				-- If it's first (and allowed to be first), then it always passes
				table.insert(sequence, finds[i])
				local complete = sequence_complete(sequence)
				if complete or #sequence > #longest_passing_sequence then
					longest_passing_sequence = TableCopy(sequence)
					if complete then
						-- If not printing all, we can stop now because we found a pass.
						table.insert(sequence_outputs, PrintFindsHtml(sequence,#sequence,print_fields))
						if not print_all_sequences then
							break
						end
						sequence = {}
						-- NOTE: Check if *this* find can start a new sequence, and if so, add it to the new sequence now.
						if can_start_sequence(finds[i]) then
							table.insert(sequence, finds[i])
						end
					end
				end
			elseif (ignore_dupes or dupes_required) and (sequence[#sequence][field] == finds[i][field]) then
				-- do nothing, ignore it.
			elseif continuous then
				if #sequence > #longest_passing_sequence then
					longest_passing_sequence = TableCopy(sequence)
				end

				if print_all_sequences then
					table.insert(sequence_outputs, PrintFindsHtml(sequence,#sequence,print_fields))
				end

				sequence={}

				-- NOTE: Check if *this* find can start a new sequence, and if so, add it to the new sequence now.
				if can_start_sequence(finds[i]) then
					table.insert(sequence, finds[i])
				end
			end
		end
	end

	if #sequence_outputs == 0 then
		table.insert(sequence_outputs, PrintFindsHtml(longest_passing_sequence,#longest_passing_sequence,print_fields))
	elseif #sequence > 0 then
		table.insert(sequence_outputs, PrintFindsHtml(sequence,#sequence,print_fields))
	end

	local ok = sequence_complete(longest_passing_sequence)
	local slog = "User has " .. #longest_passing_sequence .. " finds in sequence " .. (limit and "(" .. limit .. " needed)." or "") .." "..PrintFilter(filter).."\n"
	local shtml = "User has " .. #longest_passing_sequence .. " finds in sequence " .. (limit and "(" .. limit .. " needed)." or "") .." "..PrintFilter(filter)
	local log = slog
	local html = shtml

	if not brief then
		slog = slog.."\n"..PrintFindsText(longest_passing_sequence,#longest_passing_sequence,print_fields)
		if ok then
			shtml = shtml..PrintFindsHtml(longest_passing_sequence,#longest_passing_sequence,print_fields)
		else
			shtml = shtml.."<br>".. table.concat(sequence_outputs,"<hr/>")
		end
	end

	local res = {}
	res.ok = ok
	res.log = ""
	res.html= ""
	res.slog = ok_text(res.ok) .. ": " .. slog
	res.shtml = ok_text(res.ok) .. ": " ..  shtml
	return res

end
-----------------------------------------------------
function c_histogram(conf)
	local group = conf.group						-- The field that splits finds into different groups.
	local limit_per_field = conf.group_limit or 1	-- The count per group that 'passes'
	local average_field = conf.average_field		-- The field to take the average values of a group
	local average_opt = conf.average_opt			-- See binary_comparison - struct should contain op and v1 (v0 will be the average).
	local limit = conf.limit or 1					-- The number of groups passing that constitutes a pass
	local filter = FilterFromConfig(conf)	    	-- standard filter
	local fields = {'gccode', 'cache_name', 'visitdate'}	-- fields to retrive for fav caches
	local print_groups = get_default(conf.print_groups, true)	-- Whether the groups should be printed to the output
	local print_finds = conf.print_finds or "none"	-- Which finds to print. none/group/all - none = nothing, group = finds up to group_limit, all = all finds in any groups
	local print_fields = conf.print_fields		-- the fields to print out in the log, if printing finds.
    local log = {}
    local html = {}

	if group == nil then
		error("Must specify 'group', the field in which the grouping takes place.")
	end

	if average_field ~= nil and average_opt == nil then
		error("You specified average_field, but not average_group_opt - needs both.")
	end
	
	insert_into_list_if_unique(group, fields)
	if average_field ~= nil then
		insert_into_list_if_unique(average_field, fields)
	end

	if print_fields == nil then
		print_fields = fields
	end

	-- Get the finds.
	local finds = GetCombinedFinds(profileId, {lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = fields, order="OLDESTFIRST", filter=filter, includeLabCaches=conf.include_labs})

	-- Error out if they use an invalid field.
	if #finds >= 0 and finds[1][group] == nil then
		error("Field '" .. group .."' is not a valid find field.")
	end

	-- generate the histogram
	local histogram = {}
	for _, find in ipairs(finds) do
        if find[group] ~= nil then 
			histogram[find[group]] = histogram[find[group]] or {}
			histogram[find[group]].key = find[group]
			histogram[find[group]].count = (histogram[find[group]].count or 0) + (tonumber(find[group]) or 1)
			histogram[find[group]].finds = histogram[find[group]].finds or {}
			table.insert(histogram[find[group]].finds, find)
      end
	end

	-- Calcualte the average
	if average_field ~= nil then
		for group, entry in pairs(histogram) do
			local value = 0
			for _, find in ipairs(entry.finds) do
				value = value + tonumber(find[average_field])
			end
			entry.average = value / #entry.finds
		end	
	end

	local log ={}
	local html = {}
	local passing_histo = {}
	for group, entry in spairs(histogram) do
		if entry.count >= limit_per_field then
			if average_field == nil then
				table.insert(passing_histo, entry)
				if print_groups then
					table.insert(log, group .. ": " .. histogram[group].count .. " (" .. #entry.finds .. " finds)")
					table.insert(html, group .. ": " .. histogram[group].count .. " (" .. #entry.finds .. " finds)")
				end
			else
				if binary_comparison(average_opt.op, entry.average, average_opt.v1)  then
					table.insert(passing_histo, entry)
					if print_groups then
						table.insert(log, group .. ": "..average_field.." ".. string.format("%.3f",entry.average) .. " average (" .. #entry.finds .. " finds)")
						table.insert(html, group .. ": "..average_field.." ".. string.format("%.3f",entry.average) .. " average (" .. #entry.finds .. " finds)")
					end
				end
			end
		end
	end

	local sum_description = (limit_per_field > 1) and ", with '"..group.."' having a sum of " ..limit_per_field.." or more. "..PrintFilter(filter).."\n" or "\n"
	table.insert(log,  "User has " .. #passing_histo .. " " .. plural(group) .. " (" .. limit .. " needed)" .. sum_description)
	table.insert(html, "User has " .. #passing_histo .. " " .. plural(group) .. " (" .. limit .. " needed)" .. sum_description)

	if print_finds == "group" or print_finds == "all" then		
		for group_number, entry in ipairs(passing_histo) do
			local print_limit = print_finds == "all" and #entry.finds or limit_per_field
			table.insert(log,"")
			table.insert(log, "#"..group_number..". (" .. group .. ' = ' .. entry.key .. ")")
			table.insert(log, PrintFindsText(entry.finds, print_limit, print_fields))
			table.insert(html,"")
			table.insert(html, "#"..group_number..". (" .. group .. ' = ' .. entry.key .. ")")
			table.insert(html, PrintFindsHtml(entry.finds, print_limit, print_fields))
		end
	end

	local ok = #passing_histo >= limit
	local slog = table.concat(log, "\n")
	local shtml = table.concat(html, "<br/>")

	local res = {}
	res.ok = ok
	res.log = ""
	res.html= ""
	res.slog = ok_text(res.ok) .. ": " .. slog
	res.shtml = ok_text(res.ok) .. ": " ..  shtml
	return res
end
-----------------------------------------------------
function c_unique_value(conf)
	local filter = FilterFromConfig(conf)			 -- standard filter
	local xfield = conf.x							 -- the 'grouping' field.
	local xfilters = conf.x_filters or conf.xf		 -- Each of these is run as a filter, to bin the xgroups, instead of using xfield.
	local yfield = conf.y							 -- the field(s) that must be unique value for per group
	local fields = {'gccode', 'cache_name', 'visitdate'}	-- fields to retrive for fav caches
	local print_fields = conf.print_fields 			 -- the fields to print out in the log, if not brief.
	local limit = conf.limit    					 -- the number of unique values required to pass (one per group, if not specified).
	local default_func = conf.default_func			 -- to save space in the tag, if there are many that use the same function.
	local default_opt = conf.default_opt or {}		 -- to save space in the tag, if there are many that use the opt function. It is MERGED with any existing opt.
	local re_field = conf.re_field or "cache_name"	 -- if a just a regex string filter is used, the field that is used.
	local sort_field = conf.sort_field or "group"	 -- the field to sort the results on, defaults to the binned group (eg. 'x' value) if not specified
	local find_best_failure = conf.find_best_failure or true	-- If the result is failure, keep re-running to find the best result with less requirements
	local initial_timeout = conf.initial_timeout or 45 				-- spend up to 45s trying to find a solution. If it fails, keep trying with less requirements.
	local max_timeout = conf.max_timeout or 58 						-- max timeout is 58s, to be under the 60s.
	local best_timeout_increment = conf.best_timeout_increment or 2	-- give each "best" attempt 2s.

	if xfield == nil and xfilters == nil then
		error('Must supply "x" or "x_filters"')
	end
	if yfield == nil then
		error('"y" cannot be omitted.')
	end
	if type(yfield) == 'string' then
		yfield = {yfield}
	end

	if (xfield ~= nil) then
		insert_into_list_if_unique(xfield, fields)
	end
	for _,yf in ipairs(yfield) do
		insert_into_list_if_unique(yf, fields)
	end

	if (xfilters ~= nil) then
		local new_xfilters = {}
		for _,xf in ipairs(xfilters) do
			-- any xf that's just a string becomes a regex filter against the cache name.
			if type(xf) == 'string' then
				local new_xf = {func="regex",opt={field=re_field, pattern=xf}}
				xf = new_xf
			end
			table.insert(new_xfilters,xf)
		end
		xfilters = new_xfilters

		for _,xf in ipairs(xfilters) do

			local fields_in_criteria = fields_in_criteria(xf)
			for _, field in ipairs(fields_in_criteria) do
				insert_into_list_if_unique(field, fields)
			end
		end
	end

	if print_fields == nil then
		print_fields = {'group', 'gccode', 'cache_name', 'visitdate'}
		for _,yf in ipairs(yfield) do
			insert_into_list_if_unique(yf, print_fields)
		end
	end

	if xfilters ~= nil then
		for _, xf in ipairs(xfilters) do
			if xf.name == nil then
				xf.name = criteria_as_string(xf)
			end
			if xf.field == nil and xf.func == nil then
				DebugPrint("No function specified for " .. xf.name .. ", using default_func: " .. default_func .. "\n")
				xf.func = default_func
			end
			xf.opt = table_join(xf.opt or {}, default_opt)
		end
	end

	-- Bin the finds into each 'x' field
	local xfield_groups = {}
	local finds = GetCombinedFinds(profileId, {lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = fields, order="OLDESTFIRST", filter=filter, includeLabCaches=conf.include_labs})

	for _, f in ipairs(finds) do
		if xfilters ~= nil then
			for xi, xf in ipairs(xfilters) do
				if find_satisfies_criteria(f, xf) then
					xfield_groups[xf.name] = xfield_groups[xf.name] or {}
					local new_f = TableCopy(f)
					new_f.group = xf.name
					new_f.group_index = xi
					insert_in_list_if_unique_fields(new_f, yfield, xfield_groups[xf.name])
				end
			end
		else
			if f[xfield] ~= nil then
				xfield_groups[f[xfield]] = xfield_groups[f[xfield]] or {}
				local new_f = TableCopy(f)
				new_f.group = f[xfield]
				insert_in_list_if_unique_fields(new_f, yfield, xfield_groups[f[xfield]])
			else
				DebugPrint("Excluding " .. f.gccode .. " because " .. xfield .. "== nil\n")
			end
		end
	end

	-- Now, from the xfield groups, find a find (hrmm) with a unique value of y. NOTE: This has really bad O(x)... if there's lots of groups and possible values, it'll probably timeout.
	local solution = {}
	local arrays = {}
	local found_group_count = 0
	local unique_values = {}
	for k,v in spairs(xfield_groups) do 
		found_group_count = found_group_count + 1
		table.insert(arrays,v) 
		for _,cache in ipairs(v) do
			for _,yf in ipairs(yfield) do
				unique_values[yf] = unique_values[yf] or {}				
				insert_into_list_if_unique(cache[yf], unique_values[yf])
			end
		end
	end

	-- To reduce the search space, iteratively remove items from other arrays, that only have one option.
	reduce_array_choices(yfield, arrays, found_group_count)

	DebugPrint("Total found groups: " .. found_group_count .."\n")

	limit = limit or (xfilters ~= nil and #xfilters or error("Must supply 'limit', if not using xfilters."))
	if type(limit) ~= 'table' then
		local new_limit_array = {}
		for _,mr in ipairs(yfield) do
			table.insert(new_limit_array,limit)
		end
		limit = new_limit_array
		DebugPrint("limit was not an array, expanding.\n")
	end

	local original_limits = TableCopy(limit)
	local enough_groups = true
	for i = 1,#limit do
		if found_group_count < limit[i] then
			DebugPrint("Reducing required found limit, because you haven't found enough groups (just looking for the best solution, but passing is not possible.)\n")
			limit[i] = found_group_count
			enough_groups = false
		end
	end

	local result = choose_unique_fields_per_array(arrays, 1, yfield, solution, limit, nil, initial_timeout)
	local ok_message = ""

	-- If it fails, it's going to return a really bad result. Say you need less and try again.
	local best_timeout = initial_timeout
	if find_best_failure and result.ok == false then
		while result.ok == false do
			for i,l in ipairs(limit) do
				limit[i] = math.max(l-1,0)
			end
			 best_timeout = math.min(max_timeout, best_timeout + (best_timeout_increment))
			result = choose_unique_fields_per_array(arrays, 1, yfield, solution, limit, nil, best_timeout)
		end
		result.ok = false
	end	

	for i = 1, #yfield do
		local f = yfield[i]
		local found = 0
		local value_hash = {}
		for _,c in ipairs(result.best_solution) do
			if value_hash[c[f]] == nil then
				value_hash[c[f]] = 1
				found = found + 1
			end
		end

		ok_message = ok_message .. "You have found " .. found .. " out of a required " .. original_limits[i] .. " of " .. f .. " values.\n"		
	end

	-- Sort it back into group order.
	table.sort(result.best_solution or {}, function(f1,f2) return f1[sort_field] < f2[sort_field] end)
	
	local res = {}
	res.ok = result.ok and enough_groups
	if not res.ok and xfilters ~= nil then
		local missing_groups = {}
		for _,xf in pairs(xfilters) do
			local missing = true
			for _,f in ipairs(result.best_solution) do
				if f.group == xf.name then
					missing = false
					break
				end
			end	
			if missing then
				table.insert(missing_groups, xf.name)
			end
		end		
		ok_message = ok_message .. "You are missing these groups: " .. table.concat(missing_groups, ", ")
	end

	res.caches = array_splice(result.best_solution,1, #result.best_solution) -- remove any non-list fields
	res.log = ""
	res.html= ""
	res.slog = ok_text(res.ok) .. ": " .. ok_message .. "\n\n" .. PrintFindsText(result.best_solution, #result.best_solution, print_fields)
	res.shtml = ok_text(res.ok) .. ": " .. ok_message .. "<br/><br/>" ..  PrintFindsHtml(result.best_solution, #result.best_solution, print_fields)
	return res

end

