function c_fizzy_complete(conf)
	
	local filter = FilterFromConfig(conf)
	local field = conf.field or error("Must supply 'field'")
	local limit = conf.limit or 1	-- number of unique values of 'field' you must get to pass.
	local fields = {'gccode', 'cache_name', 'visitdate', 'difficulty', 'terrain'}
	local print_fields = conf.print_fields

	-- fetch field if it's not fetched already.
	insert_into_list_if_unique(field, fields)
	local finds = GetCombinedFinds(profileId, {lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = fields, order="OLDESTFIRST", filter=filter})

	local fizzy_values = {}
	local fizzy_count = {}
	local current_fizzy = 0
	for _, find in ipairs(finds) do
		dt = find.difficulty..find.terrain
		fizzy_count[dt] = (fizzy_count[dt] or 0)+1
		if (fizzy_count[dt] == current_fizzy+1) then
			local current_fizzy_complete = true
			local spot_count = 0
			for _,count in pairs(fizzy_count) do
				spot_count = spot_count +1
				if (count < current_fizzy+1) then
					current_fizzy_complete = false
					break
				end
			end
			if (current_fizzy_complete and spot_count == 81)  then
				current_fizzy = current_fizzy+1
				DebugPrint("Completed fizzy " .. current_fizzy .. " with " .. find.gccode .. "(field="..field.."="..find[field]..")\n")
				
				find.fizzy_number=current_fizzy -- mark the find with which fizzy it completed
				fizzy_values[find[field]] = fizzy_values[find[field]] or {}				
				table.insert(fizzy_values[find[field]], find)
			end
		end
	end

	local ordered_fizzy_list = {}
	local unique_complete = 0
	for field_values, find_list in pairs(fizzy_values) do
		unique_complete = unique_complete+1
		table.insert(ordered_fizzy_list, find_list[1])
	end

	table.sort(ordered_fizzy_list, function (f1, f2) return f1.fizzy_number < f2.fizzy_number end)

	ok = unique_complete >= limit

	local log = {}
	local html= {}

	table.insert(log, "You have completed a fizzy with " .. unique_complete .. " unique " .. field .. " values out of a required " .. limit .. ".")
	table.insert(html, "You have completed a fizzy with " .. unique_complete .. " unique " .. field .. " values out of a required " .. limit .. ".")

	print_fields = print_fields or TableCopy(fields)
	table.insert(print_fields, 1, 'fizzy_number')
	table.insert(log, PrintFindsText(ordered_fizzy_list,#ordered_fizzy_list, print_fields))
	table.insert(html, PrintFindsHtml(ordered_fizzy_list,#ordered_fizzy_list, print_fields))

	local shtml=table.concat(html,"<br/>")
	local slog=table.concat(log, "\n")

	local ok = #ordered_fizzy_list >= limit
	local res = {}
	res.ok = ok
	res.log = ""
	res.html= ""
	res.slog = slog
	res.shtml = shtml
	return res
end

