function c_from_home(conf)
	local furthest = PGC.GetFurthestFound(conf.filter) -- for filter, see https://project-gc.com/doxygen/lua-sandbox/classPGC__LUA__Sandbox.html#a91560b921f4a4ce5e0e85f3b15ad6c2b
	local distance = conf.distance or error("Must supply 'distance' with func='from_home'")

	local res = {}
	res.log = ""
	res.html = ""
	local log = {}

	if type(furthest)=='boolean' and furthest == false then
		error("User did not have home coordinates. Could not determine furthest cache from home.")
	else
		res.ok = furthest.distance >= distance
		table.insert(log, "Furthest found from home: " .. furthest.gccode .. " is " .. furthest.distance .. "km away, required distance is " .. distance)
	end
	res.shtml = table.concat(log, "<br/>")
	res.slog = table.concat(log, "\n")
	return res
end

local indent = ""
