function c_lonely(conf)
	local fallback = conf.fallback or 'last_publish_date'			-- fallback field if the cache has never been found. either last_publish_date or 'hidden'
	local days = conf.days or 1										-- number of days a cache must be lonely to be included
	local limit = conf.limit or 1									-- total number of lonely finds required
	local fields = {'gccode', 'visitdate', 'cache_name'}			-- fields to retrieve
	local print_fields = conf.print_fields or fields				-- fields to print from finds.
	local show = conf.show or "limit"								-- finds to show in the output. ("all", "limit" - only the number needed, "none" - don't print finds)
	local filter = FilterFromConfig(conf)							-- filter
	local pointType = conf.pointType								-- If calculating points, then type of points ("total_days" = sum of days of passing finds, "count" = number of finds)

	local lonely = PGC.GetLonelyFinds(profileId, days, { fallback = fallback })
	local finds = GetCombinedFinds(profileId, {lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = fields, order="OLDESTFIRST", filter=filter})
	local merged_lonely = array_join_by_field(lonely, finds, 'gccode')
	local qualified_n = math.min(#merged_lonely, limit)

	-- Much more useful if num_days is a number, not a string.
	for _,ml in ipairs(merged_lonely) do
		ml.num_days = tonumber(ml.num_days)
	end

	table.sort(merged_lonely, function (l1, l2) return l1.num_days > l2.num_days end)
	
	-- Pretty much always want to print out the number of days lonely...
	insert_into_list_if_unique('num_days', print_fields)

	res = {}
	res.ok = qualified_n >= limit
	res.html =  ""
	res.log = ""
	res.shtml = "You had " .. #merged_lonely .. " lonely finds out of a required " .. limit .. ", which were at least " .. days .. " days lonely."
	res.shtml = res.shtml .. (show == "none" and "" or PrintFindsHtml(merged_lonely, (show == "all" and #merged_lonely or qualified_n), print_fields))
	res.slog = "You had " .. #merged_lonely .. " lonely finds out of a required " .. limit .. ", which were at least " .. days .. " days lonely."
	res.slog = res.slog .. (show == "none" and "" or PrintFindsText(merged_lonely, (show == "all" and #merged_lonely or qualified_n), print_fields))

	local points = nil
	if res.ok and conf.pointsPer ~= nil then
		if pointType == "count" or pointType == nil then
			points = (points or 0) + conf.pointsPer * math.min(#merged_lonely, limit)
		elseif pointType == "total_days" then
			for i=1,qualified_n do
				points = (points or 0) + conf.pointsPer * merged_lonely[i].num_days
			end
		else
			error("Invalid point type. Must be count/total_days (or nil), but " .. conf.pointType .. " was used.")
		end
	end
	res.points = points
	res.caches = array_splice(merged_lonely,1,qualified_n)
	return res
end
------------------------------------------------------------
function c_generic_fizzy(conf)

	local fizzy_defs = conf.fizzies or error("Must supply 'fizzies' to generic_fizzy")
	local verbose_log  = conf.verbose_log or false
	local full_table_on_pass = conf.verbose_table or false
	local filter = FilterFromConfig(conf)

	local fields_required = {'gccode', 'visitdate', 'difficulty', 'terrain', 'type'}
	local criteria_list = {}
	local transforms = conf.transforms

	function dtidx(d, t)
		return ((tonumber(d)-1)*2)*9 + tonumber(t)*2-1 -- 1..81
	end
	function revdtidx(idx)
		local d = (math.floor(idx/9)+1)/2
		local t = (idx%9 + 1)/2
		return d,t
	end

	function check_criteria_set(fizzy_table, criteria_set, ignore_dt_index)
		-- Are there enough finds to cover the counts in the criteria_set?
		local all_spots_covered = {}
		local required_criteria = 0
		for _, criteria in ipairs(criteria_set) do
			all_spots_covered = array_union(all_spots_covered, criteria.dt_spots)
			required_criteria = required_criteria + criteria.count
		end
		if ignore_dt_index ~= nil then
			local ignore_index = find_in_list(ignore_dt_index, all_spots_covered)
			if (ignore_index > 0) then
				table.remove(all_spots_covered, ignore_index)
			end
		end
	
		local result = {ok=(#all_spots_covered >= required_criteria), had=#all_spots_covered, req=required_criteria}
		return result;
	end
		
	function check_criteria_sets(fizzy_table, criteria_sets, ignore_dt_index, initial_check)
	
		-- In the initial check with pruning, you just need to find one of each leaf criteria to pass.
		-- In subsequent checks (with or without pruning), you need all checks to pass.
		local failures = {}
		local successes = {}
		local result = true
	
		for _,  criteria_set in ipairs(criteria_sets) do
			local fizzy_index = criteria_set.fizzy_index
	
			local check_result = check_criteria_set(fizzy_table, criteria_set, ignore_dt_index)
			if (not check_result.ok) then
				result = false
				local failure_line = ("Criteria: ")
				for i, criteria in ipairs(criteria_set) do
					failure_line = failure_line .. ((i>1 and " AND " or "") .. criteria_as_string(criteria))
				end
				failure_line = failure_line .. (" had " .. check_result.had .. " DTs, but needed " .. check_result.req .. " DTs (FAIL)")
				table.insert(failures, {msg=failure_line, fizzy_index=fizzy_index})
	
				-- If this is the initial check, then keep going and find them all.
				if not initial_check then
					break
				end
			else
				table.insert(successes, {msg=pass_line, fizzy_index=fizzy_index})
			end
		end
	
		local solution = {ok=result, failures=failures, successes=successes}
		return solution
	end
	
	function fill_fizzies(fizzy_table)
	
		local solution = { ok = true}
	
		-- Create all permutaions the criteria 'sets' in all fizzies.
		for fizzy_index, fizzy_entry in ipairs(fizzy_defs) do
			local criteria_set = {}
			for _, criteria in ipairs(fizzy_entry.criteria) do
				if not fizzy_entry.use_pruning or not (criteria.prune or false) then
					table.insert(criteria_set, criteria)
				end
			end
			criteria_set.fizzy_index = fizzy_index
			criteria_set.fizzy_def = fizzy_defs[fizzy_index]
	
			local req_size = fizzy_entry.criteria_required or #fizzy_entry.criteria
	
			if fizzy_entry.use_pruning and #criteria_set < req_size then
				table.insert(solution, {ok=false, results={"You didn't satisfy enough individual criterias to pass this fizzy challenge."}})
			else
				local fizzy_solution = {}
				foreach_combination_until(criteria_set, req_size,
					function (criteria_set)
						criteria_set.fizzy_index = fizzy_index
						fizzy_solution = find_solution_with_criteria_set(fizzy_table, criteria_set)
						return not fizzy_solution.ok
					end
				)
	
				solution.ok = solution.ok and fizzy_solution.ok
				table.insert(solution, fizzy_solution)
			end
		end
	
		return solution
	end
	
	function find_solution_with_criteria_set(fizzy_table, criteria_set)
	
		-- Create all combinations of the input criteria set (including the full set)
		local criteria_sets = {}
		for set_size=1, #criteria_set do
			local new_combos = get_all_combinations(criteria_set, set_size)
			for _, combo in ipairs(new_combos) do
				combo.fizzy_index = criteria_set.fizzy_index
				combo.fizzy_def = criteria_set.fizzy_def
			end
			criteria_sets = array_join(criteria_sets, new_combos)
		end
	
		-- Check all the sets, to see if it's even possible.
		local first_check = check_criteria_sets(fizzy_table, criteria_sets, 0, true)
		local solution = {ok = first_check.ok }
	
		DebugPrint("The first pass for fizzy : " .. (solution.ok and "PASS" or "FAIL") .. "\n")
	
		if not solution.ok then
			solution.results = first_check.failures
			return solution
		end
	
		-- If we know we can get a solution, go find it. Iterate over all criteria, over all DT spots that its satisfied on, and choose each possible find.
		-- And then see if there is still a possible solution after that. If so, then we must be able to choose that one. Otherwise, choose another.
	
		-- Figure out which criteria are in the final criteria set or not.
		for _, criteria in ipairs(criteria_list) do
			criteria.in_leaf = false
		end
		for _, criteria in ipairs(criteria_set) do
			criteria.in_leaf = true
		end

		-- Inverse sort by the number of DT spots that criteria pass. 
		table.sort(criteria_list, function(c1, c2) return #c1.dt_spots < #c2.dt_spots end)
	
		-- Now go over all the criteria in this fizzy.
		for _, criteria in ipairs(criteria_list) do
	
			if criteria.fizzy_index == criteria_set.fizzy_index and criteria.in_leaf then
	
				DebugPrint(criteria_as_string(criteria) .. " needed = " .. criteria.count .. "\n")
				-- Make sure we need to find something for this criteria.
				while criteria.count > 0 do
	
					-- Iterate over all the DTs this criteria has a find for.
					local found_dt_solution = false
					local spot_index=1
					while spot_index <= #criteria.dt_spots do
						local dt_index=criteria.dt_spots[spot_index]
						local d, t = revdtidx(dt_index)
	
						if solution ~= nil and solution[dt_index] ~= nil then
							error("Solution " .. criteria.fizzy_index .. " " .. d.."/"..t .. " had " .. dump(solution[dt_index]) .. " but it is included in criteria " .. dump(criteria) .. "\n")
						end
						-- Make sure we don't have something at this spot alreadd.
						if solution == nil or solution[dt_index] == nil then
	
							if #fizzy_table[dt_index][criteria.criteria_index] == 0 then
								error("Script indicated that criteria " .. criteria.criteria_index .. " satisfied DT " .. d.."/"..t .. ", but there were no finds." )
							end
	
							for _, find in ipairs(fizzy_table[dt_index][criteria.criteria_index]) do
	
								-- Choose this find for this fizzy's DT.
								solution = solution or {}
								solution[dt_index] = find
								solution[dt_index].chosen_criteria = solution[dt_index].chosen_criteria or {}
								solution[dt_index].chosen_criteria[criteria.fizzy_index] = criteria
	
								-- Now, adjust. We need one less all the criteria this find satisfied. Also, remove the DT spot from all the criteria.
								for _, criteria_update in ipairs(criteria_list) do
									if find_in_list(criteria_update.criteria_index, find.satisfied_criteria) > 0 then
										if solution[dt_index].chosen_criteria[criteria.fizzy_index] == criteria_update then
											criteria_update.count = criteria_update.count - 1
										end
									end
								end
	
								local check_result = check_criteria_sets(fizzy_table, criteria_sets, dt_index, false)
								if check_result.ok then
									-- It passed. We can definitely choose this find for this DT spot, so remove the DT spot from all criteria in this fizzy, and go to the next one.
									for _, update_criteria in ipairs(criteria_list) do
										if update_criteria.fizzy_index == criteria.fizzy_index then
											local dt_index_index = find_in_list(dt_index, update_criteria.dt_spots)
											while (dt_index_index >= 1) do
												table.remove(update_criteria.dt_spots, dt_index_index)
												if #update_criteria.dt_spots < update_criteria.count and update_criteria.in_leaf then
													error("Script error. We're removing DT spot " .. d.."/"..t .." from " .. criteria_as_string(update_criteria) .. " but we need all of them. (" .. #update_criteria.dt_spots .. " vs " .. update_criteria.count .. ")" ..
														dump(update_criteria) .. "\n\n " .. dump(criteria_sets) .. "\n")
												end
												dt_index_index = find_in_list(dt_index, update_criteria.dt_spots)
											end
										end
									end
									found_dt_solution = true
									DebugPrint("Chose " .. find.gccode .. " for DT " .. d.."/" ..t.. " (criteria: " .. criteria.criteria_index .. ")\n")
									break
								else
									-- Nope, don't pass anymore. Can't use this find. Increase the find counts again.
									DebugPrint("Can't choose " .. find.gccode .. " for DT  " .. d.."/"..t .. " because " .. check_result.failures[1].msg .. "\n")
									for _, criteria_update in ipairs(criteria_list) do
										if find_in_list(criteria_update.criteria_index, find.satisfied_criteria) > 0 then
											if solution[dt_index].chosen_criteria[criteria.fizzy_index] == criteria_update then
												criteria_update.count = criteria_update.count + 1
											end
										end
									end
									solution[dt_index] = nil
	
								end
							end
						end
	
						-- If we found a find for this DT, then break out of the loop. Otherwise, go to the next DT.
						if found_dt_solution then
							spot_index=1
							break
						else
							spot_index = spot_index+1
						end
					end
	
					if criteria.count > 0 and spot_index > #criteria.dt_spots then
						DebugPrint("Criteria " .. dump(criteria).." error.\n")
						DebugPrint("Solution: " .. dump(solution) .. "\n")
						error("Script error. We could not find a suitable cache for this criteria, but the initial test indicated there was one.")
					end
				end
	
				DebugPrint("Criteria " .. criteria.criteria_index .. " satisfied.\n")
			end
		end
	
		return solution
	end
		
	-- Calculate the required number of fizzy spots filled, based on the sum of the criteria
	-- Also generate ALL the extra fields that we will required for all fizzy defs, so we can call GetFinds only once.
	local criteria_index = 1
	for fizzy_index, fizzy_entry in ipairs(fizzy_defs) do

		fizzy_entry.use_pruning = fizzy_entry.use_pruning or fizzy_entry.criteria_required ~= nil
		fizzy_entry.fizzy_index = fizzy_index

		for _, fizzy_criteria in ipairs(fizzy_entry.criteria) do
			fizzy_criteria.fizzy_index = fizzy_index
			fizzy_criteria.criteria_index = criteria_index
			fizzy_criteria.dt_spots = {} -- filled in later
			criteria_index = criteria_index + 1
			for _, fi in ipairs(fields_in_criteria(fizzy_criteria) or {}) do
				insert_into_list_if_unique(fi, fields_required)
			end
			table.insert(criteria_list, fizzy_criteria)
		end
	end

	DebugPrint("Fields: " .. dump(fields_required) .. "\n")
	DebugPrint("Filter: " .. dump(filter) .. "\n")

	-- Get data for as few fields as possible to reduce memory usage. A full list of fields can be found at http://project-gc.com/doxygen/lua-sandbox/classPGC__LUA__Sandbox.html#a8b8f58ee20469917a29dc7a7f751d9ea
	DebugPrint(dump(conf.transforms).."\n")	
	local finds = GetCombinedFinds(profileId, { lookup_cache=conf.lookup_cache,transforms=transforms, fields=fields_required, order = 'OLDESTFIRST', filter = filter })

	--DebugPrint("fizzy defs: " .. dump(criteria_list) .. "\n")
	DebugPrint("fields: " .. dump(fields_required) .. "\n")

	-- Group all the finds into their fizzy grid spot, by the criteria in each fizzy that they satisfy.
	local fizzy_table = {}
	for _, find in ipairs(finds) do
		local dt_index = dtidx(find.difficulty, find.terrain)
		find.dt_index = dt_index
		fizzy_table[dt_index] = fizzy_table[dt_index] or {}
		for _, fizzy_entry in ipairs(fizzy_defs) do
			for _, criteria in ipairs(fizzy_entry.criteria) do
				fizzy_table[dt_index][criteria.criteria_index] = fizzy_table[dt_index][criteria.criteria_index] or {}

				-- Put it in the list of the satisfying criteria, AND add the criteria index to the find itself.
				if find_satisfies_criteria(find, criteria) then
					insert_into_list_if_unique(dt_index, criteria.dt_spots)
					table.insert(fizzy_table[dt_index][criteria.criteria_index], find)
					find.satisfied_criteria = find.satisfied_criteria or {}
					table.insert(find.satisfied_criteria, criteria.criteria_index)
				end
			end
		end
	end

	-- Now, for faster finding, sort the finds with the least satisfied criteria first. (If it has less satisfied criteria, then we're more likely to get a solution faster.
	for dt_index = 1, 81 do
		for _, criteria_finds in ipairs(fizzy_table[dt_index] or {}) do
			table.sort(criteria_finds, function(f1,f2) return #f1.satisfied_criteria < #f2.satisfied_criteria end)
		end
	end

	-- ALSO, sort the DTs by the criterias by the number of DT squares that most have possible finds for them.
	table.sort(criteria_list, function (cl1, cl2) return #cl1.dt_spots > #cl2.dt_spots end )

	-- If a criteria does not have enough DT spots to possibly pass, mark that.
	for _, criteria in ipairs(criteria_list) do
		if #criteria.dt_spots < criteria.count and criteria.count < (fizzy_defs[criteria.fizzy_index].required_criteria or math.huge) then
			--DebugPrint(criteria_as_string(criteria) .. " only has " .. #criteria.dt_spots .. ". Pruning, as it may not be required, and it cannot be satisfied.\n")
			criteria.prune = true
		end
	end

	-- Now actually try to fillllll the fizzziiies!
	local best_solution = fill_fizzies(fizzy_table)

	-- Sort the criteria list BACK into their correct order (for easier outputting)
	--table.sort(criteria_list, function (cl1, cl2) return cl1.criteria_index < cl1.criteria_index end )

	DebugPrint(dump(best_solution).."\n\n")

	local ok = best_solution.ok
	local html = {}
	local log = {}

	-- Print the fizzies to HTML
	for fizzy_index, fizzy_def in ipairs(fizzy_defs) do
		local solution_html = {}
		local all_criteria_html = {}

		local pass_fail_img = "<img src='https://cdn2.project-gc.com/images/" .. (best_solution[fizzy_index].ok and 'check16.png' or 'stop_16.png') .. "'/>"
		table.insert(html, "<b>" .. pass_fail_img .. " " .. fizzy_def.name .. "</b><br/><br/>")

		local header_line = "<table class=\""..g_table_class.."\"><tr><th width='5%'></td>"
		for t = 1.0, 5.0, 0.5 do
			header_line = header_line.."<th width='10%'><p align='center'><b>"..string.format("%.1f",t).."</p></b></th>"
		end
		header_line = header_line.."</tr>"

		table.insert(all_criteria_html, "Complete find table for " .. fizzy_def.name )
		table.insert(all_criteria_html, header_line)
		table.insert(solution_html, header_line)

		-- Now build the rest of the table.
		for d = 1.0, 5.0, 0.5 do
			table.insert(all_criteria_html, "<tr><td><b>"..string.format("%.1f",d).."</b></td>")
			table.insert(solution_html, "<tr><td><b>"..string.format("%.1f",d).."</b></td>")
			for t = 1.0, 5.0, 0.5 do
				local dt_index = dtidx(d, t)

				-- all passed criteria
				local passed_criteria_line = "<td><table class=\""..g_table_class.."\"><tr>"
				local per_row = math.max(4, math.floor(math.sqrt(#fizzy_def.criteria)))
				for criteriaidx, criteria in ipairs(fizzy_def.criteria) do
					local criteria_passed = fizzy_table[dt_index] and #fizzy_table[dt_index][criteria.criteria_index] > 0 or false

					passed_criteria_line = passed_criteria_line.."<td>"
					passed_criteria_line = passed_criteria_line .. get_html_for_criteria_struct(criteria_passed, criteria)
					passed_criteria_line = passed_criteria_line .. "</td>"
					if criteriaidx%per_row == 0 then
						passed_criteria_line = passed_criteria_line.."</tr><tr>"
					end
				end
				passed_criteria_line = passed_criteria_line .. "</tr></table>"
				passed_criteria_line = passed_criteria_line .. "</td>"
				table.insert(all_criteria_html, passed_criteria_line)

				-- solution
				local dt_line = "<td>"
				if best_solution[fizzy_index] and best_solution[fizzy_index][dt_index] ~= nil then
					local find = best_solution[fizzy_index][dt_index]
					dt_line = dt_line .. get_html_for_criteria_struct(true, find.chosen_criteria[fizzy_index]) .. " - "
					dt_line = dt_line .. "<a href='http://coord.info/" .. find.gccode .. "'>" .. find.gccode.."</a>"
					if verbose_log  then
						table.insert(log, criteria_as_string(find.chosen_criteria[fizzy_index]) .. ": " .. string.format("%.1f", d) .. "/" .. string.format("%.1f", t) .. " " .. find.gccode .. ": " .. find.visitdate)
					end
				else
					dt_line = dt_line .. "<font bg='#FFFF00'>N/A</font>"
				end
				dt_line = dt_line .. "</td>"
				table.insert(solution_html, dt_line)

			end
			table.insert(all_criteria_html, "</tr>")
			table.insert(solution_html, "</tr>")
		end
		table.insert(all_criteria_html,"</table>")
		table.insert(solution_html,"</table>")

		-- We have now built both tables.
		if best_solution[fizzy_index].ok then
			html = array_join(html, solution_html)
		else
			for _, fail_line in ipairs(best_solution[fizzy_index].results) do
				table.insert(html, fail_line.msg)
			end
		end

		if (not best_solution[fizzy_index].ok) or full_table_on_pass then
			html = array_join(html, all_criteria_html)
		end
	end


	local shtml = table.concat(html, "<br/>")
	local slog = table.concat(log, "\n")
	local result = {ok=ok, log="", slog=slog, html="", shtml=shtml}

	return result
end
-----------------------------------------------------
-- Finds caches that are a certain distance apart from any other cache.
function c_remote(conf)
	
	local point_table = conf.points 													-- array of points structure, must be sorted by distance {distance, desc, points}
	local min_distance = (point_table ~= nil and #point_table > 0) and point_table[1].distance or 
		(conf.min_distance or error("Must supply 'min_distance', or 'point_table'"))	-- minimum distance in meters, to get any points for a cache.
	local limit = conf.limit or 1 														-- number of points required to pass
	local break_on_limit = conf.break_on_limit or false									-- whether to stop processing once the 'limit' is reached, or find ALL distant caches
	local remote_when_found = conf.remote_when_found or false							-- only caches that were remote *when* you found them count
	local ignore_events_for_proximity = conf.ignore_events_for_proximity or false		-- whether to consider events as 'close', even if they aren't archived.
	local ignore_logged_after_archived = conf.ignore_logged_after_archived or false		-- if you log something after it was archived, does it count as remote (if it was remote?)
	local print_fields =conf.print_fields or {'gccode', 'visitdate', 'cache_name', 'closest_gccode', 'closest_dist'}		-- fields to print, when printing distant caches.
	local remote_filter = FilterFromConfig(conf.remote_filter or {}) 					-- Used to filter out caches that could be considered 'remote'. Eg. to limit to only caches of a specific type.

	local transforms = conf.transforms													-- standard transforms
	local filter = FilterFromConfig(conf)												-- standard filter
	local generate_map = conf.generate_map or false										-- Whether to generate a map showing the caches.
	
	if point_table == nil then
		point_table = {}
		table.insert(point_table,{desc="Over "..(min_distance/1000).."km", points=1, distance=min_distance})
	end

	local needed_fields = {'gccode', 'latitude', 'longitude', 'archived','owner_id','last_archive_date','visitdate','last_publish_date'}
	for _,pf in ipairs(print_fields) do
		insert_into_list_if_unique(pf, needed_fields)
	end

	transforms = transforms or {}
	table.insert(transforms, {func='type_group_events'})

	local finds = GetCombinedFinds(profileId, { 
		lookup_cache=conf.lookup_cache,transforms=transforms, 
		fields = needed_fields, order = 'OLDESTFIRST', filter = filter })

	function should_consider_other_find(find, other_find)

		local why_not = "Should consider"

		-- if last_archive_date is nil, which, it can be... just say it's the same day as the visitdate. Presumably you didn't find it when it was archived.
		if remote_when_found and tonumber(other_find.archived) ~= 0 and other_find.last_archive_date == nil then
			other_find.last_archive_date = other_find.visitdate

			-- if that's ALSO nil, then say it was the last date it was found, because presumably somebody didn't find it after it was archived. And if they did, well then it was still available to be found.
			if other_find.last_archive_date == nil then
				other_find.last_archive_date = other_find.last_find_date
			end
			if other_find.last_archive_date == nil then
				other_find.last_archive_date = find.visitdate
			end
		end

		local valid_check = true
		if tonumber(other_find.archived) ~= 0 then
			if remote_when_found then
				valid_check = other_find.last_archive_date > find.visitdate and other_find.last_publish_date <= find.visitdate
				if not valid_check then
					why_not = "was archived on " .. other_find.last_archive_date .. " before you visited (on "..find.visitdate..")."
				end
			else
				-- other is archived now, and remote_when_found = false, so this one doesn't get checked
				valid_check = false 
				if not valid_check then
					why_not = other_find.gccode .. " is archived now."
				end
			end
		elseif remote_when_found then
			-- other was published after we found it, so it shouldn't be considered
			valid_check = other_find.last_publish_date <= find.visitdate
			if not valid_check then
				why_not = " was published on " .. other_find.last_publish_date .. " after you visited (on "..find.visitdate..")."
			end
		end

		-- If we're just ignoring events and it is an event then return false.
		if ignore_events_for_proximity and other_find.type_group_events=="Events" then
			valid_check = false
			if not valid_check then
				why_not = other_find.gccode .. " is an event, and they are being ignored for proximity."
			end
		end

		return valid_check, why_not
	end

	function filter_distance_finds(finds, min_distance)

		DebugPrint("Attempting to filter finds, which are " .. min_distance .. "m from each other, from all your finds.\n")

		local distant_finds = {}
		
		-- First, sort by longitude. If a cache is further in longitude along the same latitude, then no other caches can possibly be close enough to it.
		table.sort(finds, function (f1, f2) return f1.longitude < f2.longitude end)

		for i, find in ipairs(finds) do

			-- If we're not allowed found-when-archived caches, eliminate those now. 
			-- Note: sometimes last_archive_date is missing, because there is no archive log... in that case, assume the user found it when it wasn't archived.
			-- Usually this is a result of HQ locking the cache for some reason, and happens only in rare cases.
			local archive_check = true
			if ignore_logged_after_archived and (tonumber(find.archived) ~= 0) and find.last_archive_date ~= nil and (find.visitdate > find.last_archive_date) then
				DebugPrint(find.gccode .. ": was found after it was archived. Ignoring.\n")
				archive_check = false
			end

			-- NOTE: not really using using_lookup_cache, but this way it does all the filtering that the built-in database would do.
			if archive_check and not find_fails_filter(remote_filter, find, true) then

				local still_distant = true
				for j = i+1, #finds do
					local other_find = finds[j]
					local archive_check  = should_consider_other_find(find, other_find)
					if (archive_check and PGC.DistanceHaversine(find.latitude, find.longitude, other_find.latitude, other_find.longitude) < min_distance) then
						still_distant = false
						break
					elseif (PGC.DistanceHaversine(find.latitude, find.longitude, find.latitude, other_find.longitude) >= min_distance ) then
						-- Check if at the same latitude, even the longitude would be too far. If it is, this is a distance find.
						break
					end
				end

				-- NOTE: Need to go both ways, as a close cache might have a lower longitude.
				if (still_distant) then
					for j = i-1, 1,-1 do
						local other_find = finds[j]
						local archive_check  = should_consider_other_find(find, other_find)
						if (archive_check and PGC.DistanceHaversine(find.latitude, find.longitude, other_find.latitude, other_find.longitude) < min_distance) then
							still_distant = false
							break
						elseif (PGC.DistanceHaversine(find.latitude, find.longitude, find.latitude, other_find.longitude) >= min_distance) then
							-- Check if at the same latitude, even the longitude would be too far. If it is, this is a distance find.
							break
						end
					end
				end

				if (still_distant) then
					-- It's likely that hiders hide caches "near" to their other hides. So, get the suspected distant cache's owner, and check against their other hides.
					local excluded_owner_hides = false
					if find.owner_id ~= nil then
						local owner_hides = PGC.GetHides(find.owner_id, {fields={'gccode','latitude', 'longitude', 'archived','last_archive_date','last_find_date','last_publish_date'}})
						if type(owner_hides) == 'table' then
							excluded_owner_hides = true
							for _, oh in ipairs(owner_hides) do
								if oh.gccode ~= find.gccode and should_consider_other_find(find, oh) then
									local oh_distance = PGC.DistanceHaversine(find.latitude, find.longitude, oh.latitude, oh.longitude)
									if  oh_distance < min_distance then
										DebugPrint("Removed " .. find.gccode .. " from consideration because same owners cache " .. oh.gccode .. " is only " .. oh_distance .. " away\n" )
										still_distant = false
										break
									end
								end
							end
						end
					end

					if not excluded_owner_hides then
						DebugPrint("Couldn't GetHides for owner " .. tostring(find.owner_id) .. " they must have privacy settings on.\n")
					end

					if still_distant then
						find.closest_dist = math.huge -- 'unknown'
						table.insert(distant_finds, find)
						DebugPrint("Added " .. find.gccode .. " to (potentially) distant finds.\n")
					end
				end
			end
		end

		return distant_finds
	end


	function determine_points(distant_finds, point_criteria, limit)

		-- NOTE: Doing the calculation this way can only handle a certain number of distance caches in the 60 second time limit. HOPEFULLY,
		-- If you analyze 1000 caches, then you'll pass the challenge in the first 1000, otherwise, the test is inconclusive.    
		local result = 
		{
			total = 0,
			finds = {},
			criterias = {},
			truncated = false
		}

		-- We need a really small distance for the first check... because it might just be that you found one cache that IS close to another on a roadtrip or something.
		-- If we use a huge initial radius, this takes the database a long time to figure out. A small one, will be much faster. If that passes, we can drill down further.
		local distance_checks = {}
		local dist = 1000
		while (dist < 2000000) do
			table.insert(distance_checks,dist)
			dist = dist * 2
		end

		DebugPrint("Current time: " .. os.time().."\n")

		for f = 1, #distant_finds do

			-- If you get to 55 seconds of processing, truncate the results.
			if (os.difftime(os.time(), start_time) > 55) then 
				result.truncated = true
				break
			end
			
			-- Break on limit acheived (if desired)
			if break_on_limit and result.total >= limit then
				break
			end

			find = distant_finds[f]
			for i, max_distance in ipairs(distance_checks) do

				-- Query favourites... with zero favourite points.
				-- If there aren't *any* within the required radius, then this is probably an archived cache, with no others around it.
				-- If there is one, make sure it isn't this cache.
				-- If there are two (or more), that pass the archive check, then the criteria fails.
				local caches = PGC.GetFavorites('points', 
					{
						limit=100, requiredFP=0,
						filter={
							excludeArchived=false, excludeDisabled=false,
							radius={distance=max_distance, latitude=find.latitude, longitude=find.longitude}}
					});

				if #caches == 0 or (#caches == 1 and caches[1].gccode == find.gccode) then
					DebugPrint("find: " .. find.gccode .. " was not within " .. max_distance .. " of any other cache.\n")
				else
					for _, close_cache in ipairs(caches) do
						if close_cache.gccode ~= find.gccode then
							local dist = PGC.DistanceHaversine(find.latitude, find.longitude, close_cache.latitude, close_cache.longitude)
							if (dist < find.closest_dist) then
								-- It may be that this cache shouldn't be 'considered'. To know that, we actually need more info, because GetFavorites doesn't give us much.
								local hides = PGC.GetHides(close_cache.owner_id, {fields={'gccode','archived','last_archive_date','last_publish_date','type'}})
								if type(hides) == 'table' then
									for _,h in ipairs(hides) do
										if h.gccode == close_cache.gccode then
											close_cache = table_join(h,close_cache)
											break
										end
									end
								else
									DebugPrint("Couldn't GetHides for owner " .. close_cache.owner_id .. " they must have privacy settings on.\n")
								end

								consider_other_find, why_not = should_consider_other_find(find, close_cache)
								if consider_other_find then
									DebugPrint(find.gccode .. ": ".. close_cache.gccode .. " was " .. dist .. " away (min="..max_distance.."), and thus stops it from being pursued.\n")
									find.closest_cache = close_cache
									find.closest_dist = dist
								else
									find.not_considered = find.not_considered or {}
									if find_in_list_by_field(close_cache, 'gccode',find.not_considered) < 1 then
										table.insert(find.not_considered, table_join(TableCopy(close_cache),{why_not=why_not}))
									end
								end
							end
						end
					end

					-- There were other caches within the radius, but none of them were considered.
					if find.closest_cache ~= nil then
						-- We found the geocache that was closest, so we can stop now.
						break
					end
				end
			end
	
			-- Determine how many points it's worth
			if (find.closest_cache ~= nil) then
				local best_passed_criteria 
				for _, criteria in ipairs(point_criteria) do
					if find.closest_dist < criteria.distance then
						break
					else
						best_passed_criteria = criteria
					end
				end

				if best_passed_criteria ~= nil then
					result.total = result.total + best_passed_criteria.points
					table.insert(result.finds, find)
					table.insert(result.criterias, best_passed_criteria)
					DebugPrint("find: " .. find.gccode .. " gets " ..  best_passed_criteria.points .. " point(s), closest considered cache " .. find.closest_cache.gccode .. " ("..find.closest_dist..")\n")
					if find.not_considered and #find.not_considered > 0 then
						DebugPrint("Not considered:\n"..PrintFindsText(find.not_considered,#find.not_considered,{'gccode','why_not'}).."\n")
					end
				end
			end
		end

		-- Sort the finds by the furthest distance to others
		table.sort(result.finds, function(f1,f2) return f1.closest_dist >  f2.closest_dist end)	

		-- If there are finds without closest_cache, put in a BS one one, or else PrintFinds will have problems.
		for _, r in ipairs(result.finds) do
			r.closest_cache = r.closest_cache or {gccode='unknown'}
			r.closest_gccode = r.closest_cache.gccode
		end
		return result
	end
	

	local distant_finds = filter_distance_finds(finds, min_distance)
	DebugPrint("There are " .. #distant_finds .. " finds of yours that are at least " .. min_distance .. "m from all other (non-archived) finds. Analyzing these for points.\n")

	local point_result = determine_points(distant_finds, point_table, limit)

	local res = {}
	local truncated_message = point_result.truncated and "<h3><b>NOTE: Processing distant finds is time consuming. Not all your finds were processed, so you may have achieved more points than listed.</b><h3>" or ""
	res.ok = point_result.total >= limit
	res.log = ""
	res.html = ""
	res.slog = "You found a total of " .. point_result.total .. " out of a required " .. limit
	res.slog = res.slog .. PrintFindsText(point_result.finds, #point_result.finds, print_fields)
	res.shtml = "You found a total of " .. point_result.total .. " out of a required " .. limit .. ". " .. truncated_message
	res.shtml = res.shtml .. PrintFindsHtml(point_result.finds, #point_result.finds, print_fields)
	res.caches = point_result.finds

	if generate_map then
		local map = { caches = {}, polygons = {}, polygonLines = {}, circles = {}, correctedCoordinatesInUse = false } 
		for _, mapcache in ipairs(res.caches) do
			table.insert(map.caches, mapcache.gccode)			
			if mapcache.closest_gccode ~= nil and  mapcache.closest_gccode ~= 'unknown' then
				table.insert(map.circles,{ latitude = mapcache.latitude, longitude = mapcache.longitude, radius = mapcache.closest_dist, 
					tooltip = tip, color = "green", weight = 1, opacity = 0.8, fillOpacity = 0.05 })
				table.insert(map.caches, mapcache.closest_gccode)
				table.insert(map.polygonLines, { polygonLine={{mapcache.latitude,mapcache.longitude},{mapcache.closest_cache.latitude,mapcache.closest_cache.longitude}},
					color = "red", weight = 1.2, opacity = 0.75})
			end
		end
		res.map = map
	end

	return res
end

-----------------------------------------------------
-- Find N groups of that each have M finds with a unique value for a particular field. Across some subset of groups N, you must have a total of P unique values for the field (or the field specified by z).
function c_unique_groups(conf)

	local x_group  = conf.x or error("Must supply 'x' (the field used to create groups)")
	local y_group  = conf.y or error("Must supply 'y' (the field within a group that needs to be unique)")
	local z_group  = conf.z or y_group -- the group that must have P unique values. Defaults to y, but could be some other field
	local groups   = conf.groups or error("Must supply 'groups' (number of passing groups required)")
	local limit    = conf.limit or error("Must supply 'limit' (number of entries required in a group)")
	local unique   = conf.unique or error("Must supply 'unique' (number of unique values of 'y' over all groups of 'x')")
	local fields   = {'gccode', 'cache_name'}
	local filter   = FilterFromConfig(conf)

	insert_into_list_if_unique(x_group, fields)
	insert_into_list_if_unique(y_group, fields)
	insert_into_list_if_unique(z_group, fields)

	local print_fields = conf.print_fields or fields

	local finds = GetCombinedFinds(profileId, { transforms=g_conf.transforms,fields = fields, order = 'OLDESTFIRST', filter = filter })

	-- Group all the finds, removing from x groups any duplicate values of y.
	local finds_by_x_y_type = {}
	for i=1,#finds do
		local find = finds[i]
		local x = find[x_group]
		local y = find[y_group]
		if x == nil or y == nil then
			DebugPrint(find.gccode .. "(skipping): "..x_group.." = " .. dump(x) .. ", " .. y_group .. " = " .. dump(y) .. "\n")
		else
			finds_by_x_y_type[x] = finds_by_x_y_type[x] or {}
			finds_by_x_y_type[x][y] = finds_by_x_y_type[x][y] or {}
			if find_in_list_by_field(find, y, finds_by_x_y_type[x][y]) <= 0 then
				table.insert(finds_by_x_y_type[x][y], find)
			end
		end
	end

	-- now eliminate any groups which don't have at least the minimum number
	local eliminate_groups = {}
	for key,entry in pairs(finds_by_x_y_type) do
		local y_count = 0
		for _,finds in pairs(entry) do
			y_count = y_count + 1
		end
		if y_count < limit then
			finds_by_x_y_type[key] = nil
		end
	end

	local x_group_list = {}
	for key,entry in spairs(finds_by_x_y_type) do
		local group_list = {}
		for group_key,group_entry in spairs(finds_by_x_y_type[key]) do
			table.insert(group_list,group_entry[1])
		end
		table.insert(x_group_list, group_list)
	end

	-- Calculate the number of unique values of 'z', within each group.
	local seen_unique_z = {}
	local all_z_values = {}
	for _, group in ipairs(x_group_list) do
		local unique_z = {}
		group.unique_z = 0
		for _,cache in ipairs(group) do
			if unique_z[cache[z_group]] == nil then
				group.unique_z = group.unique_z + 1
				unique_z[cache[z_group]] = true
			end
		end

		-- If this exact set of unique_zs has been seen before, lower the priority of this group.
		local total_key = ""
		for key,_ in spairs(unique_z) do
			total_key = total_key..key
			insert_into_list_if_unique(key,all_z_values)
		end
		DebugPrint("Group:" .. group[1][x_group].." key = "..total_key.."\n")
		seen_unique_z[total_key] = (seen_unique_z[total_key] or 0) + 1
		group.priority_z = seen_unique_z[total_key]
		group.total_key = total_key
	end

	-- If there aren't enough z values, then don't try to permute, because we may timeout.
	local enough_z = #all_z_values >= unique 
	DebugPrint("Total unique z values:" .. #all_z_values .. " ("..table.concat(all_z_values," ")..")\n")
	if not enough_z then
		local res = {}
		res.ok = false
		res.log = ""
		res.html= ""
		res.slog = "You have found " .. #x_group_list .. " groups of " .. x_group .. " with at least " .. limit .. " entries. However, there are only " .. #all_z_values .. " unique values of " .. z_group .. ", out of a required " .. unique 
		res.shtml = res.slog
		return res
	end

	-- Put the bigger groups at the front, as they are more likely to produce permutations that pass
	table.sort(x_group_list, function(gl1, gl2) return gl1.priority_z < gl2.priority_z end)

	-- If something has non-one priority, it means that something else completely duplicates it. It should be able to be removed from consideration.
	local final_x_group_list = {}
	for _, xg in ipairs(x_group_list) do
		if #final_x_group_list < groups or xg.priority_z == 1 then
			table.insert(final_x_group_list, xg)
		end
	end
	x_group_list = final_x_group_list

	-- Print out ALL the X groups, and the Y groups
	if g_conf.debug then
		for _, group in ipairs(x_group_list) do
			DebugPrint("Group: " .. group[1][x_group] .. " (unique_z="..group.unique_z..", priority="..group.priority_z..") - ")
			for _,cache in ipairs(group) do
				DebugPrint(cache[y_group] .. ", ")
			end
			DebugPrint("\n")
		end
	end

	-- now, permute by x_group and limit of y values, to come up with a set of caches that have at least 'unique' number of values for y.
	local best_cache_set = {}
	local best_unique_count = 0
	foreach_combination_until(x_group_list, groups,
		function (group_set)

			-- This is a set of X groups. Now, permute each of the groups, check all these sets of groups, and see if there's something that satisfies the unique.
			local combo_sets = {}
			local index_choices = {}
			for _, group in ipairs(group_set) do
				local combo_set = get_all_combinations(group, limit)
				table.insert(combo_sets, combo_set)
				table.insert(index_choices, 1)
			end

			function check_combo_choice(combo_sets, index_choices)
				local unique_values = {}
				local unique_count = 0
				for combo_set_index, combo_index in ipairs(index_choices) do
					for _, cache in ipairs(combo_sets[combo_set_index][combo_index]) do
						if unique_values[cache[z_group]] == nil then
							unique_count = unique_count +1
							unique_values[cache[z_group]] = true
						end
					end
				end

				if unique_count > best_unique_count then
					DebugPrint("New best unique count ("..unique_count..") " .. dump(unique_values) .. "\n")
					best_unique_count = unique_count
					best_cache_set = {}
					for combo_set_index, combo_index in ipairs(index_choices) do
						table.insert(best_cache_set, combo_sets[combo_set_index][combo_index])
					end

					if unique_count >= unique then
						return true
					end
				end
				return false
			end

			function check_next_permutation(index)			
				index = index or 1
				for i = 1, #combo_sets[index] do
					index_choices[index] = i
					if index == groups then
						if check_combo_choice(combo_sets, index_choices) then
							return true
						end
					else
						if check_next_permutation(math.min(index+1, groups)) then
							return true
						end
					end
				end
				return false
			end

			local group_result = check_next_permutation()

			if g_conf.debug then
				DebugPrint("Checking x_group: ")
				for _, group in ipairs(group_set) do
					DebugPrint(group[1][x_group] .. ", ")
				end
				DebugPrint(dump(group_result) .. "\n")
			end

			-- return FALSE if you want to stop...
			return not group_result
		end)

	local ok= true
	local output = {}
	html = ""
	if #best_cache_set==0 then
		ok = false
		table.insert(output, "You have found " .. #x_group_list  .. " groups of " .. x_group .. " with at least " .. limit .. " entries. Must have at least " .. groups .. " to pass.")
	else	

		local unique_values = {}
		local unique_count = 0
		for _, cache_set in ipairs(best_cache_set or {}) do
			for _, find in ipairs(cache_set) do
				if (unique_values[find[z_group]]==nil) then
					unique_values[find[z_group]] = true
					unique_count = unique_count +1
				end
			end
		end

		ok = unique_count >= unique

		table.insert(output,"You have found " .. groups .. " groups of " .. x_group .. " with at least " .. limit .. " entries. Of these groups, there is a set that has " .. unique_count .. " values for " .. z_group .. ", out of a required " .. unique )
		if ok then
			table.insert(output,"There may be a group that contains more unique values, but stopped checking once a solution was found.\n")
		end
		local values_string = "These values are: **"
		local first = true
		for key,_ in pairs(unique_values) do
			values_string = values_string .. (first and "" or ", ") .. key
			first = false
		end
		values_string = values_string .. "**"
		table.insert(output, values_string)
		table.insert(output, "")
	end

	local shtml=table.concat(output,"<br/>"):gsub("%*%*(.-)%*%*","<b>%1</b>"):gsub("%[(GC.-)%]%((http.-)%)","<a href='%2'>%1</a>")
	local slog=table.concat(output,"\n")

	DebugPrint(dump(best_cache_set) .. "\n")
	for key, cache_set in ipairs(best_cache_set or {}) do
		shtml = shtml .. "<br/><b>" .. x_group .. ": " .. cache_set[1][x_group] .. "</b><br/>"
		slog = slog .. x_group .. ": " .. cache_set[1][x_group] .. "\n"
		shtml = shtml .. PrintFindsHtml(cache_set, #cache_set, print_fields) .. "<br/>"
		slog = slog .. PrintFindsText(cache_set, #cache_set, print_fields) .. "\n"
	end

	local log=""

	local res = {}
	res.ok = ok
	res.log = ""
	res.html= ""
	res.slog = slog
	res.shtml = shtml
	return res

end
