function c_venn(conf)

	-- We're setup to have A/B/C/AB/AC/BC/ABC (and optionally X for none groups). Must specify all (except X, or it's an error).
	error_if(conf.A == nil, "Must specify 'A' in conf.")
	error_if(conf.B == nil, "Must specify 'B' in conf.")
	error_if(conf.C == nil, "Must specify 'C' in conf.")
	error_if(conf.AB == nil, "Must specify 'AB' in conf.")
	error_if(conf.AC == nil, "Must specify 'AC' in conf.")
	error_if(conf.BC == nil, "Must specify 'BC' in conf.")
	error_if(conf.ABC == nil, "Must specify 'ABC' in conf.")

	-- Do the operations.
	local print_fields = conf.print_fields or conf.printFields or {"gccode", "cache_name"}
	local print_field_tags = conf.print_field_tags
	local resTable = {}
	resTable.A   = lookup(conf.A.func,conf.A.conf,conf.A.filter,conf.A.opt)
	resTable.B   = lookup(conf.B.func,conf.B.conf,conf.B.filter,conf.B.opt)
	resTable.C   = lookup(conf.C.func,conf.C.conf,conf.C.filter,conf.C.opt)
	resTable.AB  = lookup(conf.AB.func,conf.AB.conf,conf.AB.filter,conf.AB.opt)
	resTable.AC  = lookup(conf.AC.func,conf.AC.conf,conf.AC.filter,conf.AC.opt)
	resTable.BC  = lookup(conf.BC.func,conf.BC.conf,conf.BC.filter,conf.BC.opt)
	resTable.ABC = lookup(conf.ABC.func,conf.ABC.conf,conf.ABC.filter,conf.ABC.opt)
	resTable.X   = conf.X and lookup(conf.X.func,conf.X.conf,conf.X.filter,conf.X.opt) or nil

	local res = {}
	res.shtml = ""
	res.slog =  ""

	-- For now, assume that you must pass everything, including 'X', unless it was unspecified
	res.ok = true
	for result,entry in pairs(resTable) do
		res.ok = res.ok and entry.ok
	end

	local img_addr = conf.img_addr or "https://i.imgur.com/c2AtVS8.png"
	local img_w = 900
	local img_h = 860
	local spacing_w = 20
	local spacing_h = 20

	local location_01 = conf.A.title_pos or "20x4" 
	local location_02 = conf.B.title_pos or "8x36" 
	local location_03 = conf.C.title_pos or "35x36"
	local location_04 = conf.A.pos       or "18x9" 
	local location_05 = conf.B.pos       or "3x26" 
	local location_06 = conf.C.pos       or "27x26"
	local location_07 = conf.AB.pos      or "12x15" 
	local location_08 = conf.AC.pos      or "24x15" 
	local location_09 = conf.BC.pos      or "22x33"
	local location_10 = conf.ABC.pos     or "20x22" 
	local location_11 = (conf.X and conf.X.pos) or "3x9"

	local element_locations = {}
	local g_table_class_original = g_table_class	-- override table class, only for venn, and then put it back. 
	g_table_class = "table-condensed"
	element_locations[location_01]	= conf.A.title
	element_locations[location_02]	= conf.B.title
	element_locations[location_03]	= conf.C.title
	element_locations[location_04]	= resTable.A.ok and PrintFindsHtml(resTable.A.caches,1,print_fields,true,nil,print_field_tags) or "N/A"
	element_locations[location_05]	= resTable.B.ok and PrintFindsHtml(resTable.B.caches,1,print_fields,true,nil,print_field_tags) or "N/A"
	element_locations[location_06]	= resTable.C.ok and PrintFindsHtml(resTable.C.caches,1,print_fields,true,nil,print_field_tags) or "N/A"
	element_locations[location_07]	= resTable.AB.ok and PrintFindsHtml(resTable.AB.caches,1,print_fields,true,nil,print_field_tags) or "N/A"
	element_locations[location_08]	= resTable.AC.ok and PrintFindsHtml(resTable.AC.caches,1,print_fields,true,nil,print_field_tags) or "N/A"
	element_locations[location_09]	= resTable.BC.ok and PrintFindsHtml(resTable.BC.caches,1,print_fields,true,nil,print_field_tags) or "N/A"
	element_locations[location_10]	= resTable.ABC.ok and PrintFindsHtml(resTable.ABC.caches,1,print_fields,true,nil,print_field_tags) or "N/A"
	if resTable.X ~= nil then
		element_locations[location_11] = resTable.X.ok and PrintFindsHtml(resTable.X.caches,1,print_fields,true,nil,print_field_tags) or "N/A"
	end
	g_table_class = g_table_class_original

	local element_sizes = {}
	element_sizes[location_01] = conf.A.title_size or {1,1}
	element_sizes[location_02] = conf.B.title_size or {1,1}
	element_sizes[location_03] = conf.C.title_size or {1,1}
	element_sizes[location_04] = conf.A.size or {13,1}
	element_sizes[location_05] = conf.B.size or {13,1}
	element_sizes[location_06] = conf.C.size or {13,1}
	element_sizes[location_07] = conf.AB.size or {8,1}
	element_sizes[location_08] = conf.AC.size or {8,1}	
	element_sizes[location_09] = conf.BC.size or {11,1}	
	element_sizes[location_10] = conf.ABC.size or {11,1}	
	element_sizes[location_11] = (conf.X and conf.X.size) or {5,1} 

	local html = {}
	table.insert(html,"<table style='table-layout:fixed; background-image: url(\""..img_addr.."\"); background-size: 100% 100%; background-repeat: no-repeat; background-size: contain;'>")
	for row=1,img_h/spacing_h do
		table.insert(html,"<tr style='height:"..spacing_h.."px;max-height:"..spacing_h.."px;'>")
		for col=1,img_w/spacing_w do
			local this_location = col.."x"..row
			if element_locations[this_location] ~= nil then
				local colspan = element_sizes[this_location][1]
				local rowspan = element_sizes[this_location][2]
				local td_w = spacing_w * colspan
				local td_h = spacing_h * rowspan
				table.insert(html,"<td style='padding:0px; min-width:"..spacing_w.."px; max-width:"..spacing_w.."px; min-height:"..spacing_h.."px; max-height:"..spacing_h.."px; overflow:hidden;' height="..spacing_h.." width="..spacing_h.." colspan="..colspan.." rowspan="..rowspan..">")
				table.insert(html,"<div style='width:"..td_w.."px; height:"..td_h.."px; overflow:hidden;'>"..element_locations[col.."x"..row].."</div>")
				table.insert(html,"</td>")
			else
				table.insert(html,"<td style='padding:0px; min-width:"..spacing_w.."px; max-width:"..spacing_w.."px; min-height:"..spacing_h.."px; max-height:"..spacing_h.."px; overflow:hidden;' height="..spacing_h.." width="..spacing_w.."></td>")
			end
		end
		table.insert(html,"</tr>")
	end
	table.insert(html,"</table>")

	res.html = table.concat(html,"")
	res.log = ""

	return res
end
-----------------------------------------------------
function c_span_pairs(conf)

	local field = conf.field																	-- The (numeric) field that will be used to do delta comparisons. 
	local span = conf.span																		-- The smallest delta value for a pair to qualify.
	local brief = get_default(conf.brief, false)												-- Whether the pairs are printed to the output
	local print_fields = conf.print_fields or {'gccode', 'visitdate', 'cache_name', field }		-- The fields of the caches to print out.
	local limit = get_default(conf.limit, 1)													-- The number of pairs required.
	local logic_short_circuit = get_default(conf.logic_short_circuit, false)					-- If you reach limit pairs, then don't process further
	local cmp_op = get_default(conf.cmp, "gte")													-- The logic comparison done to get matching pairs.
	local was_short_circuit = false

	local filter = FilterFromConfig(conf)
	
	error_if(field == nil, "Must supply 'field'")
	error_if(span == nil, "Must supply 'span'")
	error_if(cmp_op ~= 'eq' and cmp_op ~= 'gt' and cmp_op ~= 'gte', "Only eq/gt/gte are allowed cmp values. If you need something else, contact bmuzzin.")

	local fetch_fields = array_join( print_fields, {'gccode', field } )
	local finds = GetCombinedFinds(profileId, { lookup_cache=conf.lookup_cache,transforms=conf.transforms,fields = fetch_fields, order = 'OLDESTFIRST', filter = filter, includeLabCaches=conf.include_labs, gethides=conf.gethides })

	-- Sort the finds by their value of the field (descending).
	table.sort(finds, function(f1, f2) return f1[field] > f2[field] end)

	local pairs = {}
	local all_caches = {}
	local pairs_html = {}
	local pairs_text = {}
	local remaining_finds = TableCopy(finds)

	-- Now iterate over the pairs. Could this be more efficient? (n^n*logn on the user's number of finds)
	while #remaining_finds > 1 do
		local current_find = remaining_finds[1]
		table.remove(remaining_finds,1)

		-- quick out if the comparision is impossible. Can't do this for lt, lte or ne.
		if op=='eq' or op == 'gt' or 'gte' then
			local max_d = current_find[field]-remaining_finds[#remaining_finds][field]
			-- maximum delta will only get smaller, so we will not find a pair from now on.
			if max_d < span then
				DebugPrint("span between " .. current_find.gccode .. " and " .. remaining_finds[#remaining_finds].gccode .. " is " .. max_d .. " which is less than " .. span .. " thus there will not be any more matches.\n")
				break
			end
		end

		local pair_index = binary_search(remaining_finds, function(match) return current_find[field]-match[field] end, cmp_op, span)
		if pair_index >= 1 then
			local matching_find = remaining_finds[pair_index]
			local d = current_find[field] - matching_find[field]
			table.remove(remaining_finds, pair_index)			
			table.insert(pairs, {current_find, matching_find})
			table.insert(all_caches, current_find)
			table.insert(all_caches, matching_find)
			if not brief then
				table.insert(pairs_html, "Pairs span for "..field.." is " .. d .. ":")
				table.insert(pairs_html, PrintFindsHtml(pairs[#pairs], 2, print_fields))
				table.insert(pairs_text, "Pairs span for "..field.." is " .. d .. ":")
				table.insert(pairs_text, PrintFindsText(pairs[#pairs], 2, print_fields))
			end
		end

		if logic_short_circuit and #pairs >= limit then
			was_short_circuit = true
			break
		end
	end

    local res = {}
	res.ok = #pairs >= limit

	local result_text = ok_text(res.ok) .. ": You had " .. #pairs .. (was_short_circuit and " (truncated) " or "") .. " pairs, out of a required " .. limit
	table.insert(pairs_text, 1, result_text .. "\n")
	table.insert(pairs_html, 1, result_text .. "<br/>")

    res.log = ""
    res.html = ""
    res.slog = table.concat(pairs_text, "\n")
    res.shtml = table.concat(pairs_html, "<br/>")
	res.caches = all_caches
	res.points = calculate_points(conf, res.ok, #pairs)
	
	return res
end
-----------------------------------------------------
function lookup(f,arg,filter,opt)
  local res=nil

  if f==nil then
	if conf.default_func ~= nil then
		f = conf.default_func
		DebugPrint("'func' was not specified, using default_func\n")
	else
		error("No 'func' specified in the tag config.")
	end
  end

  -- Based on the operation, you can mangle in global opt or conf/arg kvps. Usually only useful if you're trying to conserve tag space with repepetive operations.
  if g_globals[f] ~= nil then
	if (g_globals[f].opt ~= nil) then
		opt = table_join(g_globals[f].opt, opt or {})
	end
	if (g_globals[f].filter ~= nil) then
		filter = table_join(g_globals[f].filter, filter or {})
	end
	if (g_globals[f].conf ~= nil) then
		arg = table_join(g_globals[f].conf, arg or {})
	end
  end

  DebugPrint(indent .. "processing " .. f .. "(conf:" .. dump(arg) .. (opt ~= nil and ("opt:" .. dump(opt)) or "") .. ")\n")

  if f=="or"  then
    res=l_or(arg,filter,opt)
  elseif f=="and"  then
    res=l_and(arg,filter,opt)
  elseif f=="points"  then
    res=l_points(arg,filter,opt)
  elseif f=="at_least"  then
    res=l_at_least(arg,filter,opt)
   elseif f=="in_a_year"  then
    res=l_in_a_year(arg,filter,opt)
   elseif f=="in_a_hidden_year"  then
    res=l_in_a_hidden_year(arg,filter,opt)
   elseif f=="bingo" or f=="bingo2" then
    res=l_bingo(arg,filter,opt)
   elseif f=="sameCRC"  then
    res=l_sameCRC(arg,filter,opt)
   elseif f=="same"  then
    res=l_same(arg,filter,opt)
   elseif f=="for_each" then
	res=l_same(arg,filter,opt)	-- for_each is ... actually the same as same.
   elseif f=='visit_date' then
    res=l_visit_date(arg, filter, opt)
   elseif f=='generate' then
    res=l_generate(arg)
  elseif f=="number" then
    res=c_number(arg)
  elseif f=="range" then
    res=c_range(arg)
  elseif f=="calendar" then
    res=c_calendar(arg)
  elseif f=="oldest_calendar" then
    res=c_oldest_calendar(arg)
  elseif f=="topfav_calendar" then
    res=c_topfav_calendar(arg)
  elseif f=="top_elevation_calendar" then
    res=c_top_elevation_calendar(arg)
  elseif f=="jasmer" then
    res=c_jasmer(arg)
  elseif f=="DT" then
    res=c_DT(arg)
  elseif f=="adv_number" then
    res=c_adv_number(arg)
   elseif f=="streak" then
    res=c_streak(arg)
   elseif f=="attributes" then
    res=c_attributes(arg)
   elseif f=="fp" then
    res=c_fp(arg)
   elseif f=="crc" then
    res=c_crc(arg)
   elseif f=="souvenir" then
    res=c_souvenir(arg)
   elseif f=="tb" then
    res=c_tb(arg)
   elseif f=="regex" then
    res=c_regex(arg)
   elseif f=="words" then
    res=c_words(arg)
   elseif f=="distance" then
    res=c_distance(arg)
   elseif f=="types" then
    error("'types' function is no longer supported. You can get similiar functionality from either 'grid' or 'same'+'number'.")
   elseif f=="elevation" then
    res=c_elevation(arg)
  elseif f=="age" then
    res=c_age(arg)
   elseif f=="ok" then
    res=c_ok(arg)
   elseif f=="info" then
    res=c_info(arg)
   elseif f=="maybe" then
    error("'maybe' function is no longer supported. This script checks that you pass or you don't.")
   elseif f=="oldest" then
    res=c_oldest(arg)
   elseif f=="topfav" then
	res=c_topfav(arg)
   elseif f=="top_elevation" then
	res=c_top_elevation(arg)
   elseif f=="oldest_fizzy" then
    res=c_oldest_fizzy(arg)
   elseif f=="topfav_fizzy" then
	res=c_topfav_fizzy(arg)
   elseif f=="top_elevation_fizzy" then
	res=c_top_elevation_fizzy(arg)
   elseif f=="continents" then
	res=c_continents(arg)
   elseif f=="maxdist" then
	res=c_maxdist(arg)
   elseif f=="grid" then
	res=c_grid(arg)
   elseif f=="samex_diffy" then
	res=c_samex_diffy(arg)
   elseif f=="sequence" then
	res=c_sequence(arg)
   elseif f=='histogram' then
	res=c_histogram(arg)
   elseif f=='unique_value' then
	res=c_unique_value(arg)
   elseif f=='fizzy_complete' then
	res=c_fizzy_complete(arg)
   elseif f=='from_home' then
	res=c_from_home(arg)
   elseif f=='lonely' then
	res=c_lonely(arg)
   elseif f=='generic_fizzy' then
	res=c_generic_fizzy(arg)
   elseif f=='generic_calendar' then
	res=c_generic_calendar(arg)
   elseif f=='remote' then
	res=c_remote(arg)
   elseif f=='unique_groups' then
	res=c_unique_groups(arg)
   elseif f=='venn' then
	res=c_venn(arg)
   elseif f=='span_pairs' then
	res=c_span_pairs(arg)
  else
    error ("Missing function:"..f.."\n")
  end

  if res == nil or res.slog == nil or res.shtml ==nil or res.log ==nil or res.html == nil or res.ok ==nil then
	error ("func " .. f .. " did not return a proper result. " .. dump(res) .. "\n")
  end

  return res
end
-----------------------------------------------------
function truncate_html_if_required(html)	

	function split_pattern(s,p)
		local splits = {}
		local i,j
		local lp = string.len(p)
		local ls = string.len(s)
		local lasti = 1
		i=stringx.lfind(s,p)
		while (i) do
			table.insert(splits,string.sub(s,lasti,i))
			table.insert(splits,p)
			lasti = i
			i = stringx.lfind(s,p,i+lp+1)
		end
		if lasti < ls then
			table.insert(splits,string.sub(s,lasti))
		end
		return splits
	end

	local html_max = 850*1024 -- by trial and error. 900 is "sometimes" too large.

	local html_len = string.len(html)
	if conf.allow_emoji_truncation and html_len > html_max then
		html = string.gsub(html, '<img src="/images/check16%.png">', '✅')
	end

	html_len = string.len(html)
	if html_len > html_max then

		DebugPrint("HTML output is too large ("..html_len..", max="..html_max.."). Attempting to truncate.\n")

		-- Assume that table tags are the cause of huge output. Start by chopping out table lines, and putting a "truncated" message.
		local tables = split_pattern(html, "</table>")
		local trunc_line = "<b>NOTE: This table has been truncated because the HTML output was too large.</b><br/>"
		 
		if #tables > 1 then
			DebugPrint("HTML contains " .. #tables - 1 .. " table(s). Attempting to shorten them\n")
			for table_index = #tables-1,1,-1 do
				-- There was at least one table. Truncate the last one by chopping rows, until we're under the limit.
				local new_last_table = tables[table_index]
				local table_rows = split_pattern(new_last_table,"</tr>")
				html_len = html_len + string.len(trunc_line) -- pretend we've already added it in.
				local initial_rows = #table_rows
				while (html_len > html_max and #table_rows > 2) do
					-- NOTE: Last entry is just an empty </tr>
					html_len = html_len - string.len(table_rows[#table_rows-1])
					table.remove(table_rows,#table_rows-1)
				end
				local removed_rows = initial_rows - #table_rows
				DebugPrint("Removed " .. initial_rows - #table_rows .. " rows (out of "..initial_rows .. ") from table " .. table_index.."\n")
				if removed_rows > 0 then
					table.insert(table_rows,1,trunc_line)
					tables[table_index] = table.concat(table_rows,"")
				end
			end
			html = table.concat(tables,"")
		else
			-- There weren't any tables... don't think this is going to ever happen... but if it does, let the user know to ask me.
			html = "HTML output was too large, and truncating non-table output is unsupported. Contact bmuzzin and ask for this to be supported.\n"
		end

		if g_conf.debug then
			local l = string.len(html)
			DebugPrint("HTML output now ("..l..", tail=" .. string.sub(html,l-100) .. ".\n")
		end
	end	

	return html
end
-----------------------------------------------------
DebugPrint('Got profile name (id='..profileId..') '.. profileName.. "\n")
DebugPrint("https://project-gc.com/Tools/Challenges?viewDebugLog="..tostring(args[1]['environmentSettings']['token']).. "\n")

local res
for i=1,1,1 do
  res=lookup(conf.func,conf.conf,conf.filter,conf.opt)
end

if g_conf.generate_map then
	if res.map ~= nil then
		error("You specified both generating a map for some sub-function, and globally. Choose just one.")
	end
	local map = { caches = {}, polygons = {}, circles = {}, correctedCoordinatesInUse = false } 
	for _, mapcache in ipairs(res.caches or {}) do
		table.insert(map.caches, mapcache.gccode)			
	end

	-- Map all the polysets in the cache, because presumably you tested something against them.
	for filename, polyset in pairs(g_polyset_cache) do
		for setname, polyregion in pairs(polyset) do
			if polyregion.accessed and polyregion.polypoints ~= nil then
				for _,polygon_list in ipairs(polyregion.polypoints) do
					local region_label = filename..":"..setname
					local mappoly = {}
					mappoly.polygon = polygon_list
					mappoly.urlText = region_label
					mappoly.color = "green"
					mappoly.opacity = 0.5
					mappoly.fillOpacity = 0.1
					mappoly.htmlTooltip = tipregion_label
					DebugPrint("Mapping region: " .. region_label .. "\n")
					table.insert(map.polygons,mappoly)
				end
			else
				DebugPrint(filename .. ":" .. setname .. " polypoints was nil.\n")
			end
		end
	end

	res.map = map
end

local ok=res.ok
local log=res.slog.."\n\n"..res.log
local html=res.shtml.."<br/>"..res.html
local map = res.map

html = truncate_html_if_required(html)

return { ok = ok, log = log, html = html, map = map }
